def _run_report_load_options():
    return (
        selectinload(Run.assessment_chain),
        selectinload(Run.engagement).selectinload(Engagement.scopes),
        selectinload(Run.engagement).selectinload(Engagement.inventory_snapshots),
        selectinload(Run.profile),
        selectinload(Run.bound_pack).selectinload(CapabilityPack.validation_results),
        selectinload(Run.bound_pack).selectinload(CapabilityPack.approvals),
        selectinload(Run.bound_pack).selectinload(CapabilityPack.deployments),
        selectinload(Run.bound_pack_deployment),
        selectinload(Run.approvals),
        selectinload(Run.findings),
        selectinload(Run.findings).selectinload(Finding.remediation),
        selectinload(Run.findings).selectinload(Finding.validation_records),
        selectinload(Run.finding_chains),
        selectinload(Run.rationale_ledger_entries).selectinload(RationaleLedgerEntry.context_document),
        selectinload(Run.tasks)
        .selectinload(Task.executions)
        .selectinload(ToolExecution.artifacts),
    )


def load_run_report(session: Session, run_id: UUID | str) -> Run | None:
    return session.scalar(
        select(Run)
        .options(*_run_report_load_options())
        .where(Run.id == run_id, Run.deleted_at.is_(None))
    )


def load_assessment_chain_report_runs(session: Session, chain_id: UUID | str) -> list[Run]:
    return list(
        session.scalars(
            select(Run)
            .options(*_run_report_load_options())
            .where(Run.assessment_chain_id == chain_id, Run.deleted_at.is_(None))
            .order_by(Run.created_at.asc(), Run.id.asc())
        )
    )


def effective_inventory_snapshot_for_run(run: Run):
    engagement = run.engagement
    if engagement is None:
        return None

    snapshots = list(engagement.inventory_snapshots or [])
    run_id = str(run.id)
    derived = sorted(
        (
            snapshot
            for snapshot in snapshots
            if str(snapshot.raw_inputs_json.get("run_id") or "") == run_id
        ),
        key=lambda snapshot: (snapshot.created_at, snapshot.id.hex),
        reverse=True,
    )
    if derived:
        aggregated = aggregate_inventory_snapshots(derived)
        if aggregated is not None:
            representative = derived[0]
            return SimpleNamespace(
                id=representative.id,
                engagement_id=representative.engagement_id,
                requested_by=representative.requested_by,
                status=representative.status,
                raw_inputs_json={"run_id": run_id, "aggregated_snapshot_count": len(derived)},
                normalized_inventory_json=aggregated["normalized_inventory_json"],
                summary_json=aggregated["summary_json"],
                source_tools_json=aggregated["source_tools_json"],
                environment_notes_json=aggregated["environment_notes_json"],
                assumptions_json=aggregated["assumptions_json"],
                confidence_score=aggregated["confidence_score"],
                created_at=representative.created_at,
            )
        return derived[0]

    if run.source_inventory_snapshot_id is not None:
        for snapshot in snapshots:
            if snapshot.id == run.source_inventory_snapshot_id:
                return snapshot
    return None


def _short_run_id(run: Run) -> str:
    return str(run.id).split("-", 1)[0]


def _report_date_range(run: Run) -> str:
    return f"{run.created_at.isoformat()} to {run.updated_at.isoformat()}"


def _authorized_by(run: Run, approvals: list[Approval]) -> str:
    approvers = sorted(
        {
            str(approval.approver_id).strip()
            for approval in approvals
            if str(approval.approver_id or "").strip()
        }
    )
    if approvers:
        return ", ".join(approvers)
    if str(run.requested_by or "").strip():
        return str(run.requested_by)
    return "Not recorded"


def _format_count_map_markdown(counts: object, *, empty_label: str = "None recorded") -> list[str]:
    if not isinstance(counts, dict) or not counts:
        return [f"- {empty_label}"]
    lines = ["| Category | Count |", "| --- | ---: |"]
    for key in sorted(counts, key=lambda item: SEVERITY_ORDER.get(str(item), 99)):
        lines.append(f"| {_humanize_key(str(key))} | {counts[key]} |")
    return lines


def _format_count_map_html(counts: object, *, empty_label: str = "None recorded") -> str:
    if not isinstance(counts, dict) or not counts:
        return f"<p>{escape(empty_label)}</p>"
    rows = "".join(
        f"<tr><th>{escape(_humanize_key(str(key)))}</th><td>{escape(str(counts[key]))}</td></tr>"
        for key in sorted(counts, key=lambda item: SEVERITY_ORDER.get(str(item), 99))
    )
    return f"<table>{rows}</table>"


def _severity_rank(severity: str | None) -> int:
    return SEVERITY_ORDER.get(str(severity or "unknown").lower(), SEVERITY_ORDER["unknown"])


def _risk_score(findings: list[Finding]) -> float:
    weights = {"critical": 10.0, "high": 7.0, "medium": 4.0, "low": 1.5, "info": 0.0, "unknown": 0.0}
    score = sum(weights.get(str(finding.severity or "unknown").lower(), 0.0) for finding in findings)
    return round(min(10.0, score / 2.0), 1)


def _risk_level(score: float) -> str:
    if score >= 8.0:
        return "HIGH"
    if score >= 4.0:
        return "MEDIUM"
    if score > 0:
        return "LOW"
    return "INFORMATIONAL"


def _risk_bar(score: float) -> str:
    filled = max(0, min(10, int(round(score))))
    return "█" * filled + "░" * (10 - filled)


MANAGEMENT_INTERNAL_MARKER_RE = re.compile(
    r"(flag[_ -]?injected|flag captured|interactive[-_ ]exploit|run[-_ ]local|exec[-_ ]plan|"
    r"pre[-_ ]recon|exploit[-_ ]runner|grader|benchmark|fixture|smoke|debug|"
    r"sqlmap|nmap|zap|aegispt http status|xbow[-_a-z0-9{}]+|xben[-_a-z0-9]+|aegispt\{[^}]+\}|"
    r"\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b)",
    re.IGNORECASE,
)
MANAGEMENT_TECHNICAL_TITLE_RE = re.compile(
    r"\b(?:x-frame|xss|csrf|sql injection|path traversal|command injection|jwt|oauth|cookie|cve|csp|hsts|"
    r"fastapi|openapi|swagger|auto-docs|api docs|http status|status 200|baseline)\b",
    re.IGNORECASE,
)

