def _management_task_technique_key(task: Task) -> str | None:
    signal = _task_signal_text(task)
    for profile in MANAGEMENT_TECHNIQUE_PROFILES:
        keywords = tuple(str(keyword) for keyword in profile["keywords"])
        if _signals_match(signal, keywords):
            return str(profile["key"])
    return None


def _management_technique_facts(context: dict[str, object], *, language: str = "en") -> list[dict[str, object]]:
    tasks = [task for task in context.get("tasks", []) if isinstance(task, Task)]
    executed_tasks = [task for task in tasks if task.status in EXECUTED_TASK_STATUSES]
    matches: dict[str, list[Task]] = {}
    for task in executed_tasks:
        key = _management_task_technique_key(task)
        if key:
            matches.setdefault(key, []).append(task)

    technique_rows: list[dict[str, object]] = []
    for profile in MANAGEMENT_TECHNIQUE_PROFILES:
        key = str(profile["key"])
        matched_tasks = matches.get(key, [])
        if not matched_tasks:
            continue
        count = len(matched_tasks)
        if language == "nl":
            evidence = f"{count} vastgelegde check" + ("" if count == 1 else "s")
            technique_rows.append(
                {
                    "key": key,
                    "label": profile["label_nl"],
                    "plain": profile["plain_nl"],
                    "why": profile["why_nl"],
                    "standard": profile["standard_nl"],
                    "evidence": evidence,
                    "count": count,
                }
            )
        else:
            evidence = f"{count} recorded check" + ("" if count == 1 else "s")
            technique_rows.append(
                {
                    "key": key,
                    "label": profile["label"],
                    "plain": profile["plain"],
                    "why": profile["why"],
                    "standard": profile["standard"],
                    "evidence": evidence,
                    "count": count,
                }
            )

    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    if not technique_rows and findings:
        if language == "nl":
            return [
                {
                    "key": "evidence_review",
                    "label": "Bewijsbeoordeling",
                    "plain": "Beoordeelt opgeslagen bevindingen en gekoppelde bewijsstukken.",
                    "why": "Dit zorgt dat het rapport spreekt over vastgelegde resultaten, niet over losse signalen.",
                    "standard": "NIST SP 800-115 bewijsvoering en rapportagestructuur.",
                    "evidence": f"{len(findings)} opgeslagen bevindingen",
                    "count": len(findings),
                }
            ]
        return [
            {
                "key": "evidence_review",
                "label": "Evidence review",
                "plain": "Reviews saved findings and linked evidence records.",
                "why": "This keeps the report tied to recorded outcomes instead of loose signals.",
                "standard": "NIST SP 800-115 evidence handling and reporting structure.",
                "evidence": f"{len(findings)} saved findings",
                "count": len(findings),
            }
        ]

    if not technique_rows:
        if language == "nl":
            return [
                {
                    "key": "scope_review",
                    "label": "Scopebeoordeling",
                    "plain": "Controleert de vastgelegde scope en rapportgrenzen.",
                    "why": "Dit voorkomt dat het rapport meer claimt dan is getest.",
                    "standard": "PTES voorbereiding en NIST SP 800-115 rapportagegrenzen.",
                    "evidence": "Geen uitgevoerde checks vastgelegd",
                    "count": 0,
                }
            ]
        return [
            {
                "key": "scope_review",
                "label": "Scope review",
                "plain": "Checks the recorded scope and report boundary.",
                "why": "This prevents the report from claiming more than was tested.",
                "standard": "PTES preparation and NIST SP 800-115 reporting boundary.",
                "evidence": "No executed checks recorded",
                "count": 0,
            }
        ]
    return technique_rows


def _management_attack_tone(severity: str | None) -> str:
    sev = str(severity or "").lower()
    if sev == "critical":
        return "critical"
    if sev == "high":
        return "high"
    if sev == "medium":
        return "medium"
    if sev == "low":
        return "low"
    return "info"


