def generate_management_nl_report(
    run: Run,
    *,
    settings: Settings,
    session: object | None = None,
    context: dict[str, object] | None = None,
) -> str:
    """Generate a Dutch management report, using ChatGPT when available and template as fallback."""
    ctx = context or report_context(run)
    provider = effective_ai_provider_name(settings, settings.ai_report_drafting_provider)
    use_chatgpt = (
        settings.ai_report_drafting_enabled
        and provider == CHATGPT_OAUTH_PROVIDER
        and session is not None
    )
    if use_chatgpt:
        try:
            findings = [f for f in ctx.get("findings", []) if isinstance(f, Finding)]
            severity_counts: dict[str, int] = ctx.get("findings_by_severity", {})  # type: ignore[assignment]
            target = _management_scope_label(ctx, language="nl")
            decision_facts = _management_decision_facts(run, ctx, language="nl")
            story_context = _management_assessment_story_context(run, ctx, language="nl")
            technique_summary = "\n".join(
                f"- {item['label']}: {item['plain']} Relevantie: {item['why']} Standaard: {item['standard']}"
                for item in story_context["techniques"]
                if isinstance(item, dict)
            )
            attacker_summary = "\n".join(
                f"- {item['theme']}: aanvallerpad={item['attacker']} zakelijke zorg={item['business']} bewijs={item['proof']}"
                for item in story_context["attacker_story"]
                if isinstance(item, dict)
            )
            remediation_summary = "\n".join(
                f"- {item['theme']}: engineering={item['engineering']} it_ops={item['it']} klaar={item['done']}"
                for item in story_context["remediation_tracks"]
                if isinstance(item, dict)
            )
            standards_summary = "\n".join(
                f"- {item['badge']} {item['label']}: {item['meaning']}"
                for item in story_context["standards_badges"]
                if isinstance(item, dict)
            )
            origin_summary = "\n".join(
                line
                for line in _management_test_origin_markdown_lines(run, ctx, language="nl")
                if line and not line.startswith("##")
            )
            findings_summary = "\n".join(
                f"- [{str(f.severity or '?').upper()}] {_management_finding_title(f, language='nl')}: "
                f"{_management_business_impact(f, language='nl')} "
                f"Aanpak: {_management_remediation_action(f, language='nl')}"
                for f in findings[:30]
            )
            prompt = (
                f"Beoordeeld systeem: {target}\n"
                f"Aantal bevindingen: {len(findings)}\n"
                f"Ernstverdeling: kritiek={severity_counts.get('critical',0)}, "
                f"hoog={severity_counts.get('high',0)}, "
                f"gemiddeld={severity_counts.get('medium',0)}, "
                f"laag={severity_counts.get('low',0)}\n\n"
                "Managementbesluit (gestructureerde feiten, niet wijzigen):\n"
                f"- Status: {decision_facts['verdict']}\n"
                f"- Besluit: {decision_facts['decision']}\n"
                f"- Bewijsbasis: {decision_facts['evidence']}\n"
                f"- Getest: {decision_facts['tested']}\n"
                f"- Niet geclaimd: {' '.join(str(item) for item in decision_facts['not_claimed'])}\n"
                f"- Eerste acties: {'; '.join(str(item) for item in decision_facts['first_actions'])}\n\n"
                "Aanvalskaart en techniek-feiten (gestructureerde feiten, niet wijzigen):\n"
                f"- Route: {story_context['route']}\n"
                f"- Verhaal: {story_context['headline']}\n"
                f"- Wat getest: {story_context['tested_story']}\n"
                f"- Technieken:\n{technique_summary}\n\n"
                "Aanvallerpad in gewone taal (gestructureerde feiten, niet wijzigen):\n"
                f"{attacker_summary}\n\n"
                "Herstelpad voor IT en engineering (gestructureerde feiten, niet wijzigen):\n"
                f"{remediation_summary}\n\n"
                "Totstandkoming en bewijsbasis (gestructureerde feiten, niet wijzigen):\n"
                f"{origin_summary}\n\n"
                "Normenkader en iconen/badges (gestructureerde feiten, niet wijzigen):\n"
                f"{standards_summary}\n\n"
                f"Bevindingen (per ernst):\n{findings_summary}\n\n"
                "Schrijf een professioneel managementrapport in het Nederlands voor niet-technische directeuren. "
                "Gebruik begrijpelijke taal zonder technisch jargon. "
                "Gebruik geen run-id's, benchmarknamen, XBEN/XBOW-markers, flagwaarden, toolnamen of runnernamen. "
                "Leg per bevinding de zakelijke impact uit: wat kan een aanvaller doen, wat is het risico voor het bedrijf? "
                "Leg apart uit wat de aanvaller concreet zou moeten doen en wat engineers en IT/Ops concreet moeten doen om dit te herstellen. "
                "Neem een visuele/tekstuele sectie 'Aanvalskaart' op die uitlegt hoe de test van scope naar bewijs en besluit liep. "
                "Neem een sectie 'Gebruikte technieken in gewone taal' op en leg per techniek uit wat deze deed en waarom dat relevant is. "
                "Neem een sectie 'Hoe deze test tot stand kwam' op en vermeld dat losse terminaluitvoer of alleen URL's geen managementbevinding zijn. "
                f"Neem expliciet een sectie 'Welke standaarden zijn gebruikt?' op met PTES, OWASP WSTG {WSTG_STABLE_VERSION}, "
                f"NIST SP 800-115 en optioneel OWASP ASVS {ASVS_STABLE_VERSION} waar bevindingen zijn gekoppeld. "
                "Toon de standaarden als herkenbare badges zoals [PTES], [WSTG], [NIST] en [ASVS]. "
                "Maak duidelijk dat dit geen certificering is, maar een evidence-first beveiligingsbeoordeling. "
                "Structuur het rapport met: Samenvatting, Wat is getest, Bevindingen (in gewone taal), "
                "Aanvalskaart, Waarom dit ernstig is, Wat kan een aanvaller hiermee, Wat moeten IT en engineering doen, "
                "Hoe deze test tot stand kwam, Gebruikte technieken in gewone taal, Welke standaarden zijn gebruikt, Prioriteiten, Vervolgstappen. "
                "Retourneer ALLEEN een JSON object met key 'draft_markdown' die de volledige Markdown tekst bevat."
            )
            result_payload = send_chatgpt_backend_streaming_json_request(  # type: ignore[arg-type]
                session=session,
                engagement_id=run.engagement_id,
                settings=settings,
                model=str(settings.chatgpt_oauth_model or "gpt-5.4"),
                instructions=(
                    "Je bent een ervaren cybersecurity consultant. Genereer een Nederlandstalig managementrapport "
                    "voor een niet-technisch publiek. Retourneer een JSON object met key 'draft_markdown' "
                    "met de volledige Markdown inhoud. Geen andere keys, geen uitleg buiten het JSON object."
                ),
                input_items=[
                    {
                        "type": "message",
                        "role": "user",
                        "content": [{"type": "input_text", "text": prompt}],
                    }
                ],
            )
            if isinstance(result_payload, dict) and result_payload.get("draft_markdown"):
                return str(result_payload["draft_markdown"])
        except Exception:
            pass  # Fall through to template

    # Template fallback
    return _render_management_nl_markdown(run, ctx)


def _render_management_nl_markdown(run: Run, context: dict[str, object]) -> str:
    findings = [f for f in context.get("findings", []) if isinstance(f, Finding)]
    severity_counts: dict[str, int] = context.get("findings_by_severity", {})  # type: ignore[assignment]
    target = _management_scope_label(context, language="nl")
    client = _management_safe_text(context.get("client_name"), fallback="de opdrachtgever")
    run_date = _format_management_date_nl(run.created_at)
    high_crit = [f for f in findings if str(f.severity or "").lower() in {"critical", "high"}]
    medium = [f for f in findings if str(f.severity or "").lower() == "medium"]
    management_rows = _management_cluster_rows(findings, language="nl")
    decision_facts = _management_decision_facts(run, context, language="nl")
    story_context = _management_assessment_story_context(run, context, language="nl")

    # Overall risk label
    if any(str(f.severity or "").lower() == "critical" for f in findings):
        risk_label = "🔴 KRITIEK"
        risk_text = (
            "De beveiligingsscan heeft kritieke kwetsbaarheden aangetroffen. "
            "Direct ingrijpen is noodzakelijk om ernstige schade te voorkomen."
        )
    elif high_crit:
        risk_label = "🟠 HOOG"
        risk_text = (
            "De beveiligingsscan heeft hoog-risico kwetsbaarheden aangetroffen. "
            "Snel handelen is sterk aangeraden."
        )
    elif medium:
        risk_label = "🟡 GEMIDDELD"
        risk_text = (
            "De scan heeft kwetsbaarheden aangetroffen met gemiddeld risico. "
            "Herstel is aan te raden binnen de komende weken."
        )
    else:
        risk_label = "🟢 LAAG / SCHOON"
        risk_text = (
            "Er zijn geen hoog- of kritiek-risico bevindingen vastgelegd. "
            "Dit is geen garantie dat er geen risico bestaat; het betekent dat deze testronde "
            "geen zwaarwegende bevinding heeft opgeleverd."
        )
    follow_up_steps = (
        [
            f"{index}. **{row['title']}** — {row['action']}"
            for index, row in enumerate(management_rows[:4], start=1)
        ]
        if management_rows
        else [
            "1. **Monitoring behouden** — blijf wijzigingen volgen en hertest na belangrijke releases.",
            "2. **Bewijs bewaren** — bewaar de rapportage als nulmeting voor toekomstige beoordelingen.",
        ]
    )
    follow_up_steps.append(
        f"{len(follow_up_steps) + 1}. **Hertest na herstel** — laat na wijzigingen controleren "
        "of de risico's daadwerkelijk zijn opgelost."
    )

    lines = [
        "# Managementrapport Beveiligingsbeoordeling",
        "",
        f"**Opgesteld voor:** {client}  ",
        f"**Datum:** {run_date}  ",
        f"**Beoordeeld systeem:** {target}  ",
        f"**Algeheel risiconiveau:** {risk_label}",
        "",
        "---",
        "",
        "## Samenvatting in het kort",
        "",
        risk_text,
        "",
        f"In totaal zijn **{len(findings)} bevindingen** vastgesteld.",
        "",
        "| Ernst | Aantal | Wat betekent dit? |",
        "|-------|--------|-------------------|",
    ]
    for sev in ("critical", "high", "medium", "low", "info"):
        count = severity_counts.get(sev, 0)
        if count:
            label = _NL_SEVERITY_LABELS.get(sev, sev.capitalize())
            advice = _NL_SEVERITY_ADVICE.get(sev, "")
            lines.append(f"| **{label}** | {count} | {advice} |")
    lines += [
        "",
        "---",
        "",
        *_management_risk_picture_markdown_lines(context, language="nl"),
        "---",
        "",
        *_management_decision_markdown_lines(decision_facts, language="nl"),
        "---",
        "",
        *_management_story_markdown_lines(story_context, language="nl"),
        "---",
        "",
        *_management_attacker_markdown_lines(context, language="nl"),
        "---",
        "",
        *_management_remediation_markdown_lines(context, language="nl"),
        "---",
        "",
        *_management_test_origin_markdown_lines(run, context, language="nl"),
        "---",
        "",
        *_management_standards_markdown_lines(language="nl"),
        "",
        "---",
        "",
        "## Wat hebben we gevonden?",
        "",
    ]

    if not management_rows:
        lines.append("Geen bevindingen aangetroffen.")
    else:
        for row in management_rows[:10]:
            sev = str(row.get("severity") or "info").lower()
            nl_sev = _NL_SEVERITY_LABELS.get(sev, sev.capitalize())
            title = str(row.get("title") or "Onbekend")
            explanation = str(row.get("impact") or "Zie de technische bijlage voor details.")
            action = str(row.get("action") or "Plan herstel en hertest op basis van het gekoppelde bewijs.")
            count_str = f" ({row['count']}×)" if int(row.get("count", 1)) > 1 else ""
            lines += [
                f"### {nl_sev}: {title}{count_str}",
                "",
                f"**Zakelijke betekenis:** {explanation}",
                "",
                f"**Aanpak:** {action}",
                "",
            ]

    lines += [
        "---",
        "",
        "## Wat moet er als eerste worden gedaan?",
        "",
    ]
    if high_crit:
        lines.append("De volgende bevindingen vereisen **directe aandacht** van het ontwikkelteam:")
        lines.append("")
        for row in management_rows[:5]:
            if str(row.get("severity") or "").lower() not in {"critical", "high"}:
                continue
            sev_nl = _NL_SEVERITY_LABELS.get(str(row.get("severity") or "").lower(), "?")
            lines.append(f"- **[{sev_nl}]** {row['title']} — {row['action']}")
        lines.append("")
    else:
        lines.append("Er zijn geen hoog- of kritiek-risico bevindingen die directe actie vereisen.")
        lines.append("")

    lines += [
        "---",
        "",
        "## Aanbevolen vervolgstappen",
        "",
        *follow_up_steps,
        "",
        "---",
        "",
        "## Disclaimer",
        "",
        "_Dit rapport is gebaseerd op geautomatiseerd bewijs uit de AegisPT beveiligingsscan. "
        "De bevindingen zijn indicatief en dienen te worden beoordeeld door een gekwalificeerde beveiligingsspecialist. "
        "Het rapport vervangt geen handmatige penetratietest en garandeert geen volledige afwezigheid van kwetsbaarheden._",
        "",
    ]
    return "\n".join(lines)


def _deduplicated_finding_rows(findings: list[Finding]) -> list[dict[str, object]]:
    grouped: dict[str, list[Finding]] = {}
    for finding in findings:
        key = str(finding.title or "Untitled finding").strip().lower()
        grouped.setdefault(key, []).append(finding)

    rows: list[dict[str, object]] = []
    for group in grouped.values():
        ordered = sorted(group, key=lambda finding: (_severity_rank(finding.severity), finding.target_id, finding.id.hex))
        representative = ordered[0]
        targets = sorted({str(finding.target_id or "Not recorded") for finding in ordered})
        evidence_refs = sorted({str(finding.evidence_ref or "") for finding in ordered if str(finding.evidence_ref or "").strip()})
        rows.append(
            {
                "title": representative.title,
                "severity": representative.severity,
                "status": representative.status,
                "priority": remediation_priority_for_finding(representative),
                "count": len(ordered),
                "targets": targets,
                "evidence_refs": evidence_refs,
                "representative": representative,
                "summary": representative.summary or "",
            }
        )
    return sorted(rows, key=lambda row: (_severity_rank(str(row["severity"])), str(row["title"]).lower()))


def _markdown_table_cell(value: object) -> str:
    return re.sub(r"\s+", " ", str(value or "").replace("|", "/")).strip() or "Not recorded"


def _render_remediation_priority_table_markdown(
    findings: list[Finding],
    *,
    management: bool = False,
    language: str = "en",
) -> list[str]:
    if management:
        rows = _management_cluster_rows(findings, language=language)[:5]
        lines = [
            "| Priority | Theme | Severity | Business Impact | Recommended Action |",
            "| --- | --- | --- | --- | --- |",
        ]
        if not rows:
            lines.append("| Review | No confirmed findings recorded | Informational | No finding-backed impact recorded | Continue planned monitoring and retest after material changes. |")
            return lines
        for row in rows:
            representative = row["representative"]
            if not isinstance(representative, Finding):
                continue
            severity = str(row["severity"])
            count = int(row.get("count", 1))
            title = str(row["title"])
            count_suffix = f" ({count} related findings)" if count > 1 else ""
            lines.append(
                "| "
                f"{_markdown_table_cell(remediation_priority_for_finding(representative))} | "
                f"{_markdown_table_cell(title + count_suffix)} | "
                f"{_markdown_table_cell(_humanize_key(severity))} | "
                f"{_markdown_table_cell(row['impact'])} | "
                f"{_markdown_table_cell(row['action'])} |"
            )
        return lines

    rows = _deduplicated_finding_rows(findings)[:5]
    lines = ["| Priority | Finding | Severity | Effort | Impact |", "| --- | --- | --- | --- | --- |"]
    if not rows:
        lines.append("| Review | No confirmed findings recorded | Informational | None | No finding-backed impact recorded |")
        return lines
    for row in rows:
        severity = str(row["severity"])
        effort = "High" if severity in {"critical", "high"} else "Medium" if severity == "medium" else "Low"
        impact = f"{row['count']} instance{'s' if row['count'] != 1 else ''} across {', '.join(row['targets'])}"
        lines.append(f"| {row['priority']} | {row['title']} | {_humanize_key(severity)} | {effort} | {impact} |")
    return lines


def _render_remediation_priority_table_html(findings: list[Finding], *, management: bool = False) -> str:
    if management:
        rows = _management_cluster_rows(findings)[:5]
        if not rows:
            body = (
                "<tr><td>Review</td><td>No confirmed findings recorded</td><td>Informational</td>"
                "<td>No finding-backed impact recorded</td><td>Continue planned monitoring and retest after material changes.</td></tr>"
            )
        else:
            body = ""
            for row in rows:
                representative = row["representative"]
                if not isinstance(representative, Finding):
                    continue
                severity = str(row["severity"])
                count = int(row.get("count", 1))
                count_suffix = f" ({count} related findings)" if count > 1 else ""
                body += (
                    "<tr>"
                    f"<td>{escape(remediation_priority_for_finding(representative))}</td>"
                    f"<td>{escape(str(row['title']) + count_suffix)}</td>"
                    f"<td>{escape(_humanize_key(severity))}</td>"
                    f"<td>{escape(str(row['impact']))}</td>"
                    f"<td>{escape(str(row['action']))}</td>"
                    "</tr>"
                )
        return (
            "<table><thead><tr><th>Priority</th><th>Theme</th><th>Severity</th>"
            "<th>Business Impact</th><th>Recommended Action</th></tr></thead>"
            f"<tbody>{body}</tbody></table>"
        )

    rows = _deduplicated_finding_rows(findings)[:5]
    if not rows:
        body = "<tr><td>Review</td><td>No confirmed findings recorded</td><td>Informational</td><td>None</td><td>No finding-backed impact recorded</td></tr>"
    else:
        body = ""
        for row in rows:
            severity = str(row["severity"])
            effort = "High" if severity in {"critical", "high"} else "Medium" if severity == "medium" else "Low"
            impact = f"{row['count']} instance{'s' if row['count'] != 1 else ''} across {', '.join(row['targets'])}"
            body += (
                "<tr>"
                f"<td>{escape(str(row['priority']))}</td>"
                f"<td>{escape(str(row['title']))}</td>"
                f"<td>{escape(_humanize_key(severity))}</td>"
                f"<td>{escape(effort)}</td>"
                f"<td>{escape(impact)}</td>"
                "</tr>"
            )
    return f"<table><thead><tr><th>Priority</th><th>Finding</th><th>Severity</th><th>Effort</th><th>Impact</th></tr></thead><tbody>{body}</tbody></table>"


def _render_deduplicated_findings_markdown(findings: list[Finding]) -> list[str]:
    rows = _deduplicated_finding_rows(findings)
    if not rows:
        return ["No findings recorded.", ""]
    lines: list[str] = []
    for index, row in enumerate(rows, start=1):
        finding = row["representative"]
        assert isinstance(finding, Finding)
        lines.extend(
            [
                f"### {index}. {row['title']} ({row['count']} instance{'s' if row['count'] != 1 else ''})",
                "",
                f"- Severity: {row['severity']}",
                f"- Status: {row['status']}",
                f"- Remediation Priority: {row['priority']}",
                f"- Affected Targets: {', '.join(row['targets'])}",
                f"- Evidence Refs: {', '.join(row['evidence_refs']) or 'Not linked'}",
                f"- Replay Status: {replay_status_for_finding(finding)}",
            ]
        )
        lines.extend(finding_methodology_lines(finding))
        if row["summary"]:
            lines.append(f"- Summary: {row['summary']}")
        lines.append(f"- Remediation Summary: {default_remediation_summary(finding.control_family)}")
        lines.append(f"- Remediation Detail: {default_remediation_detail(finding.control_family)}")
        lines.append("")
    return lines


def _render_deduplicated_findings_html(findings: list[Finding]) -> str:
    rows = _deduplicated_finding_rows(findings)
    if not rows:
        return "<p>No findings recorded.</p>"
    cards: list[str] = []
    for row in rows:
        finding = row["representative"]
        assert isinstance(finding, Finding)
        cards.append(
            "<article class='finding'>"
            f"<div class='finding-header'><h3>{escape(str(row['title']))} ({escape(str(row['count']))} instance{'s' if row['count'] != 1 else ''})</h3>"
            f"<span class='priority'>{escape(str(row['priority']))}</span></div>"
            f"<p><strong>Severity:</strong> {escape(str(row['severity']))} | "
            f"<strong>Status:</strong> {escape(str(row['status']))}</p>"
            f"<p><strong>Affected Targets:</strong> {escape(', '.join(row['targets']))}</p>"
            f"<p><strong>Evidence Refs:</strong> <code>{escape(', '.join(row['evidence_refs']) or 'Not linked')}</code></p>"
            f"<p><strong>Methodology:</strong> PTES {escape(ptes_phase_label(finding.ptes_phase) or 'Not Assigned')} | "
            f"NIST {escape(nist_phase_label(finding.nist_phase) or 'Not Assigned')} | "
            f"WSTG {escape(format_wstg_reference(finding.wstg_id, finding.wstg_version) or 'Not Assigned')}</p>"
            f"<p><strong>Control Family:</strong> {escape(control_family_label(finding.control_family) or 'Not Assigned')}</p>"
            f"<p><strong>Finding Origin:</strong> {escape(finding.finding_origin)} | "
            f"<strong>Source Pack Version:</strong> {escape(finding.source_pack_version or 'Standard Coverage')}</p>"
            + (f"<p>{escape(str(row['summary']))}</p>" if row["summary"] else "")
            + f"<p><strong>Remediation Summary:</strong> {escape(default_remediation_summary(finding.control_family))}</p>"
            + "</article>"
        )
    return "".join(cards)


def _professional_report_header_markdown(run: Run, context: dict[str, object], variant: str) -> list[str]:
    approvals = context.get("approvals", [])
    approval_list = [approval for approval in approvals if isinstance(approval, Approval)]
    title = REPORT_VARIANT_LABELS.get(variant, REPORT_VARIANT_LABELS["technical"])
    return [
        "# AegisPT Report Header",
        "",
        f"- Assessment Title: {title}",
        f"- Target: {_report_target_summary(context)}",
        f"- Date Range: {_report_date_range(run)}",
        f"- Authorized By: {_authorized_by(run, approval_list)}",
        f"- Run ID: {_short_run_id(run)}",
        f"- AegisPT Version: {AEGISPT_REPORT_VERSION}",
        f"- Methodology Version: {METHODOLOGY_VERSION}",
        "",
    ]


def _management_report_header_markdown(run: Run, context: dict[str, object]) -> list[str]:
    client = _management_safe_text(context.get("client_name"), fallback="the customer")
    return [
        "# AegisPT Management Summary",
        "",
        f"- Customer: {client}",
        f"- Assessed System: {_management_scope_label(context)}",
        f"- Assessment Window: {_report_date_range(run)}",
        "- Evidence Basis: Stored AegisPT findings and linked evidence for the tested scope.",
        f"- Methodology Basis: PTES; OWASP WSTG {WSTG_STABLE_VERSION}; NIST SP 800-115; OWASP ASVS {ASVS_STABLE_VERSION} where mapped.",
        "- Report Boundary: Business-facing summary. Technical identifiers remain in the technical and evidence reports.",
        "",
    ]


def _finalize_markdown_report(run: Run, context: dict[str, object], variant: str, body: str) -> str:
    header = "\n".join(_professional_report_header_markdown(run, context, variant))
    return f"{header}{body.rstrip()}\n\n---\n\n{REPORT_DISCLAIMER}\n"


def _finalize_management_markdown_report(run: Run, context: dict[str, object], body: str) -> str:
    header = "\n".join(_management_report_header_markdown(run, context))
    return f"{header}{body.rstrip()}\n\n---\n\n{REPORT_DISCLAIMER}\n"


def methodology_context_for_run(run: Run) -> dict[str, str]:
    run_class = run.profile.run_class if run.profile is not None else None
    ptes_phase = default_ptes_phase_for_run_class(run_class)
    nist_phase = default_nist_phase_for_run_class(run_class)
    return {
        "operator_stage": operator_workflow_stage_for_run_class(run_class),
        "ptes_phase": ptes_phase,
        "ptes_phase_label": ptes_phase_label(ptes_phase) or ptes_phase,
        "nist_phase": nist_phase,
        "nist_phase_label": nist_phase_label(nist_phase) or nist_phase,
    }


def adaptive_pack_context(run: Run) -> dict[str, object]:
    if run.bound_pack is None:
        return {
            "active": False,
            "label": "Standard baseline coverage only",
            "manifest": {},
            "deployment_target": None,
            "deployment_status": None,
        }

    deployment = run.bound_pack_deployment
    return {
        "active": True,
        "label": f"{run.bound_pack.name} {run.bound_pack.version}",
        "manifest": dict(run.bound_pack.manifest_json or {}),
        "deployment_target": deployment.deployment_target if deployment is not None else None,
        "deployment_status": deployment.status if deployment is not None else None,
    }


def _latest_pack_approval(run: Run):
    if run.bound_pack is None or not run.bound_pack.approvals:
        return None
    return sorted(
        run.bound_pack.approvals,
        key=lambda approval: (approval.created_at, approval.id.hex),
        reverse=True,
    )[0]


def _latest_pack_deployment(run: Run):
    if run.bound_pack_deployment is not None:
        return run.bound_pack_deployment
    if run.bound_pack is None or not run.bound_pack.deployments:
        return None
    return sorted(
        run.bound_pack.deployments,
        key=lambda deployment: (deployment.created_at, deployment.id.hex),
        reverse=True,
    )[0]


def _pack_related_codex_tasks(run: Run) -> list[object]:
    if run.bound_pack is None:
        return []

    pack_id = str(run.bound_pack.id)
    pack_version = str(run.bound_pack.version)
    related = []
    for task in list_codex_tasks():
        source_context = task.source_context
        if source_context.pack_id is None or str(source_context.pack_id) != pack_id:
            continue
        if source_context.pack_version and str(source_context.pack_version) != pack_version:
            continue
        related.append(task)

    return sorted(related, key=lambda item: (item.updated_at, item.created_at, item.id), reverse=True)


def _adaptive_findings_for_run(run: Run, findings: list[Finding]) -> list[Finding]:
    if run.bound_pack is None:
        return []

    pack_id = str(run.bound_pack.id)
    pack_version = str(run.bound_pack.version)
    linked: list[Finding] = []
    seen_ids: set[UUID] = set()
    for finding in findings:
        matches_pack = False
        if finding.source_pack_id is not None and str(finding.source_pack_id) == pack_id:
            matches_pack = True
        elif finding.source_pack_version and str(finding.source_pack_version) == pack_version:
            matches_pack = True
        elif finding.finding_origin == "adaptive_pack":
            matches_pack = True

        if matches_pack and finding.id not in seen_ids:
            linked.append(finding)
            seen_ids.add(finding.id)

    return linked


def adaptive_change_summary_for_run(run: Run, findings: list[Finding]) -> dict[str, object]:
    if run.bound_pack is None:
        return {
            "active": False,
            "review_state": "standard-baseline",
            "pack_label": "Standard baseline coverage only",
            "summary_line": "No adaptive pack is bound to this run, so the report reflects the standard baseline coverage path only.",
            "governance_line": "Codex build-lane review is not in scope for this run because no adaptive pack version is attached.",
            "finding_line": "No findings are linked to a bound adaptive pack for this run.",
            "change_highlights": [],
            "related_task_count": 0,
            "related_finding_count": 0,
            "finding_origin_breakdown": {},
            "methodology_tags": [],
            "source_threat_intel_refs": [],
            "latest_task": None,
        }

    pack = run.bound_pack
    validation = latest_validation_for_pack(pack)
    approval = _latest_pack_approval(run)
    deployment = _latest_pack_deployment(run)
    related_tasks = _pack_related_codex_tasks(run)
    latest_task = related_tasks[0] if related_tasks else None
    latest_result = load_codex_task_result(latest_task.id) if latest_task is not None else None
    related_findings = _adaptive_findings_for_run(run, findings)
    origin_breakdown = dict(Counter(finding.finding_origin for finding in related_findings))
    origin_summary = ", ".join(
        f"{count} {origin.replace('_', ' ')}"
        for origin, count in sorted(origin_breakdown.items())
    )
    generation_reason = str(pack.manifest_json.get("generation_reason") or "No generation reason recorded.")
    validation_status = validation.status if validation is not None else "not_run"
    approval_status = approval.decision if approval is not None else "not_requested"
    deployment_status = deployment.status if deployment is not None else "not_deployed"

    if latest_result is not None:
        review_state = "codex-prepared"
        summary_line = (
            f"Codex-reviewed adaptive coverage is bound through {pack.name} {pack.version}; "
            f"task {latest_task.id} prepared a supervised review bundle before promotion."
        )
    elif latest_task is not None:
        review_state = "codex-linked"
        summary_line = (
            f"Adaptive coverage is linked to Codex task {latest_task.id}, but no prepared review bundle "
            f"is recorded for this pack version yet."
        )
    else:
        review_state = "pack-only"
        summary_line = (
            f"Adaptive coverage is bound through {pack.name} {pack.version} in the supervised pack lane, "
            "but no linked Codex task is recorded for this pack version yet."
        )

    governance_line = (
        f"Pack status {pack.status}; validation {validation_status}; approval {approval_status}; "
        f"deployment {deployment_status}."
    )
    if related_findings:
        finding_line = (
            f"{len(related_findings)} findings in this run currently inherit bound-pack provenance"
            + (f" ({origin_summary})." if origin_summary else ".")
        )
    else:
        finding_line = "No findings in this run currently carry provenance from the bound adaptive pack."

    task_summary = None
    if latest_task is not None:
        task_summary = {
            "id": latest_task.id,
            "task_type": latest_task.task_type,
            "status": latest_task.status,
            "validation_status": latest_task.validation_status,
            "approval_status": latest_task.approval_status,
            "generation_reason": latest_task.generation_reason,
            "updated_at": latest_task.updated_at.isoformat(),
            "prepared_result_status": latest_result.status if latest_result is not None else None,
            "prepared_command_count": len(latest_result.prepared_commands) if latest_result is not None else 0,
            "prepared_output_count": len(latest_result.output_files) if latest_result is not None else 0,
        }

    change_highlights = [
        governance_line,
        (
            f"Latest Codex task {latest_task.id} ({latest_task.task_type}) is {latest_task.status} / "
            f"{latest_task.validation_status}; reason: {latest_task.generation_reason}."
            if latest_task is not None
            else f"Generation reason: {generation_reason}"
        ),
        finding_line,
    ]

    return {
        "active": True,
        "review_state": review_state,
        "pack_label": f"{pack.name} {pack.version}",
        "generation_mode": pack.generation_mode,
        "generation_reason": generation_reason,
        "summary_line": summary_line,
        "governance_line": governance_line,
        "finding_line": finding_line,
        "change_highlights": change_highlights,
        "related_task_count": len(related_tasks),
        "related_finding_count": len(related_findings),
        "finding_origin_breakdown": origin_breakdown,
        "methodology_tags": list(pack.methodology_tags),
        "source_threat_intel_refs": list(pack.source_threat_intel_refs_json),
        "latest_task": task_summary,
    }


def methodology_coverage_summary(findings: list[Finding], tasks: list[Task]) -> dict[str, list[str]]:
    wstg_areas = {
        area
        for area in (
            wstg_area_for_identifier(finding.wstg_id)
            for finding in findings
        )
        if area
    }
    if not wstg_areas:
        for task in tasks:
            wstg_areas.update(tool_wstg_areas(task.tool))

    control_families = {
        label
        for label in (
            control_family_label(finding.control_family)
            for finding in findings
        )
        if label
    }
    methodology_tags = {
        tag
        for finding in findings
        for tag in (finding.methodology_tags or [])
        if isinstance(tag, str) and tag.strip()
    }

    return {
        "wstg_areas": sorted(wstg_areas),
        "control_families": sorted(control_families),
        "methodology_tags": sorted(methodology_tags),
        "tools": sorted({task.tool for task in tasks}),
    }


