def _task_signal_text(task: Task) -> str:
    params = task.params_json if isinstance(task.params_json, dict) else {}
    return " ".join(
        [
            str(task.tool or ""),
            str(task.target_id or ""),
            json.dumps(params, sort_keys=True, default=str),
        ]
    ).lower()


def _run_signal_text(run: Run) -> str:
    configuration = run.configuration_json if isinstance(run.configuration_json, dict) else {}
    return " ".join(
        [
            str(run.profile.name if run.profile is not None else ""),
            str(run.profile.run_class if run.profile is not None else ""),
            json.dumps(configuration, sort_keys=True, default=str),
        ]
    ).lower()


def _signals_match(text: str, keywords: tuple[str, ...]) -> bool:
    return any(keyword in text for keyword in keywords)


def _run_has_wireless_evidence(run: Run) -> bool:
    snapshot = effective_inventory_snapshot_for_run(run)
    normalized_inventory = (
        snapshot.normalized_inventory_json
        if snapshot is not None
        and isinstance(getattr(snapshot, "normalized_inventory_json", None), dict)
        else {}
    )
    return bool(
        normalized_inventory.get("wireless_access_points")
        or normalized_inventory.get("wireless_networks")
    )


def report_sections_for_run(run: Run) -> list[str]:
    task_signals = " ".join(_task_signal_text(task) for task in list(run.tasks or []))
    run_signal = _run_signal_text(run)
    sections = list(ALWAYS_REPORT_SECTIONS)

    for rule in SURFACE_COVERAGE_RULES:
        if rule["key"] == "wifi_wireless" and not _run_has_wireless_evidence(run):
            continue
        keywords = tuple(str(keyword) for keyword in rule["keywords"])
        if _signals_match(task_signals, keywords) or _signals_match(run_signal, keywords):
            for section in rule["sections"]:
                section_key = str(section)
                if section_key not in sections:
                    sections.append(section_key)

    return sections


def build_test_coverage_block(run: Run, tasks: list[Task]) -> dict[str, object]:
    executed_tasks = [task for task in tasks if task.status in EXECUTED_TASK_STATUSES]
    executed_signal = " ".join(_task_signal_text(task) for task in executed_tasks)
    tested: list[dict[str, object]] = []
    not_tested: list[dict[str, object]] = []

    for rule in SURFACE_COVERAGE_RULES:
        keywords = tuple(str(keyword) for keyword in rule["keywords"])
        matching_tasks = [task for task in executed_tasks if _signals_match(_task_signal_text(task), keywords)]
        entry = {
            "key": rule["key"],
            "label": rule["label"],
            "task_count": len(matching_tasks),
            "tools": sorted({task.tool for task in matching_tasks}),
            "sections": list(rule["sections"]),
        }
        if matching_tasks or _signals_match(executed_signal, keywords):
            tested.append(entry)
        else:
            not_tested.append(
                {
                    **entry,
                    "reason": "No executed task in this run exercised this surface.",
                }
            )

    return {
        "tested_surfaces": tested,
        "not_tested_surfaces": not_tested,
        "executed_task_count": len(executed_tasks),
        "total_task_count": len(tasks),
        "tools": sorted({task.tool for task in executed_tasks}),
        "section_keys": report_sections_for_run(run),
    }


def remediation_priority_for_finding(finding: Finding) -> str:
    return REMEDIATION_PRIORITY.get(finding.severity, REMEDIATION_PRIORITY["unknown"])


def replay_status_for_finding(finding: Finding) -> str:
    return "evidence-linked" if finding.evidence_ref else "not-linked"


def remediation_priority_counts(findings: list[Finding]) -> dict[str, int]:
    return dict(Counter(remediation_priority_for_finding(finding) for finding in findings))


def finding_methodology_lines(finding: Finding) -> list[str]:
    lines = [
        f"- PTES Phase: {ptes_phase_label(finding.ptes_phase) or 'Not Assigned'}",
        f"- NIST Phase: {nist_phase_label(finding.nist_phase) or 'Not Assigned'}",
        f"- WSTG Reference: {format_wstg_reference(finding.wstg_id, finding.wstg_version) or 'Not Assigned'}",
        f"- WSTG Area: {wstg_area_for_identifier(finding.wstg_id) or 'Not Assigned'}",
        f"- ASVS Reference: {finding.asvs_reference or 'Not Assigned'}",
        f"- Control Family: {control_family_label(finding.control_family) or 'Not Assigned'}",
        f"- Methodology Tags: {', '.join(finding.methodology_tags or []) or 'None'}",
        f"- Finding Origin: {finding.finding_origin}",
        f"- Source Pack Version: {finding.source_pack_version or 'Standard Coverage'}",
    ]
    return lines


def _normalize_soc2_token(value: object) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(" ", "_")


def _soc2_mapping_for_finding(finding: Finding) -> tuple[dict[str, object], str] | None:
    control_family = _normalize_soc2_token(finding.control_family)
    methodology_tags = {
        _normalize_soc2_token(tag)
        for tag in (finding.methodology_tags or [])
        if isinstance(tag, str) and tag.strip()
    }
    wstg_id = str(finding.wstg_id or "").upper()
    asvs_reference = str(finding.asvs_reference or "").upper()

    for mapping in SOC2_CONTROL_MAPPINGS:
        control_families = set(mapping.get("control_families", set()))
        if control_family and control_family in control_families:
            return mapping, f"control_family={finding.control_family}"

        mapped_tags = set(mapping.get("methodology_tags", set()))
        tag_matches = sorted(methodology_tags.intersection(mapped_tags))
        if tag_matches:
            return mapping, f"methodology_tags={', '.join(tag_matches)}"

        for prefix in mapping.get("wstg_prefixes", ()):
            if isinstance(prefix, str) and wstg_id.startswith(prefix):
                return mapping, f"wstg_id={finding.wstg_id}"

        for prefix in mapping.get("asvs_prefixes", ()):
            if isinstance(prefix, str) and asvs_reference.startswith(prefix):
                return mapping, f"asvs_reference={finding.asvs_reference}"

    return None


def soc2_report_package_context(context: dict[str, object]) -> dict[str, object]:
    findings = context["findings"]
    assert isinstance(findings, list)

    control_groups = [
        {
            "mapping": mapping,
            "findings": [],
        }
        for mapping in SOC2_CONTROL_MAPPINGS
    ]
    control_groups_by_id = {
        str(group["mapping"]["control_id"]): group
        for group in control_groups
    }
    unmapped: list[Finding] = []
    mapped_count = 0

    for finding in findings:
        assert isinstance(finding, Finding)
        mapping_result = _soc2_mapping_for_finding(finding)
        if mapping_result is None:
            unmapped.append(finding)
            continue

        mapping, reason = mapping_result
        control_id = str(mapping["control_id"])
        control_groups_by_id[control_id]["findings"].append(
            {
                "finding": finding,
                "mapping_reason": reason,
            }
        )
        mapped_count += 1

    active_groups = [
        group
        for group in control_groups
        if group["findings"]
    ]
    coverage_rows = [
        {
            "control_id": str(group["mapping"]["control_id"]),
            "title": str(group["mapping"]["title"]),
            "trust_service_category": str(group["mapping"]["trust_service_category"]),
            "finding_count": len(group["findings"]),
            "basis": str(group["mapping"]["basis"]),
        }
        for group in control_groups
    ]

    return {
        "package": "SOC 2",
        "trust_service_category": "Security",
        "reference": SOC2_REPORT_REFERENCE,
        "total_findings": len(findings),
        "mapped_findings": mapped_count,
        "unmapped_findings": len(unmapped),
        "mapped_control_count": len(active_groups),
        "total_mapped_controls": len(SOC2_CONTROL_MAPPINGS),
        "coverage_rows": coverage_rows,
        "control_groups": control_groups,
        "active_groups": active_groups,
        "unmapped": unmapped,
        "zero_finding_path": len(findings) == 0,
    }


def _compliance_mapping_for_finding(
    finding: Finding,
    mappings: tuple[dict[str, object], ...],
) -> tuple[dict[str, object], str] | None:
    control_family = _normalize_soc2_token(finding.control_family)
    methodology_tags = {
        _normalize_soc2_token(tag)
        for tag in (finding.methodology_tags or [])
        if isinstance(tag, str) and tag.strip()
    }
    wstg_id = str(finding.wstg_id or "").upper()
    asvs_reference = str(finding.asvs_reference or "").upper()

    for mapping in mappings:
        control_families = set(mapping.get("control_families", set()))
        if control_family and control_family in control_families:
            return mapping, f"control_family={finding.control_family}"

        mapped_tags = set(mapping.get("methodology_tags", set()))
        tag_matches = sorted(methodology_tags.intersection(mapped_tags))
        if tag_matches:
            return mapping, f"methodology_tags={', '.join(tag_matches)}"

        for prefix in mapping.get("wstg_prefixes", ()):
            if isinstance(prefix, str) and wstg_id.startswith(prefix):
                return mapping, f"wstg_id={finding.wstg_id}"

        for prefix in mapping.get("asvs_prefixes", ()):
            if isinstance(prefix, str) and asvs_reference.startswith(prefix):
                return mapping, f"asvs_reference={finding.asvs_reference}"

    return None


def compliance_framework_package_context(context: dict[str, object], variant: str) -> dict[str, object]:
    package = COMPLIANCE_FRAMEWORK_PACKAGES[variant]
    mappings = package["controls"]
    assert isinstance(mappings, tuple)
    findings = context["findings"]
    assert isinstance(findings, list)

    control_groups = [
        {
            "mapping": mapping,
            "findings": [],
        }
        for mapping in mappings
    ]
    control_groups_by_id = {
        str(group["mapping"]["control_id"]): group
        for group in control_groups
    }
    unmapped: list[Finding] = []
    mapped_count = 0

    for finding in findings:
        assert isinstance(finding, Finding)
        mapping_result = _compliance_mapping_for_finding(finding, mappings)
        if mapping_result is None:
            unmapped.append(finding)
            continue

        mapping, reason = mapping_result
        control_id = str(mapping["control_id"])
        control_groups_by_id[control_id]["findings"].append(
            {
                "finding": finding,
                "mapping_reason": reason,
            }
        )
        mapped_count += 1

    active_groups = [
        group
        for group in control_groups
        if group["findings"]
    ]
    inactive_groups = [
        group
        for group in control_groups
        if not group["findings"]
    ]
    coverage_rows = [
        {
            "control_id": str(group["mapping"]["control_id"]),
            "title": str(group["mapping"]["title"]),
            "finding_count": len(group["findings"]),
            "basis": str(group["mapping"]["basis"]),
        }
        for group in control_groups
    ]

    return {
        "variant": variant,
        "package": package["package"],
        "reference": package["reference"],
        "heading": package["heading"],
        "coverage_heading": package["coverage_heading"],
        "findings_heading": package["findings_heading"],
        "group_label": package["group_label"],
        "mapped_label": package["mapped_label"],
        "manual_queue_heading": package["manual_queue_heading"],
        "manual_queue_statement": package["manual_queue_statement"],
        "untested_heading": package["untested_heading"],
        "boundary_label": package["boundary_label"],
        "boundary": package["boundary"],
        "zero_finding_statement": package["zero_finding_statement"],
        "total_findings": len(findings),
        "mapped_findings": mapped_count,
        "unmapped_findings": len(unmapped),
        "mapped_control_count": len(active_groups),
        "total_mapped_controls": len(mappings),
        "coverage_rows": coverage_rows,
        "control_groups": control_groups,
        "active_groups": active_groups,
        "inactive_groups": inactive_groups,
        "unmapped": unmapped,
        "zero_finding_path": len(findings) == 0,
    }


def compliance_gap_advisor_context(context: dict[str, object], variant: str) -> dict[str, object]:
    if variant == "soc2":
        compliance = soc2_report_package_context(context)
        group_label = "SOC 2 Control"
    else:
        compliance = compliance_framework_package_context(context, variant)
        group_label = str(compliance.get("group_label") or "Control")

    definition = COMPLIANCE_GAP_ADVISOR_DEFINITIONS[variant]
    coverage_rows = compliance["coverage_rows"]
    assert isinstance(coverage_rows, list)

    covered = [
        {
            "control_id": str(row["control_id"]),
            "title": str(row["title"]),
            "finding_count": int(row["finding_count"]),
            "basis": str(row["basis"]),
            "status": "Covered by evidence-backed finding",
        }
        for row in coverage_rows
        if isinstance(row, dict) and int(row.get("finding_count", 0)) > 0
    ]
    not_tested_technical = [
        {
            "control_id": str(row["control_id"]),
            "title": str(row["title"]),
            "reason": (
                "No evidence-backed finding or confirmed-clean control evidence was recorded for this "
                "testable technical control in this run."
            ),
            "next_step": "Run or attach relevant technical evidence, then regenerate the compliance report.",
        }
        for row in coverage_rows
        if isinstance(row, dict) and int(row.get("finding_count", 0)) == 0
    ]
    not_tested_process = [
        {
            "control_id": "",
            "title": str(item["control"]),
            "reason": (
                f"{item['reason']} This control requires organisational process review, "
                "not a technical scan."
            ),
            "next_step": str(item["next_step"]),
        }
        for item in definition["not_tested"]
        if isinstance(item, dict)
    ]

    total_testable = int(compliance["total_mapped_controls"])
    covered_count = int(compliance["mapped_control_count"])
    coverage_percentage = round((covered_count / total_testable) * 100) if total_testable else 0
    package = str(definition["package"])

    return {
        "package": package,
        "reference": compliance.get("reference"),
        "group_label": group_label,
        "technical_scope": definition["technical_scope"],
        "covered": covered,
        "not_tested": not_tested_technical + not_tested_process,
        "requires_human_auditor": [
            {
                "framework": item["framework"],
                "requirement": item["requirement"],
                "next_step": item["next_step"],
            }
            for item in HUMAN_AUDITOR_REQUIREMENTS
        ],
        "covered_count": covered_count,
        "total_testable_controls": total_testable,
        "coverage_percentage": coverage_percentage,
        "coverage_statement": (
            f"This assessment covered {covered_count} of {total_testable} testable {package} "
            "technical controls represented in AegisPT's report-time mapping "
            f"({coverage_percentage}%). This is not full framework compliance coverage."
        ),
        "next_steps": list(definition["next_steps"]),
    }


def _render_compliance_gap_advisor_markdown(advisor: dict[str, object]) -> list[str]:
    covered = advisor["covered"]
    not_tested = advisor["not_tested"]
    auditor_requirements = advisor["requires_human_auditor"]
    next_steps = advisor["next_steps"]
    assert isinstance(covered, list)
    assert isinstance(not_tested, list)
    assert isinstance(auditor_requirements, list)
    assert isinstance(next_steps, list)

    lines = [
        "## Compliance Gap Advisor",
        "",
        f"- Framework: {advisor['package']}",
        f"- Technical Coverage: {advisor['coverage_percentage']}%",
        f"- Coverage Basis: {advisor['technical_scope']}",
        f"- Coverage Statement: {advisor['coverage_statement']}",
        "",
        "### Covered by This Assessment",
        "",
    ]
    if covered:
        for item in covered:
            assert isinstance(item, dict)
            lines.append(
                f"- Covered: {item['control_id']} - {item['title']} "
                f"({item['finding_count']} evidence-backed finding(s)); {item['basis']}"
            )
    else:
        lines.append(
            "- No testable compliance controls had evidence-backed findings or confirmed-clean evidence in this run."
        )

    lines.extend(["", "### Not Tested in This Run", ""])
    for item in not_tested:
        assert isinstance(item, dict)
        label = (
            f"{item['control_id']} - {item['title']}"
            if item.get("control_id")
            else str(item["title"])
        )
        lines.extend(
            [
                f"- Not tested: {label}",
                f"  - Why: {item['reason']}",
                f"  - Next step: {item['next_step']}",
            ]
        )

    lines.extend(["", "### Requires Human Auditor", ""])
    for item in auditor_requirements:
        assert isinstance(item, dict)
        lines.extend(
            [
                f"- {item['framework']}: {item['requirement']}",
                f"  - Next step: {item['next_step']}",
            ]
        )

    lines.extend(["", "### Coverage Percentage", "", f"- {advisor['coverage_statement']}", ""])
    lines.extend(["### Framework-Specific Next Steps", ""])
    for step in next_steps:
        lines.append(f"- {step}")
    lines.append("")
    return lines


def _render_compliance_gap_advisor_html(advisor: dict[str, object]) -> str:
    covered = advisor["covered"]
    not_tested = advisor["not_tested"]
    auditor_requirements = advisor["requires_human_auditor"]
    next_steps = advisor["next_steps"]
    assert isinstance(covered, list)
    assert isinstance(not_tested, list)
    assert isinstance(auditor_requirements, list)
    assert isinstance(next_steps, list)

    covered_html = (
        "".join(
            "<li>"
            f"<strong>Covered:</strong> {escape(str(item['control_id']))} - {escape(str(item['title']))} "
            f"({escape(str(item['finding_count']))} evidence-backed finding(s)); {escape(str(item['basis']))}"
            "</li>"
            for item in covered
            if isinstance(item, dict)
        )
        or "<li>No testable compliance controls had evidence-backed findings or confirmed-clean evidence in this run.</li>"
    )
    not_tested_html = "".join(
        "<li>"
        f"<strong>{escape((str(item['control_id']) + ' - ') if item.get('control_id') else '')}{escape(str(item['title']))}</strong>"
        f"<br><span>Why: {escape(str(item['reason']))}</span>"
        f"<br><span>Next step: {escape(str(item['next_step']))}</span>"
        "</li>"
        for item in not_tested
        if isinstance(item, dict)
    )
    auditor_html = "".join(
        "<li>"
        f"<strong>{escape(str(item['framework']))}:</strong> {escape(str(item['requirement']))}"
        f"<br><span>Next step: {escape(str(item['next_step']))}</span>"
        "</li>"
        for item in auditor_requirements
        if isinstance(item, dict)
    )
    next_steps_html = "".join(
        f"<li>{escape(str(step))}</li>"
        for step in next_steps
    )

    return f"""
    <section class="panel">
      <h2>Compliance Gap Advisor</h2>
      <p><strong>Framework:</strong> {escape(str(advisor['package']))}</p>
      <p><strong>Technical Coverage:</strong> {escape(str(advisor['coverage_percentage']))}%</p>
      <p><strong>Coverage Basis:</strong> {escape(str(advisor['technical_scope']))}</p>
      <p><strong>Coverage Statement:</strong> {escape(str(advisor['coverage_statement']))}</p>
      <h3>Covered by This Assessment</h3>
      <ul class="meta-list">{covered_html}</ul>
      <h3>Not Tested in This Run</h3>
      <ul class="meta-list">{not_tested_html}</ul>
      <h3>Requires Human Auditor</h3>
      <ul class="meta-list">{auditor_html}</ul>
      <h3>Coverage Percentage</h3>
      <p>{escape(str(advisor['coverage_statement']))}</p>
      <h3>Framework-Specific Next Steps</h3>
      <ul class="meta-list">{next_steps_html}</ul>
    </section>
    """


def assurance_package_context(context: dict[str, object]) -> dict[str, object]:
    findings = context["findings"]
    tasks = context["tasks"]
    latest_scope = context["latest_scope"]
    inventory_summary = context["inventory_summary"]
    coverage = context["coverage"]
    assert isinstance(findings, list)
    assert isinstance(tasks, list)
    assert isinstance(inventory_summary, dict)
    assert isinstance(coverage, dict)

    unresolved = [
        finding
        for finding in findings
        if isinstance(finding, Finding) and finding.status in ASSURANCE_UNRESOLVED_STATUSES
    ]
    accepted_risk = [
        finding
        for finding in findings
        if isinstance(finding, Finding) and finding.status == "accepted_risk"
    ]
    resolved = [
        finding
        for finding in findings
        if isinstance(finding, Finding) and finding.status == "resolved"
    ]
    false_positive = [
        finding
        for finding in findings
        if isinstance(finding, Finding) and finding.status == "false_positive"
    ]
    evidence_linked_findings = [
        finding
        for finding in findings
        if isinstance(finding, Finding) and bool(finding.evidence_ref)
    ]
    artifact_count = sum(
        len(execution.artifacts or [])
        for task in tasks
        if isinstance(task, Task)
        for execution in task.executions or []
    )
    tool_names = coverage.get("tools", [])
    if not isinstance(tool_names, list):
        tool_names = []

    scope_available = latest_scope is not None
    out_of_scope_items = [
        "Targets, assets, identities, cloud resources, or applications outside the recorded allowlist.",
        "Denied targets and exclusions recorded in the scope denylist.",
        "Technologies, controls, and attack paths not exercised by the recorded run tools.",
        "Security conditions introduced after the run timestamp.",
        "External audit, certification, or attestation conclusions.",
    ]

    return {
        "active": True,
        "boundary": "This package is not a certification, attestation, or guarantee of security.",
        "tested_scope_available": scope_available,
        "total_findings": len(findings),
        "evidence_linked_findings": len(evidence_linked_findings),
        "evidence_artifacts": artifact_count,
        "task_count": len(tasks),
        "tools": [str(tool) for tool in tool_names],
        "unresolved_findings": len(unresolved),
        "accepted_risk_findings": len(accepted_risk),
        "resolved_findings": len(resolved),
        "false_positive_findings": len(false_positive),
        "residual_risk_findings": len(unresolved) + len(accepted_risk),
        "inventory_counts": {
            "hosts": inventory_summary.get("host_count", 0),
            "services": inventory_summary.get("service_count", 0),
            "endpoints": inventory_summary.get("endpoint_count", 0),
            "technologies": inventory_summary.get("technology_count", 0),
        },
        "out_of_scope_items": out_of_scope_items,
        "zero_finding_path": len(findings) == 0,
    }


def run_attack_narrative_context(run: Run, context: dict[str, object] | None = None) -> dict[str, object]:
    context = context or report_context(run)
    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    tasks = [task for task in context.get("tasks", []) if isinstance(task, Task)]
    inventory_summary = context.get("inventory_summary", {})
    if not isinstance(inventory_summary, dict):
        inventory_summary = {}

    attack_summary = build_attack_path_summary_for_loaded_run(run)
    attack_core = attack_summary.get("summary", {}) if isinstance(attack_summary, dict) else {}
    candidate_paths = [
        path for path in attack_summary.get("candidate_paths", []) if isinstance(path, dict)
    ] if isinstance(attack_summary, dict) else []
    choke_points = [
        point for point in attack_summary.get("choke_points", []) if isinstance(point, dict)
    ] if isinstance(attack_summary, dict) else []
    chains = _stored_chain_summaries(run)
    source_evidence_refs = _run_narrative_evidence_refs(findings, candidate_paths, chains)
    source_categories = _run_narrative_source_categories(
        inventory_summary=inventory_summary,
        candidate_paths=candidate_paths,
        chains=chains,
        source_evidence_refs=source_evidence_refs,
    )

    has_stored_material = bool(
        findings
        or tasks
        or inventory_summary
        or candidate_paths
        or choke_points
        or chains
        or source_evidence_refs
    )
    limitations: list[str] = [
        "Narrative text is advisory and requires operator review before customer use.",
        "The narrative is limited to stored run records and does not assert that exploitation was proven.",
    ]
    if run.status not in RUN_ATTACK_NARRATIVE_ELIGIBLE_STATUSES:
        status = "unavailable"
        available = False
        limitations.insert(0, "Narrative unavailable until the run reaches completed or completed_with_errors.")
    elif not has_stored_material:
        status = "limited"
        available = True
        limitations.insert(0, "Sparse completed run data: no findings, inventory, attack paths, chains, or evidence refs were recorded.")
    elif not findings and not candidate_paths and not chains:
        status = "limited"
        available = True
        limitations.insert(0, "Limited completed-run narrative: reconnaissance or task data exists, but no confirmed findings, attack paths, or chains were recorded.")
    else:
        status = "ready"
        available = True

    top_findings = _run_narrative_top_findings(findings)
    path_summaries = _run_narrative_path_summaries(candidate_paths)
    sections = _build_run_narrative_sections(
        run=run,
        status=status,
        available=available,
        findings=findings,
        top_findings=top_findings,
        tasks=tasks,
        inventory_summary=inventory_summary,
        attack_core=attack_core,
        path_summaries=path_summaries,
        chains=chains,
        source_categories=source_categories,
        source_evidence_refs=source_evidence_refs,
        limitations=limitations,
    )

    return {
        "supported": True,
        "available": available,
        "status": status,
        "mode": "ai_assisted_advisory",
        "review_required": True,
        "operator_editable": True,
        "canonical_report_unchanged": True,
        "source_run_id": str(run.id),
        "source_data_categories": source_categories,
        "source_evidence_refs": source_evidence_refs,
        "boundary": RUN_ATTACK_NARRATIVE_BOUNDARY,
        "findings_reviewed": len(findings),
        "high_priority_finding_count": len(
            [finding for finding in findings if str(finding.severity or "").lower() in {"critical", "high"}]
        ),
        "inventory_counts": {
            "hosts": inventory_summary.get("host_count", 0),
            "services": inventory_summary.get("service_count", 0),
            "endpoints": inventory_summary.get("endpoint_count", 0),
            "technologies": inventory_summary.get("technology_count", 0),
        },
        "attack_path_summary": {
            "status": attack_summary.get("status") if isinstance(attack_summary, dict) else "unavailable",
            "evaluation_model": attack_summary.get("evaluation_model") if isinstance(attack_summary, dict) else None,
            "candidate_path_count": attack_core.get("candidate_path_count", len(candidate_paths)),
            "choke_point_count": attack_core.get("choke_point_count", len(choke_points)),
            "mean_path_confidence": attack_core.get("mean_path_confidence", 0.0),
            "reason": attack_core.get("reason", "No attack-path summary was available for this run."),
        },
        "candidate_paths": path_summaries,
        "chain_detection_summary": {
            "chain_count": len(chains),
            "chains": chains,
            "boundary": (
                "Stored chain detections are explanatory records only; they do not execute chained exploitation "
                "or auto-escalate finding severity."
            ),
        },
        "remediation_priority_counts": context.get("remediation_counts", {}),
        "sections": sections,
        "limitations": limitations,
    }


def evidence_first_attack_story_context(
    run: Run,
    context: dict[str, object] | None = None,
) -> dict[str, object]:
    context = context or report_context(run)
    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    tasks = [task for task in context.get("tasks", []) if isinstance(task, Task)]
    approvals = [
        approval for approval in context.get("approvals", []) if isinstance(approval, Approval)
    ]
    claims: list[dict[str, object]] = []
    gaps: list[dict[str, object]] = []
    source_ledger: list[dict[str, str]] = []

    for finding in sorted(findings, key=lambda item: (item.severity, item.title, item.id.hex)):
        sources = [_source_record("finding_id", finding.id)]
        if not str(finding.evidence_ref or "").strip():
            gaps.append(
                {
                    "gap_id": f"finding:{finding.id}:missing_evidence_ref",
                    "text": (
                        f"Finding {finding.title} has no linked evidence reference, so the "
                        "attack story cannot claim proof beyond the stored finding record."
                    ),
                    "source_ids": [_source_record("finding_id", finding.id)],
                }
            )
        claim = {
            "claim_id": f"finding:{finding.id}:summary",
            "text": (
                f"Stored finding {finding.title} is recorded as {finding.severity} on "
                f"{finding.target_id} with status {finding.status}."
            ),
            "source_ids": sources,
            "claim_type": "finding_summary",
        }
        claims.append(claim)
        source_ledger.extend(_ledger_rows_for_claim(claim))

    for task in sorted(tasks, key=lambda item: (item.created_at, item.id.hex)):
        executions = list(task.executions or [])
        if not executions:
            gaps.append(
                {
                    "gap_id": f"task:{task.id}:missing_runner_output",
                    "text": (
                        f"Task {task.tool} on {task_targets_display(task)} has no runner output "
                        "record, so no narrative observation is claimed from it."
                    ),
                    "source_ids": [_source_record("task_id", task.id)],
                }
            )
            continue
        for execution in sorted(executions, key=lambda item: (item.created_at, item.id.hex)):
            sources = [_source_record("runner_output_id", execution.id)]
            artifacts = list(execution.artifacts or [])
            claim = {
                "claim_id": f"runner_output:{execution.id}:observation",
                "text": (
                    f"Runner {task.tool} produced stored output for {task_targets_display(task)} "
                    f"with exit code {execution.exit_code}."
                ),
                "source_ids": sources,
                "claim_type": "runner_output",
            }
            claims.append(claim)
            source_ledger.extend(_ledger_rows_for_claim(claim))
            if not artifacts:
                gaps.append(
                    {
                        "gap_id": f"runner_output:{execution.id}:missing_artifact",
                        "text": (
                            f"Runner output {execution.id} has no artifact record, so the story "
                            "does not cite replayable artifact proof for that step."
                        ),
                        "source_ids": [_source_record("runner_output_id", execution.id)],
                    }
                )

    for approval in sorted(approvals, key=lambda item: (item.created_at, item.id.hex)):
        claim = {
            "claim_id": f"approval:{approval.id}:decision",
            "text": (
                f"Approval step {approval.step_id} was recorded as {approval.decision} "
                f"by {approval.approver_id}."
            ),
            "source_ids": [_source_record("approval_event_id", approval.id)],
            "claim_type": "approval_event",
        }
        claims.append(claim)
        source_ledger.extend(_ledger_rows_for_claim(claim))

    for chain in sorted(list(run.finding_chains or []), key=lambda item: (item.pattern_id, item.id.hex)):
        component_sources = [
            _source_record("finding_id", finding_id)
            for finding_id in list(chain.component_finding_ids_json or [])
        ]
        if not component_sources:
            gaps.append(
                {
                    "gap_id": f"finding_chain:{chain.id}:missing_component_findings",
                    "text": (
                        f"Finding chain {chain.pattern_id} has no component finding IDs, so no "
                        "attack-story chain claim was generated from it."
                    ),
                    "source_ids": [_source_record("graph_edge_id", f"finding_chain:{chain.id}")],
                }
            )
            continue
        sources = [
            _source_record("graph_edge_id", f"finding_chain:{chain.id}:chains_finding"),
            *component_sources,
        ]
        claim = {
            "claim_id": f"finding_chain:{chain.id}:summary",
            "text": (
                f"Stored finding chain {chain.pattern_id} links "
                f"{len(component_sources)} finding record(s) for operator review."
            ),
            "source_ids": sources,
            "claim_type": "stored_graph_edge",
        }
        claims.append(claim)
        source_ledger.extend(_ledger_rows_for_claim(claim))

    graph = context.get("assessment_graph")
    if isinstance(graph, dict):
        for edge in _story_graph_edges(graph):
            claim = {
                "claim_id": f"graph_edge:{edge['id']}:relationship",
                "text": (
                    f"Stored assessment graph edge {edge['relationship']} links "
                    f"{edge['source']} to {edge['target']}."
                ),
                "source_ids": [_source_record("graph_edge_id", edge["id"])],
                "claim_type": "assessment_graph_edge",
            }
            claims.append(claim)
            source_ledger.extend(_ledger_rows_for_claim(claim))

    hypothesis_report = context.get("assessment_hypotheses")
    if isinstance(hypothesis_report, dict):
        for hypothesis in _story_hypotheses(hypothesis_report):
            sources = [_source_record("graph_hypothesis_id", hypothesis["id"])]
            claim = {
                "claim_id": f"graph_hypothesis:{hypothesis['id']}:next_observation",
                "text": (
                    "Evidence graph hypothesis recorded a safe next-observation question "
                    f"with confidence {hypothesis['confidence']}."
                ),
                "source_ids": sources,
                "claim_type": "evidence_graph_hypothesis",
            }
            claims.append(claim)
            source_ledger.extend(_ledger_rows_for_claim(claim))

    if not claims:
        gaps.append(
            {
                "gap_id": f"run:{run.id}:no_narrative_sources",
                "text": (
                    "No finding, runner output, or approval sources are available; no attack-story "
                    "claims were generated."
                ),
                "source_ids": [_source_record("run_id", run.id)],
            }
        )

    return {
        "builder_version": "evidence-first-attack-story-v1",
        "source_run_id": str(run.id),
        "claims": claims,
        "source_ledger": sorted(
            source_ledger,
            key=lambda item: (item["claim_id"], item["source_type"], item["source_id"]),
        ),
        "gaps": gaps,
        "unsupported_claims": [],
        "execution_contract": {
            "analysis_only": True,
            "dispatches_work": False,
            "mutates_findings": False,
            "mutates_scope": False,
            "runtime_self_modification": False,
            "claims_without_sources_allowed": False,
        },
    }


def _source_record(source_type: str, source_id: object) -> dict[str, str]:
    return {"source_type": source_type, "source_id": str(source_id)}


def _ledger_rows_for_claim(claim: dict[str, object]) -> list[dict[str, str]]:
    claim_id = str(claim.get("claim_id") or "")
    rows: list[dict[str, str]] = []
    for source in list(claim.get("source_ids") or []):
        if not isinstance(source, dict):
            continue
        source_type = str(source.get("source_type") or "").strip()
        source_id = str(source.get("source_id") or "").strip()
        if claim_id and source_type and source_id:
            rows.append(
                {
                    "claim_id": claim_id,
                    "source_type": source_type,
                    "source_id": source_id,
                }
            )
    return rows


def _story_graph_edges(graph: dict[str, object]) -> list[dict[str, str]]:
    allowed_relationships = {
        "chains_finding",
        "produced_artifact",
        "produced_execution",
        "reports_approval",
        "reports_evidence_artifact",
        "reports_finding",
        "supported_by_artifact",
    }
    edges: list[dict[str, str]] = []
    for edge in list(graph.get("edges") or []):
        if not isinstance(edge, dict):
            continue
        relationship = str(edge.get("relationship") or "").strip()
        edge_id = str(edge.get("id") or "").strip()
        source = str(edge.get("source") or "").strip()
        target = str(edge.get("target") or "").strip()
        if relationship in allowed_relationships and edge_id and source and target:
            edges.append(
                {
                    "id": edge_id,
                    "source": source,
                    "target": target,
                    "relationship": relationship,
                }
            )
    return sorted(edges, key=lambda item: (item["relationship"], item["id"]))


def _story_hypotheses(hypothesis_report: dict[str, object]) -> list[dict[str, object]]:
    hypotheses: list[dict[str, object]] = []
    for hypothesis in list(hypothesis_report.get("hypotheses") or []):
        if not isinstance(hypothesis, dict):
            continue
        hypothesis_id = str(hypothesis.get("id") or "").strip()
        if not hypothesis_id:
            continue
        hypotheses.append(
            {
                "id": hypothesis_id,
                "confidence": hypothesis.get("confidence", "unknown"),
            }
        )
    return sorted(hypotheses, key=lambda item: str(item["id"]))


def _run_narrative_source_categories(
    *,
    inventory_summary: dict[str, object],
    candidate_paths: list[dict[str, object]],
    chains: list[dict[str, object]],
    source_evidence_refs: list[str],
) -> list[str]:
    categories = [
        "run.status",
        "run.profile",
        "run.configuration_json",
        "run.findings",
        "run.tasks",
        "methodology.run_mapping",
    ]
    if inventory_summary:
        categories.append("inventory_snapshot.summary_json")
    if candidate_paths:
        categories.append("attack_path_summary")
    if chains:
        categories.append("finding_chains")
    if source_evidence_refs:
        categories.append("finding.evidence_ref")
    return categories


def _run_narrative_evidence_refs(
    findings: list[Finding],
    candidate_paths: list[dict[str, object]],
    chains: list[dict[str, object]],
) -> list[str]:
    refs = {
        str(finding.evidence_ref).strip()
        for finding in findings
        if str(finding.evidence_ref or "").strip()
    }
    for path in candidate_paths:
        refs.update(
            str(ref).strip()
            for ref in list(path.get("evidence_refs") or [])
            if str(ref or "").strip()
        )
    for chain in chains:
        refs.update(
            str(ref).strip()
            for ref in list(chain.get("evidence_refs") or [])
            if str(ref or "").strip()
        )
    return sorted(refs)


def _stored_chain_summaries(run: Run) -> list[dict[str, object]]:
    chains = sorted(
        [chain for chain in list(run.finding_chains or []) if isinstance(chain, FindingChain)],
        key=lambda chain: (float(chain.confidence_score or 0.0), chain.created_at, chain.id.hex),
        reverse=True,
    )
    return [
        {
            "id": str(chain.id),
            "pattern_id": chain.pattern_id,
            "title": chain.title,
            "status": chain.status,
            "confidence_score": chain.confidence_score,
            "component_finding_ids": [str(item) for item in list(chain.component_finding_ids_json or [])],
            "evidence_refs": list(chain.evidence_refs_json or []),
            "combined_impact": chain.combined_impact_text,
            "operator_note": dict(chain.metadata_json or {}).get("operator_note"),
        }
        for chain in chains[:5]
    ]


def _run_narrative_top_findings(findings: list[Finding]) -> list[Finding]:
    high_priority = [
        finding
        for finding in findings
        if str(finding.severity or "").lower() in {"critical", "high"}
    ]
    return (high_priority or findings)[:5]


def _run_narrative_path_summaries(candidate_paths: list[dict[str, object]]) -> list[dict[str, object]]:
    sorted_paths = sorted(
        candidate_paths,
        key=lambda path: (
            SEVERITY_ORDER.get(str(path.get("severity") or "unknown").lower(), SEVERITY_ORDER["unknown"]),
            -float(path.get("confidence") or 0.0),
            str(path.get("finding_title") or ""),
        ),
    )
    summaries: list[dict[str, object]] = []
    for path in sorted_paths[:5]:
        labels = [
            str(label)
            for label in list(path.get("labels") or [])
            if str(label or "").strip()
        ]
        summaries.append(
            {
                "id": str(path.get("id") or ""),
                "finding_id": str(path.get("finding_id") or ""),
                "finding_title": str(path.get("finding_title") or "Untitled finding"),
                "severity": str(path.get("severity") or "unknown"),
                "target_id": str(path.get("target_id") or "not recorded"),
                "confidence": path.get("confidence") or 0.0,
                "labels": labels,
                "path": " -> ".join(labels) if labels else "No path labels recorded.",
                "evidence_refs": [
                    str(ref)
                    for ref in list(path.get("evidence_refs") or [])
                    if str(ref or "").strip()
                ],
                "explanation": str(path.get("explanation") or "No path explanation recorded."),
            }
        )
    return summaries


def _build_run_narrative_sections(
    *,
    run: Run,
    status: str,
    available: bool,
    findings: list[Finding],
    top_findings: list[Finding],
    tasks: list[Task],
    inventory_summary: dict[str, object],
    attack_core: dict[str, object],
    path_summaries: list[dict[str, object]],
    chains: list[dict[str, object]],
    source_categories: list[str],
    source_evidence_refs: list[str],
    limitations: list[str],
) -> list[dict[str, object]]:
    if not available:
        return [
            _run_narrative_section(
                section_id="availability",
                title="Narrative Availability",
                body=(
                    f"AI-assisted/advisory run attack narrative is unavailable for run status {run.status}. "
                    "Complete the run first, then regenerate this review layer from stored evidence."
                ),
                source_categories=source_categories,
                source_evidence_refs=source_evidence_refs,
            )
        ]

    host_count = inventory_summary.get("host_count", 0)
    service_count = inventory_summary.get("service_count", 0)
    endpoint_count = inventory_summary.get("endpoint_count", 0)
    recon_body = (
        f"AI-assisted/advisory narrative: reconnaissance recorded {host_count} hosts, "
        f"{service_count} services, and {endpoint_count} endpoints for this run. "
        f"The narrative also references {len(tasks)} task records and remains limited to stored execution output."
        if inventory_summary
        else (
            "AI-assisted/advisory narrative: no discovery-confirmed inventory snapshot is linked to this run. "
            f"The narrative can only reference {len(tasks)} task records and stored findings."
        )
    )

    if path_summaries:
        top_path = path_summaries[0]
        path_body = (
            "AI-assisted/advisory narrative: the existing attack-path summary produced "
            f"{attack_core.get('candidate_path_count', len(path_summaries))} candidate paths and "
            f"{attack_core.get('choke_point_count', 0)} choke points. Top reviewed path: "
            f"{top_path['path']} ({top_path['severity']} finding, confidence {top_path['confidence']})."
        )
    else:
        path_body = (
            "AI-assisted/advisory narrative: no evidence-backed attack paths were derived from the stored "
            "inventory and finding data for this run."
        )

    if chains:
        first_chain = chains[0]
        chain_body = (
            f"AI-assisted/advisory narrative: {len(chains)} stored vulnerability-chain detection records are available. "
            f"Highest-confidence chain: {first_chain['title']} ({first_chain['status']}, confidence "
            f"{first_chain['confidence_score']}). {first_chain['combined_impact']}"
        )
    else:
        chain_body = (
            "AI-assisted/advisory narrative: no stored vulnerability-chain detections are attached to this run. "
            "No chained-impact claim should be made without later operator-reviewed evidence."
        )

    if top_findings:
        finding_lines = "; ".join(
            f"{finding.severity} {finding.title} on {finding.target_id}"
            for finding in top_findings[:3]
        )
        findings_body = (
            f"AI-assisted/advisory narrative: priority operator review should focus on {finding_lines}. "
            "Remediation priority remains advisory and must be verified against the canonical findings."
        )
    else:
        findings_body = (
            "AI-assisted/advisory narrative: no confirmed findings were recorded, so this section cannot "
            "claim exploited weaknesses or remediation urgency."
        )

    limitation_body = " ".join(limitations)
    if status == "limited":
        limitation_body = f"Limited narrative status: {limitation_body}"

    return [
        _run_narrative_section(
            section_id="reconnaissance",
            title="Reconnaissance Narrative",
            body=recon_body,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
        ),
        _run_narrative_section(
            section_id="attack_paths",
            title="Attack Path Narrative",
            body=path_body,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
        ),
        _run_narrative_section(
            section_id="chain_detections",
            title="Chain Detection Narrative",
            body=chain_body,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
        ),
        _run_narrative_section(
            section_id="critical_findings",
            title="Critical Findings and Remediation Narrative",
            body=findings_body,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
        ),
        _run_narrative_section(
            section_id="review_boundary",
            title="Operator Review Boundary",
            body=limitation_body,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
        ),
    ]


def _run_narrative_section(
    *,
    section_id: str,
    title: str,
    body: str,
    source_categories: list[str],
    source_evidence_refs: list[str],
) -> dict[str, object]:
    return {
        "section_id": section_id,
        "title": title,
        "body": body,
        "source_data_categories": source_categories,
        "source_evidence_refs": source_evidence_refs,
        "review_required": True,
        "advisory": True,
    }


def report_methodology_references_for_variant(
    run: Run,
    variant: str,
    *,
    framework: str | None = None,
) -> list[str]:
    references = report_methodology_references(run)
    canonical_variant = normalize_report_variant(variant)
    compliance_framework = compliance_framework_for_request(variant, framework)
    if canonical_variant == "compliance" and compliance_framework == "soc2":
        references.append(SOC2_REPORT_REFERENCE)
    if canonical_variant == "compliance" and compliance_framework == "iso27001":
        references.append(ISO27001_REPORT_REFERENCE)
    if canonical_variant == "compliance" and compliance_framework == "pci_dss":
        references.append(PCI_DSS_REPORT_REFERENCE)
    if canonical_variant == "compliance" and compliance_framework == "nis2":
        references.append(NIS2_REPORT_REFERENCE)
        references.append("NCSC NL Cyberbeveiligingswet / NIS2 zorgplicht guidance")
    if canonical_variant == "compliance" and compliance_framework == "dora":
        references.append(DORA_REPORT_REFERENCE)
        references.append(TIBER_EU_REPORT_REFERENCE)
    if canonical_variant == "compliance" and compliance_framework == "nfir":
        references.append(NFIR_REPORT_REFERENCE)
    if variant == "assurance":
        references.append(ASSURANCE_REPORT_REFERENCE)
    if variant == "attack_narrative":
        references.append(RUN_ATTACK_NARRATIVE_REFERENCE)
    return references


def run_configuration_context(run: Run) -> dict[str, object]:
    configuration = sanitize_run_configuration(dict(run.configuration_json or {}))
    raw_modules = configuration.get("modules", {})
    enabled_modules = []
    if isinstance(raw_modules, dict):
        enabled_modules = sorted(
            _humanize_key(module)
            for module, enabled in raw_modules.items()
            if isinstance(module, str) and bool(enabled)
        )

    raw_targets = configuration.get("targets", {})
    normalized_targets: dict[str, list[str]] = {}
    if isinstance(raw_targets, dict):
        for key, values in raw_targets.items():
            if isinstance(key, str) and isinstance(values, list):
                normalized_targets[key] = [value for value in values if isinstance(value, str) and value.strip()]

    access = configuration.get("access", {})
    accounts_summary: list[str] = []
    if isinstance(access, dict):
        accounts = access.get("accounts", [])
        if isinstance(accounts, list):
            for account in accounts:
                if not isinstance(account, dict):
                    continue
                label = str(account.get("label") or account.get("username") or "Account").strip()
                role = str(account.get("role") or "role not set").strip()
                accounts_summary.append(f"{label} ({role})")

    eta = configuration.get("eta", {})
    if not isinstance(eta, dict):
        eta = {}
    safety = configuration.get("safety", {})
    if not isinstance(safety, dict):
        safety = {}

    return {
        "assessment_type": str(configuration.get("assessment_type") or "Not recorded"),
        "test_profile": str(configuration.get("test_profile") or (run.profile.name if run.profile is not None else "Not recorded")),
        "targets": normalized_targets,
        "enabled_modules": enabled_modules,
        "accounts_summary": accounts_summary,
        "safety": safety,
        "eta": eta,
    }


def report_methodology_references(run: Run) -> list[str]:
    references = [
        "PTES",
        f"OWASP WSTG {WSTG_STABLE_VERSION}",
        "NIST SP 800-115",
    ]
    if any(finding.asvs_reference for finding in run.findings):
        references.append(f"OWASP ASVS {ASVS_STABLE_VERSION}")
    return references


def report_context(run: Run) -> dict[str, object]:
    findings = sort_findings(list(run.findings))
    tasks = sort_tasks(list(run.tasks))
    approvals = sort_approvals(list(run.approvals))
    findings_by_severity, findings_by_status = findings_summary(findings)
    inventory_snapshot = effective_inventory_snapshot_for_run(run)
    inventory_summary = dict(inventory_snapshot.summary_json or {}) if inventory_snapshot is not None else {}
    coverage_truth = build_coverage_truth(None, run=run)
    return {
        "profile_name": run.profile.name if run.profile is not None else "unknown-profile",
        "engagement_name": run.engagement.name if run.engagement is not None else "unknown-engagement",
        "client_name": run.engagement.client if run.engagement is not None and run.engagement.client else "unknown-client",
        "findings": findings,
        "tasks": tasks,
        "approvals": approvals,
        "findings_by_severity": findings_by_severity,
        "findings_by_status": findings_by_status,
        "methodology": methodology_context_for_run(run),
        "adaptive_pack": adaptive_pack_context(run),
        "adaptive_change": adaptive_change_summary_for_run(run, findings),
        "coverage": methodology_coverage_summary(findings, tasks),
        "latest_scope": latest_scope_for_engagement(run.engagement),
        "remediation_counts": remediation_priority_counts(findings),
        "configuration": run_configuration_context(run),
        "inventory_snapshot": inventory_snapshot,
        "inventory_summary": inventory_summary,
        "report_sections": report_sections_for_run(run),
        "test_coverage": build_test_coverage_block(run, tasks),
        "coverage_truth": coverage_truth,
        "rationale_ledger": sorted(
            list(run.rationale_ledger_entries or []),
            key=lambda entry: (entry.created_at, entry.id),
        ),
    }


def _best_inventory_snapshot_for_runs(runs: list[Run]):
    snapshots = [
        snapshot
        for snapshot in (effective_inventory_snapshot_for_run(run) for run in runs)
        if snapshot is not None
    ]
    if not snapshots:
        return None

    def score(snapshot) -> tuple[int, datetime, str]:
        summary = snapshot.summary_json if isinstance(snapshot.summary_json, dict) else {}
        data_points = sum(
            int(summary.get(key, 0) or 0)
            for key in ("host_count", "service_count", "endpoint_count", "technology_count")
        )
        return (data_points, snapshot.created_at, snapshot.id.hex)

    return max(snapshots, key=score)


def _chain_profile_label(primary_run: Run) -> str:
    chain = primary_run.assessment_chain
    if chain is not None:
        raw_mode = str(chain.assessment_mode or "").strip()
        if raw_mode:
            return f"{_humanize_key(raw_mode)} assessment chain"
    return primary_run.profile.name if primary_run.profile is not None else "unknown-profile"


def assessment_chain_report_context(primary_run: Run, chain_runs: list[Run]) -> dict[str, object]:
    runs = [run for run in chain_runs if run.deleted_at is None]
    if not runs:
        return report_context(primary_run)

    finding_by_id = {
        finding.id: finding
        for run in runs
        for finding in list(run.findings or [])
    }
    task_by_id = {
        task.id: task
        for run in runs
        for task in list(run.tasks or [])
    }
    approval_by_id = {
        approval.id: approval
        for run in runs
        for approval in list(run.approvals or [])
    }
    rationale_by_id = {
        entry.id: entry
        for run in runs
        for entry in list(run.rationale_ledger_entries or [])
    }
    findings = sort_findings(list(finding_by_id.values()))
    tasks = sort_tasks(list(task_by_id.values()))
    approvals = sorted(
        approval_by_id.values(),
        key=lambda approval: (approval.created_at, approval.id.hex),
    )
    findings_by_severity, findings_by_status = findings_summary(findings)
    inventory_snapshot = _best_inventory_snapshot_for_runs(runs)
    inventory_summary = dict(inventory_snapshot.summary_json or {}) if inventory_snapshot is not None else {}
    base_context = report_context(primary_run)
    chain = primary_run.assessment_chain
    configuration = run_configuration_context(primary_run)
    if chain is not None:
        configuration = {
            **configuration,
            "assessment_chain_id": str(chain.id),
            "assessment_chain_status": chain.status,
            "assessment_chain_mode": chain.assessment_mode,
            "assessment_chain_run_count": len(runs),
        }

    return {
        **base_context,
        "profile_name": _chain_profile_label(primary_run),
        "findings": findings,
        "tasks": tasks,
        "approvals": approvals,
        "findings_by_severity": findings_by_severity,
        "findings_by_status": findings_by_status,
        "adaptive_change": adaptive_change_summary_for_run(primary_run, findings),
        "coverage": methodology_coverage_summary(findings, tasks),
        "remediation_counts": remediation_priority_counts(findings),
        "configuration": configuration,
        "inventory_snapshot": inventory_snapshot,
        "inventory_summary": inventory_summary,
        "test_coverage": {
            **build_test_coverage_block(primary_run, tasks),
            "assessment_chain_run_count": len(runs),
        },
        "coverage_truth": build_coverage_truth(session=None, run=primary_run),
        "rationale_ledger": sorted(
            rationale_by_id.values(),
            key=lambda entry: (entry.created_at, entry.id),
        ),
    }


def report_context_for_run(run: Run, *, session: Session | None = None) -> dict[str, object]:
    if session is not None and run.assessment_chain_id is not None:
        chain_runs = load_assessment_chain_report_runs(session, run.assessment_chain_id)
        if len(chain_runs) > 1:
            return assessment_chain_report_context(run, chain_runs)
    return report_context(run)


def _render_rationale_ledger_markdown(context: dict[str, object]) -> list[str]:
    entries = [
        entry
        for entry in context.get("rationale_ledger", [])
        if isinstance(entry, RationaleLedgerEntry)
    ]
    lines = [
        "## AI Action Rationale Ledger",
        "",
        (
            "This ledger records why AI-loop actions were queued or proposed. Each entry is grounded in "
            "a stored Target Context Document and still depends on registered runners, scope/ROE checks, "
            "approval gates, and the kill switch."
        ),
        "",
    ]
    if not entries:
        lines.extend(["- No AI rationale ledger entries recorded for this run.", ""])
        return lines
    for entry in entries:
        observed = entry.decision_source_json.get("observed_context") if isinstance(entry.decision_source_json, dict) else {}
        evidence_refs = observed.get("evidence_refs") if isinstance(observed, dict) else []
        lines.extend(
            [
                f"### Ledger Entry {entry.id}",
                "",
                f"- Status: {entry.status}",
                f"- Tool: {entry.tool_name}",
                f"- Target: {entry.target or 'Not recorded'}",
                f"- Context Document: {entry.context_document_id or 'Not linked'}",
                f"- Task: {entry.task_id or 'Not queued'}",
                f"- Proposal: {entry.agent_proposal_id or 'Not recorded'}",
                f"- Evidence Refs: {len(evidence_refs) if isinstance(evidence_refs, list) else 0}",
                f"- Rationale: {entry.rationale_text}",
                "",
            ]
        )
    return lines


def _render_rationale_ledger_html(context: dict[str, object]) -> str:
    entries = [
        entry
        for entry in context.get("rationale_ledger", [])
        if isinstance(entry, RationaleLedgerEntry)
    ]
    if not entries:
        body = "<p>No AI rationale ledger entries recorded for this run.</p>"
    else:
        body = "".join(
            "<article class='task'>"
            f"<h3>Ledger Entry {escape(str(entry.id))}</h3>"
            f"<p><strong>Status:</strong> {escape(entry.status)} | "
            f"<strong>Tool:</strong> {escape(entry.tool_name)} | "
            f"<strong>Target:</strong> {escape(entry.target or 'Not recorded')}</p>"
            f"<p><strong>Context Document:</strong> {escape(str(entry.context_document_id or 'Not linked'))} | "
            f"<strong>Task:</strong> {escape(str(entry.task_id or 'Not queued'))} | "
            f"<strong>Proposal:</strong> {escape(str(entry.agent_proposal_id or 'Not recorded'))}</p>"
            f"<p>{escape(entry.rationale_text)}</p>"
            "</article>"
            for entry in entries
        )
    return f"""
    <section class="panel">
      <h2>AI Action Rationale Ledger</h2>
      <p>This ledger records why AI-loop actions were queued or proposed. Entries remain bound to registered runners, scope/ROE checks, approval gates, and the kill switch.</p>
      {body}
    </section>
    """


def _inventory_summary_lines(context: dict[str, object]) -> list[str]:
    inventory_summary = context.get("inventory_summary", {})
    if not isinstance(inventory_summary, dict) or not inventory_summary:
        return ["- No discovery-confirmed inventory snapshot is linked to this run.", ""]

    return [
        f"- Hosts Observed: {inventory_summary.get('host_count', 0)}",
        f"- Services Observed: {inventory_summary.get('service_count', 0)}",
        f"- Endpoints Observed: {inventory_summary.get('endpoint_count', 0)}",
        f"- Technologies Observed: {inventory_summary.get('technology_count', 0)}",
        f"- Inventory Confidence: {inventory_summary.get('confidence_score', 0.0)}",
        "",
    ]


def _iot_security_summary_lines(context: dict[str, object]) -> list[str]:
    inventory_summary = context.get("inventory_summary", {})
    inventory_snapshot = context.get("inventory_snapshot")
    normalized_inventory = (
        inventory_snapshot.normalized_inventory_json
        if inventory_snapshot is not None
        and isinstance(getattr(inventory_snapshot, "normalized_inventory_json", None), dict)
        else {}
    )
    hosts = [
        host
        for host in normalized_inventory.get("hosts", [])
        if isinstance(host, dict)
    ]
    device_types = sorted(
        {
            str(host.get("device_type") or "").strip()
            for host in hosts
            if str(host.get("device_type") or "").strip()
        }
    )
    device_lines = [
        f"- {host.get('host')}: {host.get('device_type')}"
        for host in hosts
        if str(host.get("device_type") or "").strip()
    ][:12]
    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    unauthenticated = [
        finding
        for finding in findings
        if any(
            token in " ".join([finding.title, finding.summary or ""]).lower()
            for token in ("unauth", "anonymous", "no auth", "open management")
        )
    ]
    default_creds = [
        finding
        for finding in findings
        if any(
            token in " ".join([finding.title, finding.summary or ""]).lower()
            for token in ("default credential", "accepted default", "default password")
        )
    ]
    segmentation = [
        finding
        for finding in findings
        if any(
            token in " ".join([finding.title, finding.summary or ""]).lower()
            for token in ("segmentation", "vlan", "cross-segment", "ipv6")
        )
    ]
    lines = [
        "- Device Types: " + (", ".join(device_types) if device_types else "None recorded"),
        f"- IoT Device Type Count: {inventory_summary.get('device_type_count', len(device_types)) if isinstance(inventory_summary, dict) else len(device_types)}",
        f"- Unauthenticated Service Findings: {len(unauthenticated)}",
        f"- Default Credential Findings: {len(default_creds)}",
        f"- Segmentation / IPv6 Findings: {len(segmentation)}",
        "",
        "#### Device Inventory",
        "",
    ]
    lines.extend(device_lines or ["- No typed IoT devices are recorded in the linked inventory snapshot."])
    lines.append("")
    return lines


def _iot_security_summary_html(context: dict[str, object]) -> str:
    lines = _iot_security_summary_lines(context)
    items = "".join(
        f"<li>{escape(line[2:])}</li>"
        for line in lines
        if line.startswith("- ")
    )
    return f"""
    <section class="panel">
      <h2>IoT Security Summary</h2>
      <ul class="meta-list">{items or "<li>No typed IoT device inventory is recorded for this run.</li>"}</ul>
    </section>
    """


def _wifi_security_summary_lines(context: dict[str, object]) -> list[str]:
    inventory_snapshot = context.get("inventory_snapshot")
    normalized_inventory = (
        inventory_snapshot.normalized_inventory_json
        if inventory_snapshot is not None
        and isinstance(getattr(inventory_snapshot, "normalized_inventory_json", None), dict)
        else {}
    )
    access_points = [
        item
        for item in normalized_inventory.get("wireless_access_points", [])
        if isinstance(item, dict)
    ]
    networks = [
        item for item in normalized_inventory.get("wireless_networks", []) if isinstance(item, dict)
    ]
    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    wifi_findings = [
        finding
        for finding in findings
        if any(
            token in " ".join([finding.title, finding.summary or "", finding.target_id]).lower()
            for token in ("wifi", "wireless", "ssid", "bssid", "wps", "pmf")
        )
    ]
    lines = [
        f"- Wireless Networks Observed: {len(networks)}",
        f"- Access Points Observed: {len(access_points)}",
        f"- WiFi Findings: {len(wifi_findings)}",
        "- Boundary: passive evidence only; no deauthentication, jamming, evil-twin, handshake capture, WPS brute force, or credential harvesting was performed.",
        "",
        "#### Observed Networks",
        "",
    ]
    for network in networks[:12]:
        lines.append(
            f"- {network.get('ssid')}: {network.get('encryption', 'unknown')} · {network.get('bssid_count', 0)} BSSID(s)"
        )
    if not networks:
        lines.append("- No wireless network inventory is recorded in the linked inventory snapshot.")
    lines.append("")
    return lines


def _wifi_security_summary_html(context: dict[str, object]) -> str:
    lines = _wifi_security_summary_lines(context)
    items = "".join(
        f"<li>{escape(line[2:])}</li>"
        for line in lines
        if line.startswith("- ")
    )
    return f"""
    <section class="panel">
      <h2>WiFi Security Summary</h2>
      <ul class="meta-list">{items or "<li>No WiFi inventory is recorded for this run.</li>"}</ul>
    </section>
    """


def _render_test_coverage_markdown(context: dict[str, object]) -> list[str]:
    coverage = context.get("test_coverage", {})
    coverage_truth = context.get("coverage_truth", {})
    if not isinstance(coverage, dict):
        return ["## Tested / Not Tested", "", "- Coverage data is unavailable for this run.", ""]
    if not isinstance(coverage_truth, dict):
        coverage_truth = {}
    truth_summary = coverage_truth.get("summary", {}) if isinstance(coverage_truth.get("summary"), dict) else {}
    stop_condition = (
        coverage_truth.get("stop_condition", {})
        if isinstance(coverage_truth.get("stop_condition"), dict)
        else {}
    )
    tested = [item for item in coverage.get("tested_surfaces", []) if isinstance(item, dict)]
    not_tested = [item for item in coverage.get("not_tested_surfaces", []) if isinstance(item, dict)]
    lines = [
        "## Tested / Not Tested",
        "",
        f"- Executed Tasks Reviewed: {coverage.get('executed_task_count', 0)} of {coverage.get('total_task_count', 0)}",
        f"- Tools Used: {', '.join(coverage.get('tools', [])) or 'None recorded'}",
        f"- Coverage Truth Stop Condition: {stop_condition.get('state', 'unknown')}",
        f"- Coverage Truth Gaps: blocked={truth_summary.get('blocked_count', 0)}, not-tested={truth_summary.get('not_tested_count', 0)}, partial={truth_summary.get('partially_tested_count', 0)}",
        "",
        "### Tested in This Run",
        "",
    ]
    if tested:
        for item in tested:
            lines.append(
                f"- {item['label']}: {item['task_count']} executed task(s)"
                + (f" using {', '.join(item.get('tools', []))}" if item.get("tools") else "")
            )
    else:
        lines.append("- No executed test surface is recorded for this run.")
    lines.extend(["", "### Not Tested in This Run", ""])
    if not_tested:
        for item in not_tested:
            lines.append(f"- {item['label']}: {item.get('reason')}")
    else:
        lines.append("- No untested packaged surface was detected from the recorded run profile.")
    lines.append("")
    return lines


def _render_test_coverage_html(context: dict[str, object]) -> str:
    coverage = context.get("test_coverage", {})
    coverage_truth = context.get("coverage_truth", {})
    if not isinstance(coverage, dict):
        return "<section class='panel'><h2>Tested / Not Tested</h2><p>Coverage data is unavailable for this run.</p></section>"
    if not isinstance(coverage_truth, dict):
        coverage_truth = {}
    truth_summary = coverage_truth.get("summary", {}) if isinstance(coverage_truth.get("summary"), dict) else {}
    stop_condition = (
        coverage_truth.get("stop_condition", {})
        if isinstance(coverage_truth.get("stop_condition"), dict)
        else {}
    )
    tested = [item for item in coverage.get("tested_surfaces", []) if isinstance(item, dict)]
    not_tested = [item for item in coverage.get("not_tested_surfaces", []) if isinstance(item, dict)]
    tested_html = "".join(
        "<li>"
        f"<strong>{escape(str(item['label']))}:</strong> {escape(str(item['task_count']))} executed task(s)"
        + (f" using {escape(', '.join(item.get('tools', [])))}" if item.get("tools") else "")
        + "</li>"
        for item in tested
    ) or "<li>No executed test surface is recorded for this run.</li>"
    not_tested_html = "".join(
        "<li>"
        f"<strong>{escape(str(item['label']))}:</strong> {escape(str(item.get('reason') or 'No executed task recorded.'))}"
        "</li>"
        for item in not_tested
    ) or "<li>No untested packaged surface was detected from the recorded run profile.</li>"
    return f"""
    <section class="panel">
      <h2>Tested / Not Tested</h2>
      <p><strong>Executed Tasks Reviewed:</strong> {escape(str(coverage.get('executed_task_count', 0)))} of {escape(str(coverage.get('total_task_count', 0)))}</p>
      <p><strong>Tools Used:</strong> {escape(', '.join(coverage.get('tools', [])) or 'None recorded')}</p>
      <p><strong>Coverage Truth Stop Condition:</strong> {escape(str(stop_condition.get('state', 'unknown')))}</p>
      <p><strong>Coverage Truth Gaps:</strong> blocked={escape(str(truth_summary.get('blocked_count', 0)))}, not-tested={escape(str(truth_summary.get('not_tested_count', 0)))}, partial={escape(str(truth_summary.get('partially_tested_count', 0)))}</p>
      <h3>Tested in This Run</h3>
      <ul class="meta-list">{tested_html}</ul>
      <h3>Not Tested in This Run</h3>
      <ul class="meta-list">{not_tested_html}</ul>
    </section>
    """


def _render_adaptive_technical_sections_markdown(context: dict[str, object]) -> list[str]:
    sections = [str(section) for section in context.get("report_sections", [])]
    inventory_summary = context.get("inventory_summary", {})
    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    lines = ["## Adaptive Technical Sections", ""]
    for section in sections:
        label = REPORT_SECTION_LABELS.get(section, _humanize_key(section))
        lines.extend([f"### {label}", ""])
        if section == "scope_summary":
            lines.append(f"- Target: {_report_target_summary(context)}")
        elif section == "findings_summary":
            lines.append(f"- Confirmed Findings: {len(findings)}")
        elif section == "remediation_priorities":
            lines.extend(_render_remediation_priority_table_markdown(findings))
        elif section == "methodology_used":
            methodology = context.get("methodology", {})
            assert isinstance(methodology, dict)
            lines.append(f"- PTES: {methodology.get('ptes_phase_label', 'Not assigned')}")
            lines.append(f"- NIST: {methodology.get('nist_phase_label', 'Not assigned')}")
        elif section == "tools_used":
            coverage = context.get("coverage", {})
            assert isinstance(coverage, dict)
            lines.append(f"- Tools: {', '.join(coverage.get('tools', [])) or 'None recorded'}")
        elif section in {"network_discovery", "host_inventory"} and isinstance(inventory_summary, dict):
            lines.extend(_inventory_summary_lines(context))
        elif section in {"credential_findings", "ad_findings", "identity_findings", "lateral_movement"}:
            matching = [
                finding for finding in findings
                if any(token in " ".join([finding.title, finding.summary or "", finding.control_family or ""]).lower() for token in ("credential", "identity", "ldap", "ad", "lateral", "kerberos", "ntlm"))
            ]
            lines.append(f"- Relevant Findings: {len(matching)}")
        elif section in {"web_endpoints", "injection_findings", "auth_findings", "header_findings"}:
            matching = [
                finding for finding in findings
                if any(token in " ".join([finding.title, finding.summary or "", finding.control_family or ""]).lower() for token in ("web", "http", "header", "injection", "auth", "xss", "sql"))
            ]
            lines.append(f"- Relevant Findings: {len(matching)}")
        elif section in {"api_endpoints", "business_logic_findings"}:
            matching = [
                finding for finding in findings
                if any(token in " ".join([finding.title, finding.summary or "", finding.control_family or ""]).lower() for token in ("api", "graphql", "business", "logic"))
            ]
            lines.append(f"- Relevant Findings: {len(matching)}")
        elif section in {"cloud_inventory", "iam_findings", "exposure_findings"}:
            matching = [
                finding for finding in findings
                if any(token in " ".join([finding.title, finding.summary or "", finding.control_family or ""]).lower() for token in ("cloud", "iam", "exposure", "aws", "azure", "gcp"))
            ]
            lines.append(f"- Relevant Findings: {len(matching)}")
        elif section == "iot_security_summary":
            lines.extend(_iot_security_summary_lines(context))
        elif section == "wifi_security_summary":
            lines.extend(_wifi_security_summary_lines(context))
        else:
            lines.append("- Included because the run profile or executed tools touched this evidence surface.")
        lines.append("")
    return lines


def _render_adaptive_technical_sections_html(context: dict[str, object]) -> str:
    sections = [str(section) for section in context.get("report_sections", [])]
    items = "".join(
        f"<li>{escape(REPORT_SECTION_LABELS.get(section, _humanize_key(section)))}</li>"
        for section in sections
    )
    iot_summary = _iot_security_summary_html(context) if "iot_security_summary" in sections else ""
    wifi_summary = _wifi_security_summary_html(context) if "wifi_security_summary" in sections else ""
    return f"""
    <section class="panel">
      <h2>Adaptive Technical Sections</h2>
      <p>The technical report only opens sections supported by the recorded run profile, tools, tasks, findings, or inventory.</p>
      <ul class="meta-list">{items}</ul>
    </section>
    {iot_summary}
    {wifi_summary}
    """


def _retest_metadata_for_run(run: Run) -> dict[str, object] | None:
    configuration = run.configuration_json if isinstance(run.configuration_json, dict) else {}
    retest = configuration.get("retest")
    return dict(retest) if isinstance(retest, dict) and retest.get("mode") == "single_finding" else None


def _retest_verification_timestamp(run: Run) -> str:
    if run.status in {"completed", "completed_with_errors", "failed", "cancelled"}:
        return run.updated_at.isoformat()
    return "Pending retest execution completion"


def _render_retest_evidence_markdown(tasks: list[Task]) -> list[str]:
    if not tasks:
        return ["- No retest tasks recorded yet.", ""]

    lines: list[str] = []
    for task in tasks:
        lines.extend(
            [
                f"### Retest Task {task.id}",
                "",
                f"- Tool: {task.tool}",
                f"- Target: {task_targets_display(task)}",
                f"- Status: {task.status}",
            ]
        )
        if task.executions:
            for execution in task.executions:
                lines.append(
                    f"- Execution {execution.id}: exit_code={execution.exit_code}, tool_version={execution.tool_version}"
                )
                artifacts = sort_artifacts(list(execution.artifacts))
                if artifacts:
                    for artifact in artifacts:
                        artifact_name = str(artifact.metadata_json.get("name", artifact.id))
                        lines.append(
                            f"  artifact: {artifact_name} ({artifact.uri}) download={artifact_download_path(artifact.id)}"
                        )
                else:
                    lines.append("  artifact: no artifact recorded for this execution")
        else:
            lines.append("- No executions recorded for this retest task yet.")
        lines.append("")
    return lines


def _render_proof_of_resolution_markdown(run: Run, context: dict[str, object]) -> list[str]:
    retest = _retest_metadata_for_run(run)
    if retest is None:
        return [
            "## Proof of Resolution",
            "",
            "- This run is not linked to a single-finding retest request yet.",
            "",
        ]

    tasks = context["tasks"]
    assert isinstance(tasks, list)
    lines = [
        "## Proof of Resolution",
        "",
        f"- Source Finding: {retest.get('source_finding_title') or 'Not recorded'}",
        f"- Source Finding ID: {retest.get('source_finding_id') or 'Not recorded'}",
        f"- Source Run ID: {retest.get('source_run_id') or 'Not recorded'}",
        f"- Source Severity: {retest.get('source_finding_severity') or 'Not recorded'}",
        f"- Source Status Before Retest: {retest.get('source_finding_status') or 'Not recorded'}",
        f"- Source Target: {retest.get('source_finding_target') or 'Not recorded'}",
        f"- Source Evidence Ref: {retest.get('source_evidence_ref') or 'Not recorded'}",
        f"- Source Summary: {retest.get('source_finding_summary') or retest.get('source_summary') or 'Not recorded'}",
        f"- Remediation State: {retest.get('remediation_state') or 'Not recorded'}",
        f"- Remediation Notes: {retest.get('remediation_notes') or 'Not recorded'}",
        f"- Retest Operator Notes: {retest.get('operator_notes') or 'Not recorded'}",
        f"- Retest Run Status: {run.status}",
        f"- Verification Timestamp: {_retest_verification_timestamp(run)}",
        "",
        "## Retest Evidence",
        "",
    ]
    lines.extend(_render_retest_evidence_markdown(tasks))
    return lines


def _render_retest_evidence_html(tasks: list[Task]) -> str:
    if not tasks:
        return "<p>No retest tasks recorded yet.</p>"

    task_cards: list[str] = []
    for task in tasks:
        execution_items: list[str] = []
        for execution in task.executions:
            artifact_items = "".join(
                "<li>"
                f"{escape(str(artifact.metadata_json.get('name', artifact.id)))} - "
                f"<code>{escape(artifact.uri)}</code> - "
                f"<a href=\"{escape(artifact_download_path(artifact.id))}\">download</a>"
                "</li>"
                for artifact in sort_artifacts(list(execution.artifacts))
            )
            execution_items.append(
                "<li>"
                f"Execution {escape(str(execution.id))}: "
                f"exit_code={escape(str(execution.exit_code))}, "
                f"tool_version={escape(execution.tool_version)}"
                + (
                    f"<ul>{artifact_items}</ul>"
                    if artifact_items
                    else "<ul><li>No artifact recorded for this execution.</li></ul>"
                )
                + "</li>"
            )
        if not execution_items:
            execution_items.append("<li>No executions recorded for this retest task yet.</li>")

        task_cards.append(
            "<article class='task'>"
            f"<h3>Retest Task {escape(str(task.id))}</h3>"
            f"<p><strong>Tool:</strong> {escape(task.tool)} | "
            f"<strong>Target:</strong> {escape(task_targets_display(task))} | "
            f"<strong>Status:</strong> {escape(task.status)}</p>"
            f"<ul>{''.join(execution_items)}</ul>"
            "</article>"
        )
    return "".join(task_cards)


def _render_proof_of_resolution_html(run: Run, context: dict[str, object]) -> str:
    retest = _retest_metadata_for_run(run)
    if retest is None:
        return """
        <section class="panel">
          <h2>Proof of Resolution</h2>
          <p>This run is not linked to a single-finding retest request yet.</p>
        </section>
        """

    tasks = context["tasks"]
    assert isinstance(tasks, list)
    proof_rows = [
        ("Source Finding", retest.get("source_finding_title") or "Not recorded"),
        ("Source Finding ID", retest.get("source_finding_id") or "Not recorded"),
        ("Source Run ID", retest.get("source_run_id") or "Not recorded"),
        ("Source Severity", retest.get("source_finding_severity") or "Not recorded"),
        ("Source Status Before Retest", retest.get("source_finding_status") or "Not recorded"),
        ("Source Target", retest.get("source_finding_target") or "Not recorded"),
        ("Source Evidence Ref", retest.get("source_evidence_ref") or "Not recorded"),
        (
            "Source Summary",
            retest.get("source_finding_summary") or retest.get("source_summary") or "Not recorded",
        ),
        ("Remediation State", retest.get("remediation_state") or "Not recorded"),
        ("Remediation Notes", retest.get("remediation_notes") or "Not recorded"),
        ("Retest Operator Notes", retest.get("operator_notes") or "Not recorded"),
        ("Retest Run Status", run.status),
        ("Verification Timestamp", _retest_verification_timestamp(run)),
    ]
    rows_html = "".join(
        f"<tr><th>{escape(label)}</th><td>{escape(str(value))}</td></tr>" for label, value in proof_rows
    )
    return f"""
    <section class="panel">
      <h2>Proof of Resolution</h2>
      <table>{rows_html}</table>
      <h3>Retest Evidence</h3>
      {_render_retest_evidence_html(tasks)}
    </section>
    """


def _assurance_finding_state(finding: Finding) -> str:
    if finding.status == "resolved":
        return "resolved in the finding record; retain linked evidence and retest proof before relying on closure"
    if finding.status == "accepted_risk":
        return "accepted residual risk"
    if finding.status == "false_positive":
        return "marked false positive in the finding record"
    if finding.status in ASSURANCE_UNRESOLVED_STATUSES:
        return "unresolved or not yet verified"
    return f"recorded status: {finding.status}"


def _finding_remediation_state(finding: Finding) -> str:
    remediation = getattr(finding, "remediation", None)
    if remediation is None:
        return "not recorded"
    return str(remediation.state or "not recorded")


def _render_assurance_finding_markdown(finding: Finding) -> list[str]:
    return [
        f"### {finding.title}",
        "",
        f"- Assurance State: {_assurance_finding_state(finding)}",
        f"- Severity: {finding.severity}",
        f"- Finding Status: {finding.status}",
        f"- Remediation State: {_finding_remediation_state(finding)}",
        f"- Target: {finding.target_id}",
        f"- Evidence Ref: {finding.evidence_ref or 'not linked'}",
        f"- Replay Status: {replay_status_for_finding(finding)}",
        f"- Methodology Tags: {', '.join(finding.methodology_tags or []) or 'None'}",
        f"- PTES Phase: {ptes_phase_label(finding.ptes_phase) or 'Not Assigned'}",
        f"- NIST Phase: {nist_phase_label(finding.nist_phase) or 'Not Assigned'}",
        f"- WSTG Reference: {format_wstg_reference(finding.wstg_id, finding.wstg_version) or 'Not Assigned'}",
        f"- Summary: {finding.summary or 'No summary recorded.'}",
        "",
    ]


def _render_assurance_markdown(run: Run, context: dict[str, object]) -> str:
    assurance = assurance_package_context(context)
    findings = context["findings"]
    tasks = context["tasks"]
    latest_scope = context["latest_scope"]
    methodology = context["methodology"]
    coverage = context["coverage"]
    adaptive_pack = context["adaptive_pack"]
    inventory_summary = context["inventory_summary"]
    assert isinstance(findings, list)
    assert isinstance(tasks, list)
    assert isinstance(methodology, dict)
    assert isinstance(coverage, dict)
    assert isinstance(adaptive_pack, dict)
    assert isinstance(inventory_summary, dict)

    residual_findings = [
        finding
        for finding in findings
        if isinstance(finding, Finding) and finding.status in ASSURANCE_RESIDUAL_RISK_STATUSES
    ]
    evidence_linked = [finding for finding in findings if isinstance(finding, Finding) and finding.evidence_ref]
    artifact_lines: list[str] = []
    for task in tasks:
        assert isinstance(task, Task)
        for execution in task.executions or []:
            for artifact in sort_artifacts(list(execution.artifacts)):
                artifact_lines.append(
                    f"- {task.tool} / {task_targets_display(task)}: {artifact.kind} {artifact.uri} "
                    f"(redaction={artifact.redaction_state}, sha256={artifact.sha256})"
                )

    lines = [
        f"# AegisPT Evidence-Backed Assurance Package: {run.id}",
        "",
        "## Assurance Boundary",
        "",
        "- This package is not a certification, attestation, or guarantee of security.",
        "- Based on the scoped validation evidence, it summarizes what AegisPT tested and recorded for this run.",
        "- For the tested scope and time window, statements are limited to persisted evidence, findings, methodology metadata, remediation state, retest state, and report provenance.",
        "- No evidence-backed finding records were omitted from the residual-risk view.",
        "",
        "## Engagement and Scope",
        "",
        f"- Engagement: {context['engagement_name']}",
        f"- Client: {context['client_name']}",
        f"- Run ID: {run.id}",
        f"- Run Profile: {context['profile_name']}",
        f"- Run Status: {run.status}",
        f"- Created At: {run.created_at.isoformat()}",
        f"- ROE Reference: {run.engagement.roe_ref if run.engagement is not None and run.engagement.roe_ref else 'Not Recorded'}",
        "",
    ]

    if latest_scope is not None:
        lines.extend(
            [
                "### Recorded Allowlist",
                "",
                "```json",
                format_json_block(latest_scope.allowlist_json),
                "```",
                "",
                "### Recorded Denylist",
                "",
                "```json",
                format_json_block(latest_scope.denylist_json),
                "```",
                "",
            ]
        )
    else:
        lines.extend(["- No scope snapshot loaded for this run.", ""])

    lines.extend(
        [
            "## What Was Tested",
            "",
            f"- Assessment Type: {context['configuration'].get('assessment_type') if isinstance(context['configuration'], dict) else 'Not recorded'}",
            f"- Tools Executed: {', '.join(coverage.get('tools', [])) or 'None recorded'}",
            f"- Tasks Recorded: {assurance['task_count']}",
            f"- Hosts Observed: {inventory_summary.get('host_count', 0)}",
            f"- Services Observed: {inventory_summary.get('service_count', 0)}",
            f"- Endpoints Observed: {inventory_summary.get('endpoint_count', 0)}",
            f"- PTES Mapping for This Run: {methodology['ptes_phase_label']}",
            f"- NIST Mapping for This Run: {methodology['nist_phase_label']}",
            f"- Runtime Pack: {adaptive_pack['label']}",
            "",
            "## Evidence Basis",
            "",
            f"- Evidence-Linked Findings: {assurance['evidence_linked_findings']} of {assurance['total_findings']}",
            f"- Evidence Artifacts Recorded: {assurance['evidence_artifacts']}",
            f"- Methodology References: {', '.join(report_methodology_references_for_variant(run, 'assurance'))}",
            "",
        ]
    )
    lines.extend(artifact_lines or ["- No task evidence artifacts were recorded for this run."])
    lines.extend(
        [
            "",
            "## Findings and Residual Risk",
            "",
            f"- Total Findings Reviewed: {assurance['total_findings']}",
            f"- Evidence-Linked Findings: {len(evidence_linked)}",
            f"- Resolved Findings Recorded: {assurance['resolved_findings']}",
            f"- Accepted-Risk Findings: {assurance['accepted_risk_findings']}",
            f"- Unresolved or Unverified Findings: {assurance['unresolved_findings']}",
            f"- False-Positive Findings: {assurance['false_positive_findings']}",
            "",
        ]
    )

    if not findings:
        lines.extend(
            [
                "No confirmed findings were recorded in this run. This means no evidence-backed finding records were created by the executed checks; it does not prove the target is free of risk or exhaustively tested.",
                "",
            ]
        )
    else:
        for finding in findings:
            assert isinstance(finding, Finding)
            lines.extend(_render_assurance_finding_markdown(finding))

    lines.extend(["## Unresolved or Unverified Items", ""])
    if residual_findings:
        for finding in residual_findings:
            lines.append(f"- {finding.severity.upper()}: {finding.title} ({_assurance_finding_state(finding)})")
    else:
        lines.append("- No unresolved or accepted-risk finding records are currently attached to this run.")
    lines.extend(
        [
            "",
            "## Out of Scope",
            "",
            *[f"- {item}" for item in assurance["out_of_scope_items"]],
            "",
            "## Recommended Assurance Follow-Up",
            "",
            "- Review unresolved and accepted-risk findings before sharing this package as closure evidence.",
            "- Attach retest proof for remediated findings before treating them as operationally closed.",
            "- Re-run scoped validation when the target, environment, or controls materially change.",
            "",
        ]
    )

    return "\n".join(lines).rstrip() + "\n"


def _render_assurance_html(run: Run, context: dict[str, object]) -> str:
    assurance = assurance_package_context(context)
    findings = context["findings"]
    tasks = context["tasks"]
    coverage = context["coverage"]
    latest_scope = context["latest_scope"]
    assert isinstance(findings, list)
    assert isinstance(tasks, list)
    assert isinstance(coverage, dict)

    residual_items = "".join(
        "<li>"
        f"{escape(finding.severity.upper())}: {escape(finding.title)} "
        f"({escape(_assurance_finding_state(finding))})"
        "</li>"
        for finding in findings
        if isinstance(finding, Finding) and finding.status in ASSURANCE_RESIDUAL_RISK_STATUSES
    ) or "<li>No unresolved or accepted-risk finding records are currently attached to this run.</li>"

    finding_cards = "".join(
        "<article class='finding'>"
        f"<div class='finding-header'><h3>{escape(finding.title)}</h3>"
        f"<span class='priority'>{escape(_assurance_finding_state(finding))}</span></div>"
        f"<p><strong>Severity:</strong> {escape(finding.severity)} | "
        f"<strong>Status:</strong> {escape(finding.status)} | "
        f"<strong>Remediation State:</strong> {escape(_finding_remediation_state(finding))}</p>"
        f"<p><strong>Target:</strong> {escape(finding.target_id)}</p>"
        f"<p><strong>Evidence Ref:</strong> <code>{escape(finding.evidence_ref or 'not linked')}</code></p>"
        f"<p><strong>Methodology:</strong> PTES {escape(ptes_phase_label(finding.ptes_phase) or 'Not Assigned')} | "
        f"NIST {escape(nist_phase_label(finding.nist_phase) or 'Not Assigned')} | "
        f"WSTG {escape(format_wstg_reference(finding.wstg_id, finding.wstg_version) or 'Not Assigned')}</p>"
        + (f"<p>{escape(finding.summary)}</p>" if finding.summary else "")
        + "</article>"
        for finding in findings
        if isinstance(finding, Finding)
    ) or "<p>No confirmed findings were recorded in this run. This does not prove the target is free of risk or exhaustively tested.</p>"

    artifact_items: list[str] = []
    for task in tasks:
        assert isinstance(task, Task)
        for execution in task.executions or []:
            for artifact in sort_artifacts(list(execution.artifacts)):
                artifact_items.append(
                    "<li>"
                    f"{escape(task.tool)} / {escape(task_targets_display(task))}: "
                    f"{escape(artifact.kind)} <code>{escape(artifact.uri)}</code> "
                    f"(redaction={escape(artifact.redaction_state)}, sha256={escape(artifact.sha256)})"
                    "</li>"
                )

    scope_note = (
        "Recorded allowlist and denylist are included in the Scope section of this report."
        if latest_scope is not None
        else "No scope snapshot was loaded for this run."
    )
    tools = coverage.get("tools", [])
    tools_label = ", ".join(tools) if isinstance(tools, list) and tools else "None recorded"

    return f"""
    <section class="panel">
      <h2>Assurance Boundary</h2>
      <p><strong>This package is not a certification, attestation, or guarantee of security.</strong></p>
      <p>Based on the scoped validation evidence, it summarizes what AegisPT tested and recorded for this run.</p>
      <p>For the tested scope and time window, statements are limited to persisted evidence, findings, methodology metadata, remediation state, retest state, and report provenance.</p>
      <p>{escape(scope_note)}</p>
    </section>

    <section class="panel">
      <h2>Assurance Evidence Summary</h2>
      <ul class="meta-list">
        <li><strong>Tools Executed:</strong> {escape(tools_label)}</li>
        <li><strong>Tasks Recorded:</strong> {escape(str(assurance['task_count']))}</li>
        <li><strong>Total Findings Reviewed:</strong> {escape(str(assurance['total_findings']))}</li>
        <li><strong>Evidence-Linked Findings:</strong> {escape(str(assurance['evidence_linked_findings']))}</li>
        <li><strong>Evidence Artifacts Recorded:</strong> {escape(str(assurance['evidence_artifacts']))}</li>
        <li><strong>Unresolved or Unverified Findings:</strong> {escape(str(assurance['unresolved_findings']))}</li>
        <li><strong>Accepted-Risk Findings:</strong> {escape(str(assurance['accepted_risk_findings']))}</li>
      </ul>
    </section>

    <section class="panel">
      <h2>Evidence Artifacts</h2>
      <ul class="meta-list">{''.join(artifact_items) or '<li>No task evidence artifacts were recorded for this run.</li>'}</ul>
    </section>

    <section class="panel">
      <h2>Findings and Residual Risk</h2>
      {finding_cards}
    </section>

    <section class="panel">
      <h2>Unresolved or Unverified Items</h2>
      <ul class="meta-list">{residual_items}</ul>
    </section>

    <section class="panel">
      <h2>Out of Scope</h2>
      <ul class="meta-list">{''.join(f'<li>{escape(item)}</li>' for item in assurance['out_of_scope_items'])}</ul>
    </section>
    """


def _render_configuration_markdown(context: dict[str, object]) -> list[str]:
    configuration = context["configuration"]
    assert isinstance(configuration, dict)
    eta = configuration.get("eta", {})
    safety = configuration.get("safety", {})
    targets = configuration.get("targets", {})
    lines = [
        "## Run Configuration",
        "",
        f"- Assessment Type: {configuration.get('assessment_type') or 'Not Recorded'}",
        f"- Test Profile: {configuration.get('test_profile') or 'Not Recorded'}",
        f"- Enabled Modules: {', '.join(configuration.get('enabled_modules', [])) or 'Not Recorded'}",
        f"- Active Accounts / Roles: {', '.join(configuration.get('accounts_summary', [])) or 'None Recorded'}",
        "",
    ]
    lines.extend(["### Target Inputs", ""])
    lines.extend(_render_key_values_markdown(targets if isinstance(targets, dict) else {}))
    lines.extend(["", "### Safety Settings", ""])
    lines.extend(_render_key_values_markdown(safety if isinstance(safety, dict) else {}))
    lines.extend(["", "### ETA Model", ""])
    lines.extend(_render_key_values_markdown(eta if isinstance(eta, dict) else {}))
    lines.append("")
    return lines


def _render_configuration_html(context: dict[str, object]) -> str:
    configuration = context["configuration"]
    assert isinstance(configuration, dict)
    return (
        "<ul>"
        f"<li><strong>Assessment Type:</strong> {escape(str(configuration.get('assessment_type') or 'Not Recorded'))}</li>"
        f"<li><strong>Test Profile:</strong> {escape(str(configuration.get('test_profile') or 'Not Recorded'))}</li>"
        f"<li><strong>Enabled Modules:</strong> {escape(', '.join(configuration.get('enabled_modules', [])) or 'Not Recorded')}</li>"
        f"<li><strong>Active Accounts / Roles:</strong> {escape(', '.join(configuration.get('accounts_summary', [])) or 'None Recorded')}</li>"
        "</ul>"
        "<h3>Target Inputs</h3>"
        f"{_render_key_values_html(configuration.get('targets', {}) if isinstance(configuration.get('targets'), dict) else {})}"
        "<h3>Safety Settings</h3>"
        f"{_render_key_values_html(configuration.get('safety', {}) if isinstance(configuration.get('safety'), dict) else {})}"
        "<h3>ETA Model</h3>"
        f"{_render_key_values_html(configuration.get('eta', {}) if isinstance(configuration.get('eta'), dict) else {})}"
    )


def _render_adaptive_change_markdown(context: dict[str, object]) -> list[str]:
    adaptive_change = context["adaptive_change"]
    assert isinstance(adaptive_change, dict)
    if not adaptive_change.get("active"):
        return [
            "## Adaptive Change Summary",
            "",
            f"- {adaptive_change.get('summary_line')}",
            "",
        ]

    latest_task = adaptive_change.get("latest_task") if isinstance(adaptive_change.get("latest_task"), dict) else None
    lines = [
        "## Adaptive Change Summary",
        "",
        f"- Summary: {adaptive_change.get('summary_line')}",
        f"- Governance: {adaptive_change.get('governance_line')}",
        f"- Findings Linked to This Pack: {adaptive_change.get('finding_line')}",
        f"- Threat Intel References: {', '.join(adaptive_change.get('source_threat_intel_refs', [])) or 'None'}",
        f"- Methodology Tags: {', '.join(adaptive_change.get('methodology_tags', [])) or 'None'}",
    ]
    if latest_task is not None:
        lines.extend(
            [
                (
                    f"- Latest Codex Task: {latest_task.get('id')} ({latest_task.get('task_type')}) "
                    f"status={latest_task.get('status')} validation={latest_task.get('validation_status')}"
                ),
                f"- Task Reason: {latest_task.get('generation_reason') or 'Not recorded'}",
            ]
        )
        if latest_task.get("prepared_result_status"):
            lines.append(
                "- Prepared Review Bundle: "
                f"{latest_task.get('prepared_result_status')} with "
                f"{latest_task.get('prepared_command_count', 0)} commands and "
                f"{latest_task.get('prepared_output_count', 0)} output files"
            )
    lines.append("")
    return lines


def _render_adaptive_change_html(context: dict[str, object]) -> str:
    adaptive_change = context["adaptive_change"]
    assert isinstance(adaptive_change, dict)
    latest_task = adaptive_change.get("latest_task") if isinstance(adaptive_change.get("latest_task"), dict) else None
    items = [
        f"<li><strong>Summary:</strong> {escape(str(adaptive_change.get('summary_line') or 'Not recorded'))}</li>",
        f"<li><strong>Governance:</strong> {escape(str(adaptive_change.get('governance_line') or 'Not recorded'))}</li>",
        f"<li><strong>Findings Linked to This Pack:</strong> {escape(str(adaptive_change.get('finding_line') or 'Not recorded'))}</li>",
        f"<li><strong>Threat Intel References:</strong> {escape(', '.join(adaptive_change.get('source_threat_intel_refs', [])) or 'None')}</li>",
        f"<li><strong>Methodology Tags:</strong> {escape(', '.join(adaptive_change.get('methodology_tags', [])) or 'None')}</li>",
    ]
    if latest_task is not None:
        items.append(
            "<li><strong>Latest Codex Task:</strong> "
            f"{escape(str(latest_task.get('id')))} "
            f"({escape(str(latest_task.get('task_type') or 'unknown'))}) "
            f"status={escape(str(latest_task.get('status') or 'unknown'))} "
            f"validation={escape(str(latest_task.get('validation_status') or 'unknown'))}</li>"
        )
        items.append(
            f"<li><strong>Task Reason:</strong> {escape(str(latest_task.get('generation_reason') or 'Not recorded'))}</li>"
        )
        if latest_task.get("prepared_result_status"):
            items.append(
                "<li><strong>Prepared Review Bundle:</strong> "
                f"{escape(str(latest_task.get('prepared_result_status')))} with "
                f"{escape(str(latest_task.get('prepared_command_count', 0)))} commands and "
                f"{escape(str(latest_task.get('prepared_output_count', 0)))} output files</li>"
            )
    return f"<ul>{''.join(items)}</ul>"


def _render_soc2_finding_markdown(finding: Finding, mapping_reason: str) -> list[str]:
    lines = [
        f"#### {finding.title}",
        "",
        f"- Mapping Reason: {mapping_reason}",
        f"- Severity: {finding.severity}",
        f"- Status: {finding.status}",
        f"- Target: {finding.target_id}",
        f"- Evidence Ref: {finding.evidence_ref}",
        f"- Replay Status: {replay_status_for_finding(finding)}",
    ]
    lines.extend(finding_methodology_lines(finding))
    if finding.summary:
        lines.append(f"- Summary: {finding.summary}")
    lines.extend(
        [
            f"- Remediation Summary: {default_remediation_summary(finding.control_family)}",
            "",
        ]
    )
    return lines


def _render_soc2_markdown(run: Run, context: dict[str, object]) -> str:
    soc2 = soc2_report_package_context(context)
    advisor = compliance_gap_advisor_context(context, "soc2")
    coverage_rows = soc2["coverage_rows"]
    active_groups = soc2["active_groups"]
    unmapped = soc2["unmapped"]
    assert isinstance(coverage_rows, list)
    assert isinstance(active_groups, list)
    assert isinstance(unmapped, list)

    lines = [
        f"# AegisPT SOC 2 Report Package: {run.id}",
        "",
        "## Package Boundary",
        "",
        f"- Compliance Package: {soc2['reference']}",
        "- Trust Services Category: Security",
        "- Evidence Source: existing AegisPT findings, tasks, artifacts, scope, and methodology metadata.",
        "- Mapping Layer: separate report-time SOC 2 control mapping table; Prompt 1 methodology definitions remain unchanged.",
        "- Attestation Boundary: this package supports SOC 2 control review, but it is not a CPA attestation opinion.",
        "",
        "## Run Context",
        "",
        f"- Engagement: {context['engagement_name']}",
        f"- Client: {context['client_name']}",
        f"- Run Profile: {context['profile_name']}",
        f"- Run Status: {run.status}",
        f"- Requested By: {run.requested_by}",
        f"- Created At: {run.created_at.isoformat()}",
        "",
        *_render_configuration_markdown(context),
        "## Discovery Summary",
        "",
        *_inventory_summary_lines(context),
        "## SOC 2 Coverage Summary",
        "",
        f"- Total Findings Reviewed: {soc2['total_findings']}",
        f"- Mapped Findings: {soc2['mapped_findings']}",
        f"- Unmapped Findings: {soc2['unmapped_findings']}",
        f"- SOC 2 Controls With Findings: {soc2['mapped_control_count']} of {soc2['total_mapped_controls']}",
        "",
        "| SOC 2 Control | Title | Findings | Mapping Basis |",
        "| --- | --- | ---: | --- |",
    ]
    for row in coverage_rows:
        assert isinstance(row, dict)
        lines.append(
            f"| {row['control_id']} | {row['title']} | {row['finding_count']} | {row['basis']} |"
        )

    lines.extend(["", *_render_compliance_gap_advisor_markdown(advisor)])

    lines.extend(
        [
            "",
            "## Findings by SOC 2 Control",
            "",
        ]
    )

    if soc2["zero_finding_path"]:
        lines.extend(
            [
                "- No confirmed findings were recorded for this run.",
                "- This zero-finding path does not assert that SOC 2 controls are effective; it only states that the current AegisPT run produced no evidence-backed findings to map.",
                "",
            ]
        )
    else:
        for group in active_groups:
            assert isinstance(group, dict)
            mapping = group["mapping"]
            assert isinstance(mapping, dict)
            finding_records = group["findings"]
            assert isinstance(finding_records, list)
            lines.extend(
                [
                    f"### {mapping['control_id']} - {mapping['title']}",
                    "",
                    f"- Trust Services Category: {mapping['trust_service_category']}",
                    f"- Mapping Basis: {mapping['basis']}",
                    "",
                ]
            )
            for record in finding_records:
                assert isinstance(record, dict)
                finding = record["finding"]
                assert isinstance(finding, Finding)
                lines.extend(_render_soc2_finding_markdown(finding, str(record["mapping_reason"])))

        if unmapped:
            lines.extend(
                [
                    "### Manual SOC 2 Review Queue",
                    "",
                    "- These findings remain evidence-backed AegisPT findings, but the current SOC 2 mapping table does not assign them to a control reference automatically.",
                    "",
                ]
            )
            for finding in unmapped:
                assert isinstance(finding, Finding)
                lines.extend(_render_soc2_finding_markdown(finding, "no SOC 2 report-time mapping matched"))

    lines.extend(
        [
            "## Methodology References",
            "",
            *[f"- {reference}" for reference in report_methodology_references_for_variant(run, "soc2")],
            "",
        ]
    )
    return "\n".join(lines).rstrip() + "\n"


def _render_soc2_html(run: Run, context: dict[str, object]) -> str:
    soc2 = soc2_report_package_context(context)
    advisor = compliance_gap_advisor_context(context, "soc2")
    coverage_rows = soc2["coverage_rows"]
    active_groups = soc2["active_groups"]
    unmapped = soc2["unmapped"]
    assert isinstance(coverage_rows, list)
    assert isinstance(active_groups, list)
    assert isinstance(unmapped, list)

    coverage_html = "".join(
        "<tr>"
        f"<td>{escape(str(row['control_id']))}</td>"
        f"<td>{escape(str(row['title']))}</td>"
        f"<td>{escape(str(row['finding_count']))}</td>"
        f"<td>{escape(str(row['basis']))}</td>"
        "</tr>"
        for row in coverage_rows
        if isinstance(row, dict)
    )

    if soc2["zero_finding_path"]:
        findings_html = """
        <p>No confirmed findings were recorded for this run.</p>
        <p>This zero-finding path does not assert that SOC 2 controls are effective; it only states that the current AegisPT run produced no evidence-backed findings to map.</p>
        """
    else:
        group_sections: list[str] = []
        for group in active_groups:
            assert isinstance(group, dict)
            mapping = group["mapping"]
            assert isinstance(mapping, dict)
            finding_records = group["findings"]
            assert isinstance(finding_records, list)
            finding_cards: list[str] = []
            for record in finding_records:
                assert isinstance(record, dict)
                finding = record["finding"]
                assert isinstance(finding, Finding)
                finding_cards.append(
                    "<article class='finding'>"
                    f"<div class='finding-header'><h3>{escape(finding.title)}</h3><span class='priority'>{escape(remediation_priority_for_finding(finding))}</span></div>"
                    f"<p><strong>Mapping Reason:</strong> {escape(str(record['mapping_reason']))}</p>"
                    f"<p><strong>Severity:</strong> {escape(finding.severity)} | "
                    f"<strong>Status:</strong> {escape(finding.status)} | "
                    f"<strong>Target:</strong> {escape(finding.target_id)}</p>"
                    f"<p><strong>Evidence Ref:</strong> <code>{escape(finding.evidence_ref)}</code></p>"
                    f"<p><strong>WSTG:</strong> {escape(format_wstg_reference(finding.wstg_id, finding.wstg_version) or 'Not Assigned')} | "
                    f"<strong>Control Family:</strong> {escape(control_family_label(finding.control_family) or 'Not Assigned')}</p>"
                    + (f"<p>{escape(finding.summary)}</p>" if finding.summary else "")
                    + f"<p><strong>Remediation Summary:</strong> {escape(default_remediation_summary(finding.control_family))}</p>"
                    "</article>"
                )
            group_sections.append(
                "<section class='panel'>"
                f"<h3>{escape(str(mapping['control_id']))} - {escape(str(mapping['title']))}</h3>"
                f"<p><strong>Trust Services Category:</strong> {escape(str(mapping['trust_service_category']))}</p>"
                f"<p><strong>Mapping Basis:</strong> {escape(str(mapping['basis']))}</p>"
                f"{''.join(finding_cards)}"
                "</section>"
            )

        if unmapped:
            unmapped_cards = "".join(
                (
                    "<article class='finding'>"
                    f"<div class='finding-header'><h3>{escape(finding.title)}</h3><span class='priority'>{escape(remediation_priority_for_finding(finding))}</span></div>"
                    "<p><strong>Mapping Reason:</strong> no SOC 2 report-time mapping matched</p>"
                    f"<p><strong>Severity:</strong> {escape(finding.severity)} | "
                    f"<strong>Status:</strong> {escape(finding.status)} | "
                    f"<strong>Target:</strong> {escape(finding.target_id)}</p>"
                    f"<p><strong>Evidence Ref:</strong> <code>{escape(finding.evidence_ref)}</code></p>"
                    + (f"<p>{escape(finding.summary)}</p>" if finding.summary else "")
                    + "</article>"
                )
                for finding in unmapped
                if isinstance(finding, Finding)
            )
            group_sections.append(
                "<section class='panel'>"
                "<h3>Manual SOC 2 Review Queue</h3>"
                "<p>These findings remain evidence-backed AegisPT findings, but the current SOC 2 mapping table does not assign them to a control reference automatically.</p>"
                f"{unmapped_cards}"
                "</section>"
            )
        findings_html = "".join(group_sections)

    methodology_refs = "".join(
        f"<li>{escape(reference)}</li>"
        for reference in report_methodology_references_for_variant(run, "soc2")
    )

    return f"""
    <section class="panel">
      <h2>SOC 2 Package Boundary</h2>
      <ul class="meta-list">
        <li><strong>Compliance Package:</strong> {escape(str(soc2['reference']))}</li>
        <li><strong>Trust Services Category:</strong> Security</li>
        <li><strong>Evidence Source:</strong> existing AegisPT findings, tasks, artifacts, scope, and methodology metadata.</li>
        <li><strong>Mapping Layer:</strong> separate report-time SOC 2 control mapping table; Prompt 1 methodology definitions remain unchanged.</li>
        <li><strong>Attestation Boundary:</strong> this package supports SOC 2 control review, but it is not a CPA attestation opinion.</li>
      </ul>
    </section>
    <section class="panel">
      <h2>SOC 2 Coverage Summary</h2>
      <p><strong>Total Findings Reviewed:</strong> {escape(str(soc2['total_findings']))}</p>
      <p><strong>Mapped Findings:</strong> {escape(str(soc2['mapped_findings']))}</p>
      <p><strong>Unmapped Findings:</strong> {escape(str(soc2['unmapped_findings']))}</p>
      <p><strong>SOC 2 Controls With Findings:</strong> {escape(str(soc2['mapped_control_count']))} of {escape(str(soc2['total_mapped_controls']))}</p>
      <table>
        <thead><tr><th>SOC 2 Control</th><th>Title</th><th>Findings</th><th>Mapping Basis</th></tr></thead>
        <tbody>{coverage_html}</tbody>
      </table>
    </section>
    {_render_compliance_gap_advisor_html(advisor)}
    <section class="panel">
      <h2>Findings by SOC 2 Control</h2>
      {findings_html}
    </section>
    <section class="panel">
      <h2>Methodology References</h2>
      <ul class="meta-list">{methodology_refs}</ul>
    </section>
    """


def _render_compliance_finding_markdown(finding: Finding, mapping_reason: str) -> list[str]:
    return _render_soc2_finding_markdown(finding, mapping_reason)


def _render_compliance_markdown(run: Run, context: dict[str, object], variant: str) -> str:
    compliance = compliance_framework_package_context(context, variant)
    advisor = compliance_gap_advisor_context(context, variant)
    coverage_rows = compliance["coverage_rows"]
    active_groups = compliance["active_groups"]
    inactive_groups = compliance["inactive_groups"]
    unmapped = compliance["unmapped"]
    assert isinstance(coverage_rows, list)
    assert isinstance(active_groups, list)
    assert isinstance(inactive_groups, list)
    assert isinstance(unmapped, list)

    lines = [
        f"# {compliance['heading']}: {run.id}",
        "",
        "## Package Boundary",
        "",
        f"- Compliance Package: {compliance['reference']}",
        "- Evidence Source: existing AegisPT findings, tasks, artifacts, scope, and methodology metadata.",
        f"- Mapping Layer: separate report-time {compliance['package']} mapping table; Prompt 1 methodology definitions remain unchanged.",
        f"- {compliance['boundary_label']}: {compliance['boundary']}",
        "",
        "## Run Context",
        "",
        f"- Engagement: {context['engagement_name']}",
        f"- Client: {context['client_name']}",
        f"- Run Profile: {context['profile_name']}",
        f"- Run Status: {run.status}",
        f"- Requested By: {run.requested_by}",
        f"- Created At: {run.created_at.isoformat()}",
        "",
        *_render_configuration_markdown(context),
        "## Discovery Summary",
        "",
        *_inventory_summary_lines(context),
        f"## {compliance['coverage_heading']}",
        "",
        f"- Total Findings Reviewed: {compliance['total_findings']}",
        f"- Mapped Findings: {compliance['mapped_findings']}",
        f"- Unmapped Findings: {compliance['unmapped_findings']}",
        f"- {compliance['mapped_label']}: {compliance['mapped_control_count']} of {compliance['total_mapped_controls']}",
        "",
        f"| {compliance['group_label']} | Title | Findings | Mapping Basis |",
        "| --- | --- | ---: | --- |",
    ]
    for row in coverage_rows:
        assert isinstance(row, dict)
        lines.append(
            f"| {row['control_id']} | {row['title']} | {row['finding_count']} | {row['basis']} |"
        )

    lines.extend(["", *_render_compliance_gap_advisor_markdown(advisor)])

    lines.extend(["", f"## {compliance['findings_heading']}", ""])

    if compliance["zero_finding_path"]:
        lines.extend(
            [
                "- No confirmed findings were recorded for this run.",
                f"- {compliance['zero_finding_statement']}",
                "",
            ]
        )
    else:
        for group in active_groups:
            assert isinstance(group, dict)
            mapping = group["mapping"]
            assert isinstance(mapping, dict)
            finding_records = group["findings"]
            assert isinstance(finding_records, list)
            lines.extend(
                [
                    f"### {mapping['control_id']} - {mapping['title']}",
                    "",
                    f"- Mapping Basis: {mapping['basis']}",
                    "",
                ]
            )
            for record in finding_records:
                assert isinstance(record, dict)
                finding = record["finding"]
                assert isinstance(finding, Finding)
                lines.extend(_render_compliance_finding_markdown(finding, str(record["mapping_reason"])))

        if unmapped:
            lines.extend(
                [
                    f"### {compliance['manual_queue_heading']}",
                    "",
                    f"- {compliance['manual_queue_statement']}",
                    "",
                ]
            )
            for finding in unmapped:
                assert isinstance(finding, Finding)
                lines.extend(_render_compliance_finding_markdown(finding, f"no {compliance['package']} report-time mapping matched"))

    lines.extend(["", f"## {compliance['untested_heading']}", ""])
    if inactive_groups:
        lines.append(
            "- These controls or requirements did not receive evidence-backed findings in this run; absence of mapped findings is not control effectiveness or compliance."
        )
        lines.append("")
        for group in inactive_groups:
            assert isinstance(group, dict)
            mapping = group["mapping"]
            assert isinstance(mapping, dict)
            lines.append(f"- {mapping['control_id']} - {mapping['title']}: {mapping['basis']}")
    else:
        lines.append(
            "- Every currently packaged control or requirement had at least one mapped finding, but this does not represent full framework coverage."
        )

    lines.extend(
        [
            "",
            "## Methodology References",
            "",
            *[f"- {reference}" for reference in report_methodology_references_for_variant(run, variant)],
            "",
        ]
    )
    return "\n".join(lines).rstrip() + "\n"


def _render_compliance_html(run: Run, context: dict[str, object], variant: str) -> str:
    compliance = compliance_framework_package_context(context, variant)
    advisor = compliance_gap_advisor_context(context, variant)
    coverage_rows = compliance["coverage_rows"]
    active_groups = compliance["active_groups"]
    inactive_groups = compliance["inactive_groups"]
    unmapped = compliance["unmapped"]
    assert isinstance(coverage_rows, list)
    assert isinstance(active_groups, list)
    assert isinstance(inactive_groups, list)
    assert isinstance(unmapped, list)

    coverage_html = "".join(
        "<tr>"
        f"<td>{escape(str(row['control_id']))}</td>"
        f"<td>{escape(str(row['title']))}</td>"
        f"<td>{escape(str(row['finding_count']))}</td>"
        f"<td>{escape(str(row['basis']))}</td>"
        "</tr>"
        for row in coverage_rows
        if isinstance(row, dict)
    )

    if compliance["zero_finding_path"]:
        findings_html = (
            "<p>No confirmed findings were recorded for this run.</p>"
            f"<p>{escape(str(compliance['zero_finding_statement']))}</p>"
        )
    else:
        group_sections: list[str] = []
        for group in active_groups:
            assert isinstance(group, dict)
            mapping = group["mapping"]
            assert isinstance(mapping, dict)
            finding_records = group["findings"]
            assert isinstance(finding_records, list)
            finding_cards: list[str] = []
            for record in finding_records:
                assert isinstance(record, dict)
                finding = record["finding"]
                assert isinstance(finding, Finding)
                finding_cards.append(
                    "<article class='finding'>"
                    f"<div class='finding-header'><h3>{escape(finding.title)}</h3><span class='priority'>{escape(remediation_priority_for_finding(finding))}</span></div>"
                    f"<p><strong>Mapping Reason:</strong> {escape(str(record['mapping_reason']))}</p>"
                    f"<p><strong>Severity:</strong> {escape(finding.severity)} | "
                    f"<strong>Status:</strong> {escape(finding.status)} | "
                    f"<strong>Target:</strong> {escape(finding.target_id)}</p>"
                    f"<p><strong>Evidence Ref:</strong> <code>{escape(finding.evidence_ref)}</code></p>"
                    f"<p><strong>WSTG:</strong> {escape(format_wstg_reference(finding.wstg_id, finding.wstg_version) or 'Not Assigned')} | "
                    f"<strong>Control Family:</strong> {escape(control_family_label(finding.control_family) or 'Not Assigned')}</p>"
                    + (f"<p>{escape(finding.summary)}</p>" if finding.summary else "")
                    + f"<p><strong>Remediation Summary:</strong> {escape(default_remediation_summary(finding.control_family))}</p>"
                    "</article>"
                )
            group_sections.append(
                "<section class='panel'>"
                f"<h3>{escape(str(mapping['control_id']))} - {escape(str(mapping['title']))}</h3>"
                f"<p><strong>Mapping Basis:</strong> {escape(str(mapping['basis']))}</p>"
                f"{''.join(finding_cards)}"
                "</section>"
            )

        if unmapped:
            unmapped_cards = "".join(
                (
                    "<article class='finding'>"
                    f"<div class='finding-header'><h3>{escape(finding.title)}</h3><span class='priority'>{escape(remediation_priority_for_finding(finding))}</span></div>"
                    f"<p><strong>Mapping Reason:</strong> no {escape(str(compliance['package']))} report-time mapping matched</p>"
                    f"<p><strong>Severity:</strong> {escape(finding.severity)} | "
                    f"<strong>Status:</strong> {escape(finding.status)} | "
                    f"<strong>Target:</strong> {escape(finding.target_id)}</p>"
                    f"<p><strong>Evidence Ref:</strong> <code>{escape(finding.evidence_ref)}</code></p>"
                    + (f"<p>{escape(finding.summary)}</p>" if finding.summary else "")
                    + "</article>"
                )
                for finding in unmapped
                if isinstance(finding, Finding)
            )
            group_sections.append(
                "<section class='panel'>"
                f"<h3>{escape(str(compliance['manual_queue_heading']))}</h3>"
                f"<p>{escape(str(compliance['manual_queue_statement']))}</p>"
                f"{unmapped_cards}"
                "</section>"
            )
        findings_html = "".join(group_sections)

    inactive_items = "".join(
        f"<li><strong>{escape(str(group['mapping']['control_id']))} - {escape(str(group['mapping']['title']))}:</strong> {escape(str(group['mapping']['basis']))}</li>"
        for group in inactive_groups
        if isinstance(group, dict) and isinstance(group.get("mapping"), dict)
    )
    inactive_html = (
        f"<p>These controls or requirements did not receive evidence-backed findings in this run; absence of mapped findings is not control effectiveness or compliance.</p><ul class='meta-list'>{inactive_items}</ul>"
        if inactive_items
        else "<p>Every currently packaged control or requirement had at least one mapped finding, but this does not represent full framework coverage.</p>"
    )
    methodology_refs = "".join(
        f"<li>{escape(reference)}</li>"
        for reference in report_methodology_references_for_variant(run, variant)
    )

    return f"""
    <section class="panel">
      <h2>{escape(str(compliance['package']))} Package Boundary</h2>
      <ul class="meta-list">
        <li><strong>Compliance Package:</strong> {escape(str(compliance['reference']))}</li>
        <li><strong>Evidence Source:</strong> existing AegisPT findings, tasks, artifacts, scope, and methodology metadata.</li>
        <li><strong>Mapping Layer:</strong> separate report-time {escape(str(compliance['package']))} mapping table; Prompt 1 methodology definitions remain unchanged.</li>
        <li><strong>{escape(str(compliance['boundary_label']))}:</strong> {escape(str(compliance['boundary']))}</li>
      </ul>
    </section>
    <section class="panel">
      <h2>{escape(str(compliance['coverage_heading']))}</h2>
      <p><strong>Total Findings Reviewed:</strong> {escape(str(compliance['total_findings']))}</p>
      <p><strong>Mapped Findings:</strong> {escape(str(compliance['mapped_findings']))}</p>
      <p><strong>Unmapped Findings:</strong> {escape(str(compliance['unmapped_findings']))}</p>
      <p><strong>{escape(str(compliance['mapped_label']))}:</strong> {escape(str(compliance['mapped_control_count']))} of {escape(str(compliance['total_mapped_controls']))}</p>
      <table>
        <thead><tr><th>{escape(str(compliance['group_label']))}</th><th>Title</th><th>Findings</th><th>Mapping Basis</th></tr></thead>
        <tbody>{coverage_html}</tbody>
      </table>
    </section>
    {_render_compliance_gap_advisor_html(advisor)}
    <section class="panel">
      <h2>{escape(str(compliance['findings_heading']))}</h2>
      {findings_html}
    </section>
    <section class="panel">
      <h2>{escape(str(compliance['untested_heading']))}</h2>
      {inactive_html}
    </section>
    <section class="panel">
      <h2>Methodology References</h2>
      <ul class="meta-list">{methodology_refs}</ul>
    </section>
    """


def _nfir_signal_text(*parts: object) -> str:
    return " ".join(str(part or "").lower() for part in parts)


def _nfir_phase_for_text(text: str, *, default: str = "vulnerability-analysis") -> str:
    lowered = text.lower()
    if any(token in lowered for token in ("bloodhound", "sharphound", "ldap", "kerberoast", "asrep", "password-spray", "credential")):
        return "post-exploitation"
    if any(token in lowered for token in ("metasploit", "impacket", "psexec", "wmiexec", "secretsdump", "dcsync", "exploit")):
        return "exploitation"
    if any(token in lowered for token in ("nuclei", "zap", "vulnerability", "validation", "smb", "enum", "audit")):
        return "vulnerability-analysis"
    if any(token in lowered for token in ("httpx", "easm", "nmap", "discovery", "inventory", "recon", "fingerprint")):
        return "intelligence-gathering"
    if any(token in lowered for token in ("report", "retest", "remediation", "sla", "false-positive", "false_positive")):
        return "risk-analysis-remediation"
    return default


def _nfir_phase_for_task(task: Task) -> str:
    profile_name = task.params_json.get("profile_name") if isinstance(task.params_json, dict) else None
    mode = task.params_json.get("mode") if isinstance(task.params_json, dict) else None
    return _nfir_phase_for_text(
        _nfir_signal_text(task.tool, task.target_id, profile_name, mode),
        default="intelligence-gathering",
    )


def _nfir_phase_for_finding(finding: Finding) -> str:
    if str(finding.ptes_phase or "").lower() == "reporting":
        return "reporting-retest"
    if str(finding.status or "").lower() in {"resolved", "verified_resolved"}:
        return "risk-analysis-remediation"
    return _nfir_phase_for_text(
        _nfir_signal_text(
            finding.title,
            finding.target_id,
            finding.evidence_ref,
            finding.finding_origin,
            finding.control_family,
            finding.ptes_phase,
            finding.nist_phase,
            " ".join(finding.methodology_tags or []),
        ),
        default="vulnerability-analysis",
    )


def _cvss_display(finding: Finding) -> str:
    if finding.cvss_score is None:
        return "N/A"
    return f"{finding.cvss_score:g}" + (f" ({finding.cvss_vector})" if finding.cvss_vector else "")


def _finding_age_days(finding: Finding, now: datetime) -> int:
    created = finding.created_at
    if created.tzinfo is None:
        created = created.replace(tzinfo=UTC)
    return max(0, int((now - created.astimezone(UTC)).total_seconds() // 86400))


def _finding_retest_status(finding: Finding) -> str:
    records = list(finding.validation_records or [])
    if records:
        latest = sorted(records, key=lambda record: (record.created_at, record.id.hex), reverse=True)[0]
        return str(latest.status or "validation recorded").replace("_", " ")
    remediation = finding.remediation
    if remediation is not None:
        return f"remediation {remediation.state}".replace("_", " ")
    if str(finding.status or "").lower() in {"resolved", "verified_resolved"}:
        return "verified resolved in finding status"
    return "not requested"


def nfir_report_context(run: Run, context: dict[str, object]) -> dict[str, object]:
    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    tasks = [task for task in context.get("tasks", []) if isinstance(task, Task)]
    engagement = run.engagement
    now = datetime.now(UTC)
    phase_records = {
        phase["key"]: {
            **phase,
            "tasks": [],
            "findings": [],
            "status": "skipped",
            "skip_reason": "No task or finding evidence mapped to this NFIR phase for this run.",
        }
        for phase in NFIR_PHASES
    }

    for task in tasks:
        phase_records[_nfir_phase_for_task(task)]["tasks"].append(task)
    for finding in findings:
        phase_records[_nfir_phase_for_finding(finding)]["findings"].append(finding)

    authorization_recorded = bool(
        engagement is not None and (engagement.roe_ref or engagement.authorization_confirmed_at)
    )
    preparation = phase_records["preparation-authorization"]
    if authorization_recorded or context.get("approvals"):
        preparation["status"] = "executed"
        preparation["skip_reason"] = ""
    else:
        preparation["skip_reason"] = NFIR_AUTHORIZATION_WARNING

    risk_phase = phase_records["risk-analysis-remediation"]
    if findings:
        risk_phase["status"] = "executed"
        risk_phase["skip_reason"] = ""
    else:
        risk_phase["skip_reason"] = "No findings were recorded, so there is no finding-backed risk or remediation queue."

    reporting = phase_records["reporting-retest"]
    reporting["status"] = "executed"
    reporting["skip_reason"] = ""

    for record in phase_records.values():
        if record["tasks"] or record["findings"]:
            record["status"] = "executed"
            record["skip_reason"] = ""

    open_statuses = {"open", "triaged", "in_progress", "reopened", "accepted_risk"}
    resolved_statuses = {"resolved", "verified_resolved", "false_positive"}
    open_findings = [finding for finding in findings if str(finding.status or "").lower() in open_statuses]
    resolved_findings = [finding for finding in findings if str(finding.status or "").lower() in resolved_statuses]
    return {
        "reference": NFIR_REPORT_REFERENCE,
        "boundary": NFIR_REPORT_BOUNDARY,
        "authorization": {
            "roe_ref": engagement.roe_ref if engagement is not None and engagement.roe_ref else None,
            "confirmed_at": engagement.authorization_confirmed_at if engagement is not None else None,
            "confirmed_by": engagement.authorization_confirmed_by if engagement is not None else None,
            "recorded": authorization_recorded,
            "warning": "" if authorization_recorded else NFIR_AUTHORIZATION_WARNING,
        },
        "phases": [phase_records[phase["key"]] for phase in NFIR_PHASES],
        "open_findings": [
            {
                "finding": finding,
                "age_days": _finding_age_days(finding, now),
                "retest_status": _finding_retest_status(finding),
            }
            for finding in open_findings
        ],
        "resolved_findings": [
            {
                "finding": finding,
                "age_days": _finding_age_days(finding, now),
                "retest_status": _finding_retest_status(finding),
            }
            for finding in resolved_findings
        ],
    }


def _render_nfir_phase_task_markdown(task: Task) -> str:
    return f"- Task: {task.tool} on {task_targets_display(task)} ({task.status})"


def _render_nfir_phase_finding_markdown(finding: Finding) -> str:
    return (
        f"- Finding: {finding.title} | Severity: {finding.severity} | "
        f"Status: {finding.status} | CVSS: {_cvss_display(finding)} | Evidence: {finding.evidence_ref}"
    )


def _render_nfir_markdown(run: Run, context: dict[str, object]) -> str:
    nfir = nfir_report_context(run, context)
    authorization = nfir["authorization"]
    assert isinstance(authorization, dict)
    lines = [
        f"# AegisPT NFIR Evidence Mapping: {run.id}",
        "",
        "## NFIR Boundary",
        "",
        f"- Reference: {nfir['reference']}",
        f"- Disclaimer: {nfir['boundary']}",
        "- Evidence Source: stored AegisPT runs, tasks, findings, artifacts, scope, authorization, and remediation state.",
        "- Mapping Layer: additive report-time phase mapping; Prompt 1 methodology definitions remain unchanged.",
        "",
        "## Authorization",
        "",
        f"- ROE Reference: {authorization.get('roe_ref') or 'Not recorded'}",
        f"- Authorization Confirmed At: {authorization.get('confirmed_at').isoformat() if authorization.get('confirmed_at') else 'Not recorded'}",
        f"- Authorization Confirmed By: {authorization.get('confirmed_by') or 'Not recorded'}",
    ]
    if authorization.get("warning"):
        lines.append(f"- Warning: {authorization['warning']}")
    lines.extend(
        [
            "",
            "## Run Context",
            "",
            f"- Engagement: {context['engagement_name']}",
            f"- Client: {context['client_name']}",
            f"- Run Profile: {context['profile_name']}",
            f"- Run Status: {run.status}",
            f"- Requested By: {run.requested_by}",
            f"- Created At: {run.created_at.isoformat()}",
            "",
            *_render_configuration_markdown(context),
            "## NFIR 7-Phase Visibility",
            "",
            "| NFIR Phase | Status | Tasks | Findings | Reason / Basis |",
            "| --- | --- | ---: | ---: | --- |",
        ]
    )
    for phase in nfir["phases"]:
        assert isinstance(phase, dict)
        lines.append(
            f"| {phase['title']} | {phase['status']} | {len(phase['tasks'])} | {len(phase['findings'])} | {phase['skip_reason'] or phase['basis']} |"
        )
    for phase in nfir["phases"]:
        assert isinstance(phase, dict)
        lines.extend(["", f"### {phase['title']}", "", f"- Status: {phase['status']}", f"- Basis: {phase['basis']}"])
        if phase["skip_reason"]:
            lines.append(f"- Skipped Reason: {phase['skip_reason']}")
        for task in phase["tasks"]:
            assert isinstance(task, Task)
            lines.append(_render_nfir_phase_task_markdown(task))
        for finding in phase["findings"]:
            assert isinstance(finding, Finding)
            lines.append(_render_nfir_phase_finding_markdown(finding))
    lines.extend(["", "## Re-Audit Tracking", "", "### Open Findings", ""])
    if nfir["open_findings"]:
        lines.extend(["| Finding | Status | Severity | CVSS | Age | Retest Status |", "| --- | --- | --- | --- | ---: | --- |"])
        for item in nfir["open_findings"]:
            finding = item["finding"]
            assert isinstance(finding, Finding)
            lines.append(
                f"| {finding.title} | {finding.status} | {finding.severity} | {_cvss_display(finding)} | {item['age_days']} days | {item['retest_status']} |"
            )
    else:
        lines.append("- No open findings are recorded for this run.")
    lines.extend(["", "### Verified / Resolved Findings", ""])
    if nfir["resolved_findings"]:
        lines.extend(["| Finding | Status | Severity | CVSS | Age | Retest Status |", "| --- | --- | --- | --- | ---: | --- |"])
        for item in nfir["resolved_findings"]:
            finding = item["finding"]
            assert isinstance(finding, Finding)
            lines.append(
                f"| {finding.title} | {finding.status} | {finding.severity} | {_cvss_display(finding)} | {item['age_days']} days | {item['retest_status']} |"
            )
    else:
        lines.append("- No verified-resolved findings are recorded for this run.")
    lines.extend(
        [
            "",
            "## Methodology References",
            "",
            "- PTES",
            f"- OWASP WSTG {WSTG_STABLE_VERSION}",
            "- NIST SP 800-115",
            f"- {NFIR_REPORT_REFERENCE}",
            "",
        ]
    )
    return "\n".join(lines).rstrip() + "\n"


def _render_nfir_finding_table_html(items: list[dict[str, object]], *, empty_label: str) -> str:
    if not items:
        return f"<p>{escape(empty_label)}</p>"
    rows = []
    for item in items:
        finding = item["finding"]
        assert isinstance(finding, Finding)
        rows.append(
            "<tr>"
            f"<td>{escape(finding.title)}</td>"
            f"<td>{escape(finding.status)}</td>"
            f"<td>{escape(finding.severity)}</td>"
            f"<td>{escape(_cvss_display(finding))}</td>"
            f"<td>{escape(str(item['age_days']))} days</td>"
            f"<td>{escape(str(item['retest_status']))}</td>"
            "</tr>"
        )
    return (
        "<table><thead><tr><th>Finding</th><th>Status</th><th>Severity</th><th>CVSS</th><th>Age</th><th>Retest Status</th></tr></thead>"
        f"<tbody>{''.join(rows)}</tbody></table>"
    )


def _render_nfir_html(run: Run, context: dict[str, object]) -> str:
    nfir = nfir_report_context(run, context)
    authorization = nfir["authorization"]
    assert isinstance(authorization, dict)
    phase_rows = []
    phase_sections = []
    for phase in nfir["phases"]:
        assert isinstance(phase, dict)
        phase_rows.append(
            "<tr>"
            f"<td>{escape(str(phase['title']))}</td>"
            f"<td>{escape(str(phase['status']))}</td>"
            f"<td>{escape(str(len(phase['tasks'])))}</td>"
            f"<td>{escape(str(len(phase['findings'])))}</td>"
            f"<td>{escape(str(phase['skip_reason'] or phase['basis']))}</td>"
            "</tr>"
        )
        task_items = "".join(
            f"<li>{escape(task.tool)} on {escape(task_targets_display(task))} ({escape(task.status)})</li>"
            for task in phase["tasks"]
            if isinstance(task, Task)
        )
        finding_items = "".join(
            f"<li>{escape(finding.title)} - {escape(finding.severity)} - {escape(finding.status)} - CVSS {escape(_cvss_display(finding))}</li>"
            for finding in phase["findings"]
            if isinstance(finding, Finding)
        )
        phase_sections.append(
            "<section class='panel'>"
            f"<h3>{escape(str(phase['title']))}</h3>"
            f"<p><strong>Status:</strong> {escape(str(phase['status']))}</p>"
            f"<p><strong>Basis:</strong> {escape(str(phase['basis']))}</p>"
            + (f"<p><strong>Skipped Reason:</strong> {escape(str(phase['skip_reason']))}</p>" if phase["skip_reason"] else "")
            + f"<ul class='meta-list'>{task_items or '<li>No tasks mapped.</li>'}</ul>"
            + f"<ul class='meta-list'>{finding_items or '<li>No findings mapped.</li>'}</ul>"
            "</section>"
        )
    confirmed_at = authorization.get("confirmed_at")
    warning = (
        f"<p><strong>Warning:</strong> {escape(str(authorization['warning']))}</p>"
        if authorization.get("warning")
        else ""
    )
    return f"""
    <section class="panel">
      <h2>NFIR Boundary</h2>
      <ul class="meta-list">
        <li><strong>Reference:</strong> {escape(str(nfir['reference']))}</li>
        <li><strong>Disclaimer:</strong> {escape(str(nfir['boundary']))}</li>
        <li><strong>Evidence Source:</strong> stored AegisPT runs, tasks, findings, artifacts, scope, authorization, and remediation state.</li>
        <li><strong>Mapping Layer:</strong> additive report-time phase mapping; Prompt 1 methodology definitions remain unchanged.</li>
      </ul>
    </section>
    <section class="panel">
      <h2>Authorization</h2>
      <p><strong>ROE Reference:</strong> {escape(str(authorization.get('roe_ref') or 'Not recorded'))}</p>
      <p><strong>Authorization Confirmed At:</strong> {escape(confirmed_at.isoformat() if confirmed_at else 'Not recorded')}</p>
      <p><strong>Authorization Confirmed By:</strong> {escape(str(authorization.get('confirmed_by') or 'Not recorded'))}</p>
      {warning}
    </section>
    <section class="panel">
      <h2>NFIR 7-Phase Visibility</h2>
      <table>
        <thead><tr><th>NFIR Phase</th><th>Status</th><th>Tasks</th><th>Findings</th><th>Reason / Basis</th></tr></thead>
        <tbody>{''.join(phase_rows)}</tbody>
      </table>
    </section>
    {''.join(phase_sections)}
    <section class="panel">
      <h2>Re-Audit Tracking</h2>
      <h3>Open Findings</h3>
      {_render_nfir_finding_table_html(nfir['open_findings'], empty_label='No open findings are recorded for this run.')}
      <h3>Verified / Resolved Findings</h3>
      {_render_nfir_finding_table_html(nfir['resolved_findings'], empty_label='No verified-resolved findings are recorded for this run.')}
    </section>
    <section class="panel">
      <h2>Methodology References</h2>
      <ul class="meta-list">
        <li>PTES</li>
        <li>OWASP WSTG {escape(WSTG_STABLE_VERSION)}</li>
        <li>NIST SP 800-115</li>
        <li>{escape(NFIR_REPORT_REFERENCE)}</li>
      </ul>
    </section>
    """


def _render_evidence_first_attack_story_markdown(
    run: Run,
    context: dict[str, object],
) -> list[str]:
    story = evidence_first_attack_story_context(run, context)
    lines = [
        "## Evidence-First Attack Story",
        "",
        f"- Builder Version: {story['builder_version']}",
        "- Boundary: every narrative claim below must carry a source ledger entry.",
        "- Unsupported Claims: none" if not story["unsupported_claims"] else "- Unsupported Claims: present",
        "",
        "### Narrative Claims",
        "",
    ]
    claims = [claim for claim in story["claims"] if isinstance(claim, dict)]
    if claims:
        for claim in claims:
            sources = _format_source_records_markdown(claim.get("source_ids"))
            lines.extend(
                [
                    f"- Claim `{claim['claim_id']}`: {claim['text']}",
                    f"  - Sources: {sources}",
                ]
            )
    else:
        lines.append("- No narrative claims were generated because no allowed source IDs were available.")
    lines.extend(["", "### Source Ledger", ""])
    ledger = [row for row in story["source_ledger"] if isinstance(row, dict)]
    if ledger:
        lines.extend(["| Claim ID | Source Type | Source ID |", "| --- | --- | --- |"])
        for row in ledger:
            lines.append(f"| {row['claim_id']} | {row['source_type']} | {row['source_id']} |")
    else:
        lines.append("- No source ledger entries are available.")
    gaps = [gap for gap in story["gaps"] if isinstance(gap, dict)]
    if gaps:
        lines.extend(["", "### Evidence Gaps", ""])
        for gap in gaps:
            sources = _format_source_records_markdown(gap.get("source_ids"))
            lines.append(f"- Gap `{gap['gap_id']}`: {gap['text']} Sources: {sources}")
    lines.append("")
    return lines


def _render_evidence_gap_report_markdown(context: dict[str, object]) -> list[str]:
    gap_report = build_evidence_gap_report_from_context(context)
    sections = gap_report["sections"]
    lines = [
        "## Evidence Gap Report",
        "",
        f"- Report Version: {gap_report['report_version']}",
        f"- Confirmed Claims: {gap_report['summary']['confirmed']}",
        f"- Suspected Claims: {gap_report['summary']['suspected']}",
        f"- Untested Claims: {gap_report['summary']['untested']}",
        f"- Contradicted Claims: {gap_report['summary']['contradicted']}",
        f"- Unsupported Claims Excluded From Customer Prose: {gap_report['summary']['unsupported_excluded_count']}",
        "",
    ]
    for section_key, title in (
        ("confirmed", "Confirmed"),
        ("suspected", "Suspected"),
        ("untested", "Untested"),
        ("contradicted", "Contradicted"),
    ):
        claims = [claim for claim in sections[section_key] if isinstance(claim, dict)]
        lines.extend([f"### {title}", ""])
        if not claims:
            lines.extend(["- None recorded.", ""])
            continue
        for claim in claims:
            refs = claim.get("evidence_refs") if isinstance(claim.get("evidence_refs"), list) else []
            allowed = "yes" if claim.get("customer_report_allowed") else "no"
            lines.extend(
                [
                    f"- Claim: {claim.get('text')}",
                    f"  - Evidence Refs: {', '.join(str(ref) for ref in refs) if refs else 'none'}",
                    f"  - Customer Report Prose Allowed: {allowed}",
                ]
            )
            if claim.get("exclusion_reason"):
                lines.append(f"  - Exclusion Reason: {claim['exclusion_reason']}")
        lines.append("")
    unsupported = [
        claim
        for claim in gap_report["unsupported_claims_excluded_from_customer_report"]
        if isinstance(claim, dict)
    ]
    lines.extend(["### Unsupported Claims Excluded", ""])
    if not unsupported:
        lines.extend(["- None.", ""])
    else:
        for claim in unsupported:
            lines.append(f"- {claim.get('claim_id')}: {claim.get('exclusion_reason')}")
        lines.append("")
    return lines


def _render_evidence_first_attack_story_html(run: Run, context: dict[str, object]) -> str:
    story = evidence_first_attack_story_context(run, context)
    claim_items = "".join(
        "<li>"
        f"<strong>Claim <code>{escape(str(claim.get('claim_id')))}</code>:</strong> "
        f"{escape(str(claim.get('text')))}"
        f"<br><span>Sources: {escape(_format_source_records_markdown(claim.get('source_ids')))}</span>"
        "</li>"
        for claim in story["claims"]
        if isinstance(claim, dict)
    ) or "<li>No narrative claims were generated because no allowed source IDs were available.</li>"
    ledger_rows = "".join(
        "<tr>"
        f"<td>{escape(str(row.get('claim_id')))}</td>"
        f"<td>{escape(str(row.get('source_type')))}</td>"
        f"<td>{escape(str(row.get('source_id')))}</td>"
        "</tr>"
        for row in story["source_ledger"]
        if isinstance(row, dict)
    ) or "<tr><td colspan='3'>No source ledger entries are available.</td></tr>"
    gap_items = "".join(
        "<li>"
        f"<strong>Gap <code>{escape(str(gap.get('gap_id')))}</code>:</strong> "
        f"{escape(str(gap.get('text')))}"
        f"<br><span>Sources: {escape(_format_source_records_markdown(gap.get('source_ids')))}</span>"
        "</li>"
        for gap in story["gaps"]
        if isinstance(gap, dict)
    )
    gaps_html = f"<h3>Evidence Gaps</h3><ul class='meta-list'>{gap_items}</ul>" if gap_items else ""
    return f"""
      <h3>Evidence-First Attack Story</h3>
      <p><strong>Builder Version:</strong> {escape(str(story['builder_version']))}</p>
      <p>Every narrative claim below carries a source ledger entry. Unsupported claims: none.</p>
      <h4>Narrative Claims</h4>
      <ul class="meta-list">{claim_items}</ul>
      <h4>Source Ledger</h4>
      <table>
        <thead><tr><th>Claim ID</th><th>Source Type</th><th>Source ID</th></tr></thead>
        <tbody>{ledger_rows}</tbody>
      </table>
      {gaps_html}
    """


def _format_source_records_markdown(value: object) -> str:
    records = []
    for source in list(value or []):
        if not isinstance(source, dict):
            continue
        source_type = str(source.get("source_type") or "").strip()
        source_id = str(source.get("source_id") or "").strip()
        if source_type and source_id:
            records.append(f"{source_type}:{source_id}")
    return ", ".join(records) or "none"


def _render_executive_markdown(run: Run, context: dict[str, object]) -> str:
    findings = context["findings"]
    assert isinstance(findings, list)
    confirmed_findings = [finding for finding in findings if isinstance(finding, Finding)]
    score = _risk_score(confirmed_findings)
    cluster_rows = _management_cluster_rows(confirmed_findings)
    decision_facts = _management_decision_facts(run, context)
    story_context = _management_assessment_story_context(run, context)
    high_crit = [
        finding
        for finding in confirmed_findings
        if str(finding.severity or "").lower() in {"critical", "high"}
    ]
    coverage = context.get("test_coverage", {})
    coverage_summary = (
        [
            f"- Test activity reviewed: {coverage.get('executed_task_count', 0)} of {coverage.get('total_task_count', 0)} checks",
            "- Coverage boundary: This summary reflects recorded evidence for the tested scope only.",
        ]
        if isinstance(coverage, dict)
        else ["- Coverage data is unavailable for this run."]
    )
    risk_highlights = [
        f"- {_humanize_key(str(row['severity']))}: {row['title']} — {row['impact']}"
        for row in cluster_rows[:5]
    ] or ["- No confirmed findings recorded."]
    next_steps = [
        f"- {row['title']}: {row['action']}"
        for row in cluster_rows[:5]
    ] or [
        "- Keep planned monitoring in place and retest after material application or infrastructure changes.",
    ]
    return "\n".join(
        [
            "## Executive Narrative",
            "",
            _executive_narrative(run, context),
            "",
            *_management_risk_picture_markdown_lines(context),
            *_management_decision_markdown_lines(decision_facts),
            *_management_story_markdown_lines(story_context),
            *_management_attacker_markdown_lines(context),
            *_management_remediation_markdown_lines(context),
            *_management_test_origin_markdown_lines(run, context),
            "## Methodology Used",
            "",
            *[f"- {line}" for line in decision_facts["standards"]],
            "",
            *_management_standards_markdown_lines(),
            "## Evidence Basis",
            "",
            "- The summary is based on confirmed AegisPT finding records for the assessed system.",
            "- Technical replay artifacts and source ledgers remain available in the technical and evidence reports.",
            "",
            "## Exposure Score",
            "",
            f"Risk Level: {_risk_level(score)} ({score}/10) {_risk_bar(score)}",
            "",
            "## Remediation Priority Table",
            "",
            *_render_remediation_priority_table_markdown(confirmed_findings, management=True),
            "",
            "## Mission Snapshot",
            "",
            f"- Customer: {_management_safe_text(context.get('client_name'), fallback='the customer')}",
            f"- Assessed System: {_management_scope_label(context)}",
            f"- Assessment State: {_humanize_key(str(run.status))}",
            f"- Evidence-backed Findings: {len(confirmed_findings)}",
            f"- High/Critical Items: {len(high_crit)}",
            "",
            "### Findings by Severity",
            "",
            *_format_count_map_markdown(context["findings_by_severity"]),
            "",
            "### Findings by Status",
            "",
            *_format_count_map_markdown(context["findings_by_status"]),
            "",
            "## Tested / Not Tested",
            "",
            *coverage_summary,
            "",
            "## Risk Highlights",
            "",
            *risk_highlights,
            "",
            "## Recommended Next Steps",
            "",
            *next_steps,
            "- Use the technical report only when analysts need evidence references, replay artifacts, or reproduction detail.",
            "",
        ]
    ).rstrip() + "\n"


def _render_evidence_markdown(run: Run, context: dict[str, object]) -> str:
    findings = context["findings"]
    tasks = context["tasks"]
    lines = [
        f"# AegisPT Evidence Appendix: {run.id}",
        "",
        *_render_configuration_markdown(context),
        "## Discovery Results",
        "",
        *_inventory_summary_lines(context),
        "## Methodology References",
        "",
        *[f"- {reference}" for reference in report_methodology_references(run)],
        "",
        "## Findings Evidence Map",
        "",
    ]
    if findings:
        for finding in findings:
            lines.extend(
                [
                    f"### {finding.title}",
                    "",
                    f"- Evidence Ref: {finding.evidence_ref}",
                    f"- Severity: {finding.severity}",
                    f"- Status: {finding.status}",
                    *finding_methodology_lines(finding),
                    "",
                ]
            )
    else:
        lines.extend(["- No findings recorded.", ""])

    lines.extend(["## Task Evidence", ""])
    if tasks:
        for task in tasks:
            lines.extend(
                [
                    f"### Task {task.id}",
                    "",
                    f"- Tool: {task.tool}",
                    f"- Target: {task_targets_display(task)}",
                    f"- Status: {task.status}",
                ]
            )
            for execution in task.executions:
                lines.append(
                    f"- Execution {execution.id}: exit_code={execution.exit_code}, tool_version={execution.tool_version}"
                )
                for artifact in sort_artifacts(list(execution.artifacts)):
                    lines.append(
                        f"  artifact: {artifact.metadata_json.get('name', artifact.id)} download={artifact_download_path(artifact.id)}"
                    )
            lines.append("")
    else:
        lines.extend(["- No task evidence recorded.", ""])

    return "\n".join(lines).rstrip() + "\n"


def _render_retest_markdown(run: Run, context: dict[str, object]) -> str:
    findings = context["findings"]
    confirmed_findings = [finding for finding in findings if isinstance(finding, Finding)]
    lines = [
        f"# AegisPT Retest / Verification Report: {run.id}",
        "",
        "## Verification Summary",
        "",
        f"- Run Status: {run.status}",
        "",
        "### Verification Status Counts",
        "",
        *_format_count_map_markdown(context["findings_by_status"]),
        f"- Resolved Findings: {sum(1 for finding in findings if finding.status == 'resolved')}",
        f"- Still Open: {sum(1 for finding in findings if finding.status in {'open', 'triaged', 'in_progress', 'reopened'})}",
        "",
        *_render_proof_of_resolution_markdown(run, context),
        *_render_configuration_markdown(context),
        "## Discovery Results",
        "",
        *_inventory_summary_lines(context),
        "## Findings Verification State",
        "",
    ]
    lines.extend(_render_deduplicated_findings_markdown(confirmed_findings))
    lines.extend(
        [
            "## Retest Guidance",
            "",
            "- Re-run validated checks after remediation and attach new evidence under the same engagement dossier.",
            "- Update finding status only after replay confirms the fix or the customer accepts residual risk.",
            "",
        ]
    )
    return "\n".join(lines).rstrip() + "\n"


def _render_run_attack_narrative_markdown(run: Run, context: dict[str, object]) -> str:
    narrative = run_attack_narrative_context(run, context)
    attack_summary = narrative["attack_path_summary"]
    chain_summary = narrative["chain_detection_summary"]
    lines = [
        f"# AegisPT Run Attack Narrative: {run.id}",
        "",
        "## Advisory Boundary",
        "",
        "- Mode: AI-assisted / advisory",
        "- Operator Review Required: yes",
        "- Operator Editable: yes",
        "- Canonical Report Changed: no",
        f"- Narrative Status: {narrative['status']}",
        f"- Available: {'yes' if narrative['available'] else 'no'}",
        f"- Boundary: {RUN_ATTACK_NARRATIVE_BOUNDARY}",
        "",
        "## Source Traceability",
        "",
        f"- Source Data Categories: {', '.join(narrative['source_data_categories'])}",
        f"- Source Evidence Refs: {', '.join(narrative['source_evidence_refs']) or 'No linked finding evidence refs recorded'}",
        f"- Findings Reviewed: {narrative['findings_reviewed']}",
        f"- High-Priority Findings: {narrative['high_priority_finding_count']}",
        f"- Attack-Path Model: {attack_summary.get('evaluation_model') or 'not available'}",
        f"- Candidate Paths: {attack_summary.get('candidate_path_count', 0)}",
        f"- Choke Points: {attack_summary.get('choke_point_count', 0)}",
        f"- Stored Chain Detections: {chain_summary.get('chain_count', 0)}",
        "",
    ]

    for section in narrative["sections"]:
        assert isinstance(section, dict)
        lines.extend(
            [
                f"## {section['title']}",
                "",
                str(section["body"]),
                "",
            ]
        )

    candidate_paths = narrative.get("candidate_paths", [])
    if isinstance(candidate_paths, list) and candidate_paths:
        lines.extend(["## Candidate Path Evidence", ""])
        for path in candidate_paths:
            if not isinstance(path, dict):
                continue
            lines.extend(
                [
                    f"- {path.get('severity', 'unknown')} {path.get('finding_title', 'Untitled finding')}: {path.get('path', 'No path labels recorded.')}",
                    f"  - Confidence: {path.get('confidence', 0.0)}",
                    f"  - Target: {path.get('target_id', 'not recorded')}",
                    f"  - Evidence Refs: {', '.join(path.get('evidence_refs', [])) or 'none recorded'}",
                ]
            )
        lines.append("")

    chains = chain_summary.get("chains", [])
    if isinstance(chains, list) and chains:
        lines.extend(["## Stored Chain Detections", ""])
        for chain in chains:
            if not isinstance(chain, dict):
                continue
            lines.extend(
                [
                    f"- {chain.get('title', 'Untitled chain')} ({chain.get('status', 'unknown')}, confidence {chain.get('confidence_score', 0.0)})",
                    f"  - Impact: {chain.get('combined_impact', 'No combined impact recorded.')}",
                    f"  - Evidence Refs: {', '.join(chain.get('evidence_refs', [])) or 'none recorded'}",
                ]
            )
        lines.append("")

    limitations = narrative.get("limitations", [])
    if isinstance(limitations, list) and limitations:
        lines.extend(["## Limitations", ""])
        lines.extend(f"- {item}" for item in limitations)
        lines.append("")

    return "\n".join(lines).rstrip() + "\n"


def _render_run_attack_narrative_html(run: Run, context: dict[str, object]) -> str:
    narrative = run_attack_narrative_context(run, context)
    attack_summary = narrative["attack_path_summary"]
    chain_summary = narrative["chain_detection_summary"]
    sections_html = "".join(
        "<section class='panel'>"
        f"<h2>{escape(str(section.get('title', 'Narrative Section')))}</h2>"
        f"<p>{escape(str(section.get('body', 'No narrative body recorded.')))}</p>"
        f"<p><strong>Review Required:</strong> {escape('yes' if section.get('review_required') else 'no')}</p>"
        "</section>"
        for section in narrative["sections"]
        if isinstance(section, dict)
    )
    path_items = "".join(
        "<li>"
        f"<strong>{escape(str(path.get('severity', 'unknown')).upper())} {escape(str(path.get('finding_title', 'Untitled finding')))}</strong>: "
        f"{escape(str(path.get('path', 'No path labels recorded.')))} "
        f"(confidence {escape(str(path.get('confidence', 0.0)))})"
        f"<br><span>Evidence: {escape(', '.join(path.get('evidence_refs', [])) or 'none recorded')}</span>"
        "</li>"
        for path in narrative.get("candidate_paths", [])
        if isinstance(path, dict)
    )
    chain_items = "".join(
        "<li>"
        f"<strong>{escape(str(chain.get('title', 'Untitled chain')))}</strong> "
        f"({escape(str(chain.get('status', 'unknown')))}, confidence {escape(str(chain.get('confidence_score', 0.0)))})"
        f"<br><span>{escape(str(chain.get('combined_impact', 'No combined impact recorded.')))}</span>"
        f"<br><span>Evidence: {escape(', '.join(chain.get('evidence_refs', [])) or 'none recorded')}</span>"
        "</li>"
        for chain in chain_summary.get("chains", [])
        if isinstance(chain, dict)
    )
    limitations_html = "".join(
        f"<li>{escape(str(item))}</li>"
        for item in narrative.get("limitations", [])
        if str(item).strip()
    )

    return f"""
    <section class="panel">
      <h2>Run Attack Narrative Boundary</h2>
      <p><strong>Mode:</strong> AI-assisted / advisory</p>
      <p><strong>Status:</strong> {escape(str(narrative['status']))}</p>
      <p><strong>Operator Review Required:</strong> yes</p>
      <p><strong>Canonical Report Changed:</strong> no</p>
      <p>{escape(RUN_ATTACK_NARRATIVE_BOUNDARY)}</p>
    </section>
    <section class="panel">
      <h2>Source Traceability</h2>
      <ul class="meta-list">
        <li><strong>Source Data Categories:</strong> {escape(', '.join(narrative['source_data_categories']))}</li>
        <li><strong>Source Evidence Refs:</strong> {escape(', '.join(narrative['source_evidence_refs']) or 'No linked finding evidence refs recorded')}</li>
        <li><strong>Findings Reviewed:</strong> {escape(str(narrative['findings_reviewed']))}</li>
        <li><strong>High-Priority Findings:</strong> {escape(str(narrative['high_priority_finding_count']))}</li>
        <li><strong>Candidate Paths:</strong> {escape(str(attack_summary.get('candidate_path_count', 0)))}</li>
        <li><strong>Choke Points:</strong> {escape(str(attack_summary.get('choke_point_count', 0)))}</li>
        <li><strong>Stored Chain Detections:</strong> {escape(str(chain_summary.get('chain_count', 0)))}</li>
      </ul>
    </section>
    {sections_html}
    <section class="panel">
      <h2>Candidate Path Evidence</h2>
      <ul class="meta-list">{path_items or '<li>No evidence-backed attack paths were derived for this run.</li>'}</ul>
    </section>
    <section class="panel">
      <h2>Stored Chain Detections</h2>
      <ul class="meta-list">{chain_items or '<li>No stored vulnerability-chain detections are attached to this run.</li>'}</ul>
    </section>
    <section class="panel">
      <h2>Limitations</h2>
      <ul class="meta-list">{limitations_html or '<li>No additional limitations recorded.</li>'}</ul>
    </section>
    """


def report_draft_summary_for_catalog(run: Run, variant: str) -> dict[str, object]:
    variant_contract = _report_draft_variant_contract(variant)
    return {
        "supported": bool(variant_contract.get("llm_allowed")),
        "status": "operator_review_required" if variant_contract.get("llm_allowed") else "deterministic_export_only",
        "review_required": True,
        "canonical_report_unchanged": True,
        "supported_sections": list(variant_contract.get("allowed_sections", DEFAULT_REPORT_DRAFT_SECTIONS)),
        "endpoint": f"/api/v1/runs/{run.id}/report-draft",
        "boundary": REPORT_DRAFT_BOUNDARY,
        "variant": variant,
        "variant_contract": variant_contract,
    }


def build_report_draft(
    run: Run,
    *,
    variant: str = "technical",
    sections: list[str] | None = None,
    settings: Settings,
    session: Session | None = None,
) -> RunReportDraftRead:
    context = report_context_for_run(run, session=session)
    provider = effective_ai_provider_name(settings, settings.ai_report_drafting_provider)
    selected_sections = _normalize_report_draft_sections(sections, variant=variant)
    source_categories, source_evidence_refs = _report_draft_sources(context)
    structured_payload = _report_draft_backend_payload(
        run=run,
        context=context,
        variant=variant,
        selected_sections=selected_sections,
        source_categories=source_categories,
        source_evidence_refs=source_evidence_refs,
    )
    source_categories = list(structured_payload.get("source_data_categories", source_categories))
    source_evidence_refs = list(structured_payload.get("source_evidence_refs", source_evidence_refs))
    contract_fields = _report_draft_contract_fields(structured_payload)
    generated_at = datetime.now(tz=UTC)

    if not structured_payload.get("variant_contract", {}).get("llm_allowed", True):
        return RunReportDraftRead(
            source_run_id=run.id,
            variant=variant,
            status="not_applicable",
            available=False,
            provider=provider or "disabled",
            generated_at=generated_at,
            source_data_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
            boundary=REPORT_DRAFT_BOUNDARY,
            failure_reason=(
                "Raw evidence/proof exports are deterministic and are not sent to an LLM draft provider."
            ),
            **contract_fields,
        )

    if not settings.ai_report_drafting_enabled or provider in {"", "disabled", "none", "off"}:
        return RunReportDraftRead(
            source_run_id=run.id,
            variant=variant,
            status="disabled",
            available=False,
            provider=provider or "disabled",
            generated_at=generated_at,
            source_data_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
            boundary=REPORT_DRAFT_BOUNDARY,
            failure_reason="AI report drafting is disabled; normal report exports remain unchanged.",
            **contract_fields,
        )

    if provider in {"fail", "failed", "failing", "failure", "error"}:
        return RunReportDraftRead(
            source_run_id=run.id,
            variant=variant,
            status="failed",
            available=False,
            provider=provider,
            generated_at=generated_at,
            source_data_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
            boundary=REPORT_DRAFT_BOUNDARY,
            failure_reason="Configured AI report drafting provider failed deterministically for operator review.",
            **contract_fields,
        )

    if provider == CHATGPT_OAUTH_PROVIDER:
        return _build_chatgpt_oauth_report_draft(
            run=run,
            variant=variant,
            selected_sections=selected_sections,
            settings=settings,
            session=session,
            context=context,
            structured_payload=structured_payload,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
            generated_at=generated_at,
        )

    if provider not in {"deterministic", "mock", "test"}:
        return RunReportDraftRead(
            source_run_id=run.id,
            variant=variant,
            status="failed",
            available=False,
            provider=provider,
            generated_at=generated_at,
            source_data_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
            boundary=REPORT_DRAFT_BOUNDARY,
            failure_reason=f"Unsupported AI report drafting provider: {provider}",
            **contract_fields,
        )

    draft_sections = [
        _build_report_draft_section(
            section_id=section_id,
            context=context,
            variant=variant,
            structured_payload=structured_payload,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
        )
        for section_id in selected_sections
    ]
    draft_markdown = _render_report_draft_markdown(
        run=run,
        variant=variant,
        provider=provider,
        sections=draft_sections,
        source_categories=source_categories,
        source_evidence_refs=source_evidence_refs,
    )

    return RunReportDraftRead(
        source_run_id=run.id,
        variant=variant,
        status="draft_ready",
        available=True,
        provider=provider,
        generated_at=generated_at,
        sections=draft_sections,
        draft_markdown=draft_markdown,
        source_data_categories=source_categories,
        source_evidence_refs=source_evidence_refs,
        boundary=REPORT_DRAFT_BOUNDARY,
        **contract_fields,
    )


def _build_chatgpt_oauth_report_draft(
    *,
    run: Run,
    variant: str,
    selected_sections: list[str],
    settings: Settings,
    session: Session | None,
    context: dict[str, object],
    structured_payload: dict[str, object],
    source_categories: list[str],
    source_evidence_refs: list[str],
    generated_at: datetime,
) -> RunReportDraftRead:
    contract_fields = _report_draft_contract_fields(structured_payload)
    if session is None:
        return RunReportDraftRead(
            source_run_id=run.id,
            variant=variant,
            status="failed",
            available=False,
            provider=CHATGPT_OAUTH_PROVIDER,
            generated_at=generated_at,
            source_data_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
            boundary=REPORT_DRAFT_BOUNDARY,
            failure_reason="ChatGPT OAuth report drafting requires a database session.",
            **contract_fields,
        )

    try:
        result_payload = send_chatgpt_backend_streaming_json_request(
            session=session,
            engagement_id=run.engagement_id,
            settings=settings,
            model=str(settings.chatgpt_oauth_model or "gpt-5.4"),
            instructions=(
                "Return a strict JSON object with keys status, draft_markdown, and sections. "
                "Each section must include section_id, title, and draft. The draft is review-only wording, "
                "not canonical fact generation. Use only tested_scope, supported_findings, source_evidence_refs, "
                "not_tested, not_verified, methodology, management_decision, and management_story from the JSON payload. "
                "For management variants, management_decision is the canonical verdict/decision/action source and "
                "management_story is the canonical attack-map, attacker-path, remediation-track, standard-badge, and technique source. Do not turn "
                "not_tested or not_verified items into positive claims. Follow variant_contract audience and "
                "constraints. Raw proof and evidence exports remain deterministic and outside the LLM draft."
            ),
            input_items=[
                {
                    "type": "message",
                    "role": "user",
                    "content": [
                        {
                            "type": "input_text",
                            "text": json.dumps(structured_payload, sort_keys=True),
                        }
                    ],
                }
            ],
        )
    except Exception as exc:
        return RunReportDraftRead(
            source_run_id=run.id,
            variant=variant,
            status="failed",
            available=False,
            provider=CHATGPT_OAUTH_PROVIDER,
            generated_at=generated_at,
            source_data_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
            boundary=REPORT_DRAFT_BOUNDARY,
            failure_reason=f"ChatGPT OAuth report drafting failed: {exc}",
            **contract_fields,
        )
    draft_sections = _normalize_chatgpt_report_draft_sections(
        raw_sections=result_payload.get("sections"),
        selected_sections=selected_sections,
        variant=variant,
        source_categories=source_categories,
        source_evidence_refs=source_evidence_refs,
        structured_payload=structured_payload,
    )
    draft_markdown = str(result_payload.get("draft_markdown") or "").strip()
    if not draft_markdown:
        draft_markdown = _render_report_draft_markdown(
            run=run,
            variant=variant,
            provider=CHATGPT_OAUTH_PROVIDER,
            sections=draft_sections,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
        )

    return RunReportDraftRead(
        source_run_id=run.id,
        variant=variant,
        status=str(result_payload.get("status") or "draft_ready"),
        available=True,
        provider=CHATGPT_OAUTH_PROVIDER,
        generated_at=generated_at,
        sections=draft_sections,
        draft_markdown=draft_markdown,
        source_data_categories=source_categories,
        source_evidence_refs=source_evidence_refs,
        boundary=REPORT_DRAFT_BOUNDARY,
        **contract_fields,
    )


def _normalize_report_draft_sections(sections: list[str] | None, *, variant: str) -> list[str]:
    default_sections = _report_draft_default_sections_for_variant(variant)
    requested = sections or list(default_sections)
    normalized: list[str] = []
    for section in requested:
        key = str(section or "").strip().lower().replace("-", "_")
        if key in REPORT_DRAFT_SECTION_LABELS and key not in normalized:
            normalized.append(key)
    return normalized or list(default_sections)


def _normalize_chatgpt_report_draft_sections(
    *,
    raw_sections: object,
    selected_sections: list[str],
    variant: str,
    source_categories: list[str],
    source_evidence_refs: list[str],
    structured_payload: dict[str, object],
) -> list[dict[str, object]]:
    normalized: list[dict[str, object]] = []
    if isinstance(raw_sections, list):
        for item in raw_sections:
            if not isinstance(item, dict):
                continue
            section_id = str(item.get("section_id") or item.get("id") or "").strip().lower().replace("-", "_")
            if section_id not in REPORT_DRAFT_SECTION_LABELS:
                continue
            draft_text = str(item.get("draft") or item.get("markdown") or item.get("text") or "").strip()
            if not draft_text:
                continue
            normalized.append(
                {
                    "section_id": section_id,
                    "title": str(item.get("title") or REPORT_DRAFT_SECTION_LABELS[section_id]),
                    "variant": variant,
                    "draft": draft_text,
                    "source_data_categories": source_categories,
                    "source_evidence_refs": source_evidence_refs,
                    "review_required": True,
                }
            )
    if normalized:
        return normalized
    return [
        _build_report_draft_section(
            section_id=section_id,
            context={},
            variant=variant,
            structured_payload=structured_payload,
            source_categories=source_categories,
            source_evidence_refs=source_evidence_refs,
        )
        | {"draft": f"AI-assisted draft for {REPORT_DRAFT_SECTION_LABELS[section_id]}. Operator review is required before using this wording."}
        for section_id in selected_sections
    ]


def _report_draft_default_sections_for_variant(variant: str) -> tuple[str, ...]:
    raw_variant = str(variant or "technical").strip().lower()
    canonical_variant = normalize_report_variant(raw_variant)
    return tuple(
        REPORT_DRAFT_VARIANT_SECTIONS.get(raw_variant)
        or REPORT_DRAFT_VARIANT_SECTIONS.get(canonical_variant)
        or DEFAULT_REPORT_DRAFT_SECTIONS
    )


def _report_draft_variant_contract(variant: str) -> dict[str, object]:
    raw_variant = str(variant or "technical").strip().lower()
    canonical_variant = normalize_report_variant(raw_variant)
    allowed_sections = list(_report_draft_default_sections_for_variant(raw_variant))
    if raw_variant in REPORT_DRAFT_NON_LLM_VARIANTS:
        return {
            "variant": raw_variant,
            "canonical_variant": canonical_variant,
            "audience": "evidence_reviewer",
            "template": "deterministic_proof_export",
            "allowed_sections": allowed_sections,
            "llm_allowed": False,
            "raw_proof_export_non_llm": True,
            "constraints": [
                "Raw proof, evidence replay, and artifact exports remain deterministic.",
                "No LLM draft may generate or rewrite proof material.",
            ],
        }
    if raw_variant in REPORT_DRAFT_MANAGEMENT_VARIANTS or canonical_variant == "summary":
        return {
            "variant": raw_variant,
            "canonical_variant": canonical_variant,
            "audience": "management",
            "template": "plain_language_management_summary",
            "allowed_sections": allowed_sections,
            "llm_allowed": True,
            "raw_proof_export_non_llm": True,
            "constraints": [
                "Use plain language and avoid tool-only jargon.",
                "Summarize only tested scope and supported findings.",
                "Keep untested or unverified items as explicit caveats.",
            ],
        }
    if canonical_variant == "compliance":
        return {
            "variant": raw_variant,
            "canonical_variant": canonical_variant,
            "audience": "assurance_reviewer",
            "template": "control_mapping_annex",
            "allowed_sections": allowed_sections,
            "llm_allowed": True,
            "raw_proof_export_non_llm": True,
            "constraints": [
                "Map only evidence-backed findings to compliance language.",
                "Do not claim certification, attestation, or full framework coverage.",
            ],
        }
    if raw_variant == "retest" or canonical_variant == "retest":
        return {
            "variant": raw_variant,
            "canonical_variant": canonical_variant,
            "audience": "technical_retest_reviewer",
            "template": "verification_follow_up",
            "allowed_sections": allowed_sections,
            "llm_allowed": True,
            "raw_proof_export_non_llm": True,
            "constraints": [
                "Separate fixed, still open, and unverified items.",
                "Do not claim remediation unless the stored validation status supports it.",
            ],
        }
    return {
        "variant": raw_variant,
        "canonical_variant": canonical_variant,
        "audience": "technical",
        "template": "technical_evidence_narrative",
        "allowed_sections": allowed_sections,
        "llm_allowed": True,
        "raw_proof_export_non_llm": True,
        "constraints": [
            "Keep tool details, evidence refs, methodology tags, and remediation facts grounded.",
            "Use not_tested and not_verified as caveats, never as positive findings.",
        ],
    }


def _report_draft_contract_fields(payload: dict[str, object]) -> dict[str, object]:
    draft_contract = payload.get("draft_contract")
    variant_contract = payload.get("variant_contract")
    tested_scope = payload.get("tested_scope")
    management_decision = payload.get("management_decision")
    management_story = payload.get("management_story")
    supported_findings = payload.get("supported_findings")
    not_tested = payload.get("not_tested")
    not_verified = payload.get("not_verified")
    raw_proof_export_non_llm = (
        bool(draft_contract.get("raw_proof_export_non_llm", True)) if isinstance(draft_contract, dict) else True
    )
    return {
        "structured_payload": payload,
        "draft_contract": draft_contract if isinstance(draft_contract, dict) else {},
        "variant_contract": variant_contract if isinstance(variant_contract, dict) else {},
        "tested_scope": tested_scope if isinstance(tested_scope, dict) else {},
        "management_decision": management_decision if isinstance(management_decision, dict) else {},
        "management_story": management_story if isinstance(management_story, dict) else {},
        "supported_findings": [item for item in supported_findings if isinstance(item, dict)]
        if isinstance(supported_findings, list)
        else [],
        "not_tested": [item for item in not_tested if isinstance(item, dict)] if isinstance(not_tested, list) else [],
        "not_verified": [item for item in not_verified if isinstance(item, dict)] if isinstance(not_verified, list) else [],
        "raw_proof_export_non_llm": raw_proof_export_non_llm,
    }


def _safe_report_payload(value: object) -> dict[str, object]:
    return dict(value) if isinstance(value, dict) else {}


def _finding_report_payload(finding: Finding) -> dict[str, object]:
    return {
        "id": str(finding.id) if finding.id else None,
        "title": finding.title,
        "severity": finding.severity,
        "status": finding.status,
        "validation_status": finding.validation_status,
        "target_id": finding.target_id,
        "summary": finding.summary,
        "evidence_ref": finding.evidence_ref,
        "methodology_tags": list(finding.methodology_tags or []),
        "ptes_phase": finding.ptes_phase,
        "nist_phase": finding.nist_phase,
        "wstg_id": finding.wstg_id,
        "asvs_reference": finding.asvs_reference,
        "control_family": finding.control_family,
        "finding_origin": finding.finding_origin,
    }


def _task_report_payload(task: Task) -> dict[str, object]:
    return {
        "id": str(task.id) if task.id else None,
        "tool": task.tool,
        "status": task.status,
        "target": task_targets_display(task),
        "execution_count": len(task.executions),
        "artifact_count": sum(len(execution.artifacts) for execution in task.executions),
    }


def _approval_report_payload(approval: Approval) -> dict[str, object]:
    return {
        "id": str(approval.id) if approval.id else None,
        "step_id": approval.step_id,
        "decision": approval.decision,
        "approver_id": approval.approver_id,
        "created_at": approval.created_at.isoformat() if approval.created_at else None,
    }


def _report_draft_target_values(configuration: dict[str, object]) -> list[str]:
    targets = configuration.get("targets")
    values: list[str] = []
    if isinstance(targets, dict):
        for target_values in targets.values():
            if not isinstance(target_values, list):
                continue
            values.extend(str(value).strip() for value in target_values if str(value or "").strip())
    return sorted(set(values))


def _report_draft_tested_scope(context: dict[str, object]) -> dict[str, object]:
    configuration = _safe_report_payload(context.get("configuration"))
    tasks = [task for task in context.get("tasks", []) if isinstance(task, Task)]
    completed_tasks: list[dict[str, object]] = []
    tested_targets: set[str] = set()
    for task in tasks:
        status = str(task.status or "").strip().lower()
        if status not in REPORT_DRAFT_COMPLETED_TASK_STATUSES:
            continue
        task_payload = _task_report_payload(task)
        completed_tasks.append(task_payload)
        target = str(task_payload.get("target") or "").strip()
        if target:
            tested_targets.add(target)

    return {
        "profile_name": context.get("profile_name"),
        "engagement_name": context.get("engagement_name"),
        "client_name": context.get("client_name"),
        "authorized_targets": _report_draft_target_values(configuration),
        "tested_targets": sorted(tested_targets),
        "completed_task_count": len(completed_tasks),
        "completed_tasks": completed_tasks[:50],
        "scope_rule": "Only completed task targets are treated as tested. Authorized-but-unexecuted targets remain not_tested.",
    }


def _report_draft_not_tested_items(
    *,
    context: dict[str, object],
    tested_scope: dict[str, object],
) -> list[dict[str, object]]:
    tasks = [task for task in context.get("tasks", []) if isinstance(task, Task)]
    authorized_targets = {
        str(target).strip()
        for target in tested_scope.get("authorized_targets", [])
        if str(target or "").strip()
    }
    tested_targets = {
        str(target).strip()
        for target in tested_scope.get("tested_targets", [])
        if str(target or "").strip()
    }
    items: list[dict[str, object]] = []
    for target in sorted(authorized_targets - tested_targets):
        items.append(
            {
                "type": "authorized_target_without_completed_task",
                "target": target,
                "reason": "No completed task evidence is attached to this target in the report context.",
                "claim_rule": "May be described as authorized scope, not as tested coverage.",
            }
        )
    for task in tasks:
        status = str(task.status or "").strip().lower()
        if status in REPORT_DRAFT_COMPLETED_TASK_STATUSES:
            continue
        items.append(
            {
                "type": "task_not_completed",
                "tool": task.tool,
                "target": task_targets_display(task),
                "status": task.status,
                "claim_rule": "Incomplete, failed, queued, or running tasks cannot support positive report claims.",
            }
        )
    if not tested_targets:
        items.append(
            {
                "type": "no_completed_task_scope",
                "reason": "No completed task target is present in the report context.",
                "claim_rule": "The draft must not imply that the configured scope was fully tested.",
            }
        )
    return items[:100]


def _finding_not_verified_reason(finding: Finding) -> str | None:
    status = str(finding.status or "").strip().lower()
    validation_status = str(finding.validation_status or "").strip().lower()
    evidence_ref = str(finding.evidence_ref or "").strip()
    if status in REPORT_DRAFT_EXCLUDED_FINDING_STATUSES:
        return f"finding_status_{status}"
    if validation_status in REPORT_DRAFT_EXCLUDED_VALIDATION_STATUSES:
        return f"validation_status_{validation_status}"
    if not evidence_ref:
        return "missing_evidence_ref"
    return None


def _finding_supported_for_report_draft(finding: Finding) -> bool:
    return _finding_not_verified_reason(finding) is None


def _not_verified_finding_payload(finding: Finding, reason: str) -> dict[str, object]:
    payload = _finding_report_payload(finding)
    payload.pop("summary", None)
    payload["reason"] = reason
    payload["claim_rule"] = "Keep as a review caveat. Do not present this item as a supported report finding."
    return payload


def _report_draft_backend_payload(
    *,
    run: Run,
    context: dict[str, object],
    variant: str,
    selected_sections: list[str],
    source_categories: list[str],
    source_evidence_refs: list[str],
) -> dict[str, object]:
    variant_contract = _report_draft_variant_contract(variant)
    tested_scope = _report_draft_tested_scope(context)
    not_tested = _report_draft_not_tested_items(context=context, tested_scope=tested_scope)
    management_decision = (
        _management_decision_facts(run, context)
        if str(variant_contract.get("audience") or "") == "management"
        else {}
    )
    management_story = (
        _management_assessment_story_context(run, context)
        if str(variant_contract.get("audience") or "") == "management"
        else {}
    )
    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    supported_findings = [
        _finding_report_payload(finding)
        for finding in findings
        if _finding_supported_for_report_draft(finding)
    ]
    not_verified = [
        _not_verified_finding_payload(finding, reason)
        for finding in findings
        if (reason := _finding_not_verified_reason(finding)) is not None
    ]
    supported_evidence_refs = sorted(
        {
            str(finding.get("evidence_ref") or "").strip()
            for finding in supported_findings
            if str(finding.get("evidence_ref") or "").strip()
        }
    )
    filtered_categories = [
        category
        for category in source_categories
        if category
        not in {
            "run.findings",
            "run.tasks",
            "finding.evidence_ref",
        }
    ]
    if supported_findings:
        filtered_categories.append("run.findings")
    if tested_scope.get("completed_tasks"):
        filtered_categories.append("run.tasks")
    if supported_evidence_refs:
        filtered_categories.append("finding.evidence_ref")
    if not_tested:
        filtered_categories.append("report_draft.not_tested")
    if not_verified:
        filtered_categories.append("report_draft.not_verified")
    if management_decision:
        filtered_categories.append("report_draft.management_decision")
    if management_story:
        filtered_categories.append("report_draft.management_story")
    allowed_input_facts = [
        "tested_scope",
        "supported_findings",
        "source_evidence_refs",
        "not_tested",
        "not_verified",
        "methodology",
    ]
    if management_decision:
        allowed_input_facts.append("management_decision")
    if management_story:
        allowed_input_facts.append("management_story")
    return {
        "run": {
            "id": str(run.id),
            "engagement_id": str(run.engagement_id),
            "profile_name": context.get("profile_name"),
            "engagement_name": context.get("engagement_name"),
            "client_name": context.get("client_name"),
            "status": run.status,
            "variant": variant,
        },
        "requested_sections": selected_sections,
        "draft_contract": {
            "facts_source": "structured_payload_only",
            "review_only": True,
            "canonical_report_unchanged": True,
            "allowed_input_facts": allowed_input_facts,
            "prohibited_claims": [
                "untested components as tested",
                "unverified or contradicted findings as supported findings",
                "business impact not present in the payload",
                "remediation or proof facts not grounded in supported evidence",
            ],
            "raw_proof_export_non_llm": True,
            "boundary": REPORT_DRAFT_BOUNDARY,
        },
        "variant_contract": variant_contract,
        "tested_scope": tested_scope,
        "management_decision": management_decision,
        "management_story": management_story,
        "not_tested": not_tested,
        "not_verified": not_verified,
        "supported_findings": supported_findings,
        "methodology": _safe_report_payload(context.get("methodology")),
        "evidence_counts": {
            "supported_findings": len(supported_findings),
            "not_tested": len(not_tested),
            "not_verified": len(not_verified),
        },
        "source_data_categories": sorted(set(filtered_categories)),
        "source_evidence_refs": supported_evidence_refs,
        "boundary": REPORT_DRAFT_BOUNDARY,
    }


def _report_draft_sources(context: dict[str, object]) -> tuple[list[str], list[str]]:
    findings = [finding for finding in context.get("findings", []) if isinstance(finding, Finding)]
    inventory_summary = context.get("inventory_summary", {})
    coverage = context.get("coverage", {})
    source_categories = [
        "engagement.client_context",
        "run.configuration_json",
        "run.profile",
        "run.findings",
        "run.tasks",
        "methodology.run_mapping",
    ]
    if isinstance(inventory_summary, dict) and inventory_summary:
        source_categories.append("inventory_snapshot.summary_json")
    if isinstance(coverage, dict) and coverage.get("methodology_tags"):
        source_categories.append("methodology_tags")

    source_evidence_refs = sorted(
        {
            str(finding.evidence_ref).strip()
            for finding in findings
            if str(finding.evidence_ref or "").strip()
        }
    )
    if source_evidence_refs:
        source_categories.append("finding.evidence_ref")
    return source_categories, source_evidence_refs


def _build_report_draft_section(
    *,
    section_id: str,
    context: dict[str, object],
    variant: str,
    structured_payload: dict[str, object],
    source_categories: list[str],
    source_evidence_refs: list[str],
) -> dict[str, object]:
    title = REPORT_DRAFT_SECTION_LABELS[section_id]
    return {
        "section_id": section_id,
        "title": title,
        "variant": variant,
        "draft": _draft_text_for_section(section_id, context, structured_payload=structured_payload),
        "source_data_categories": source_categories,
        "source_evidence_refs": source_evidence_refs,
        "review_required": True,
    }


def _draft_text_for_section(
    section_id: str,
    context: dict[str, object],
    *,
    structured_payload: dict[str, object],
) -> str:
    payload_findings = structured_payload.get("supported_findings")
    findings = [finding for finding in payload_findings if isinstance(finding, dict)] if isinstance(payload_findings, list) else []
    tested_scope = structured_payload.get("tested_scope") if isinstance(structured_payload.get("tested_scope"), dict) else {}
    variant_contract = (
        structured_payload.get("variant_contract") if isinstance(structured_payload.get("variant_contract"), dict) else {}
    )
    management_decision = (
        structured_payload.get("management_decision")
        if isinstance(structured_payload.get("management_decision"), dict)
        else {}
    )
    management_story = (
        structured_payload.get("management_story")
        if isinstance(structured_payload.get("management_story"), dict)
        else {}
    )
    not_tested = structured_payload.get("not_tested") if isinstance(structured_payload.get("not_tested"), list) else []
    not_verified = structured_payload.get("not_verified") if isinstance(structured_payload.get("not_verified"), list) else []
    inventory_summary = context.get("inventory_summary", {})
    inventory = inventory_summary if isinstance(inventory_summary, dict) else {}
    methodology = context.get("methodology", {})
    coverage = context.get("coverage", {})
    coverage_tags = coverage.get("methodology_tags", []) if isinstance(coverage, dict) else []
    severity_counts = _status_counts([str(finding.get("severity") or "unknown") for finding in findings])
    high_priority = [finding for finding in findings if str(finding.get("severity") or "").lower() in {"critical", "high"}][:3]
    top_findings = high_priority or findings[:3]
    tested_targets = [
        str(target).strip()
        for target in tested_scope.get("tested_targets", [])
        if str(target or "").strip()
    ]
    authorized_targets = [
        str(target).strip()
        for target in tested_scope.get("authorized_targets", [])
        if str(target or "").strip()
    ]
    target_text = ", ".join(tested_targets) or "no completed task target recorded"
    audience = str(variant_contract.get("audience") or "operator")

    if section_id == "executive_summary":
        if audience == "management" and management_decision:
            route = str(management_story.get("route") or "no attack-map route recorded")
            techniques = [
                str(item.get("label") or "").strip()
                for item in management_story.get("techniques", [])
                if isinstance(item, dict) and str(item.get("label") or "").strip()
            ]
            attacker_rows = [
                item
                for item in management_story.get("attacker_story", [])
                if isinstance(item, dict)
            ]
            remediation_tracks = [
                item
                for item in management_story.get("remediation_tracks", [])
                if isinstance(item, dict)
            ]
            standards_badges = [
                str(item.get("badge") or "").strip()
                for item in management_story.get("standards_badges", [])
                if isinstance(item, dict) and str(item.get("badge") or "").strip()
            ]
            technique_text = ", ".join(techniques[:4]) or "no technique facts recorded"
            attacker_text = (
                f"{attacker_rows[0].get('theme')}: {attacker_rows[0].get('attacker')}"
                if attacker_rows
                else "no attacker-path facts recorded"
            )
            remediation_text = (
                f"{remediation_tracks[0].get('theme')}: engineering={remediation_tracks[0].get('engineering')}; "
                f"IT/Ops={remediation_tracks[0].get('it')}"
                if remediation_tracks
                else "no remediation-track facts recorded"
            )
            return (
                f"AI-assisted management draft for {context.get('client_name')} covering only completed-task scope: "
                f"{target_text}. Canonical decision: {management_decision.get('verdict')}. "
                f"{management_decision.get('decision')} Evidence basis: {management_decision.get('evidence')} "
                f"Attack-map route: {route}. Techniques in plain language: {technique_text}. "
                f"Attacker path to explain: {attacker_text}. "
                f"IT and engineering action path: {remediation_text}. "
                f"Standards badges to show: {', '.join(standards_badges) or 'none recorded'}. "
                f"The first action is: {management_decision.get('first_action')}. "
                f"{len(not_tested)} not-tested items and {len(not_verified)} not-verified items remain caveats, not report claims. "
                "Operator review is required before this text can be used in a final report."
            )
        return (
            f"AI-assisted {audience} draft for {context.get('client_name')} covering only completed-task scope: "
            f"{target_text}. The draft may reference {len(findings)} evidence-backed supported findings. "
            f"The run observed {inventory.get('host_count', 0)} hosts, "
            f"{inventory.get('service_count', 0)} services, and {inventory.get('endpoint_count', 0)} endpoints. "
            f"{len(not_tested)} not-tested items and {len(not_verified)} not-verified items remain caveats, not report claims. "
            "Operator review is required before this text can be used in a final report."
        )
    if section_id == "risk_highlights":
        if not top_findings:
            return (
                "AI-assisted draft: no evidence-backed supported findings are available for this draft. "
                "This is not a security guarantee; review not_tested, not_verified, task evidence, inventory, and scope before using this wording."
            )
        if audience == "management" and management_story:
            attacker_rows = [
                item
                for item in management_story.get("attacker_story", [])
                if isinstance(item, dict)
            ]
            attacker_summary = "; ".join(
                f"{item.get('theme')}: {item.get('attacker')}"
                for item in attacker_rows[:3]
            )
            return (
                f"AI-assisted management risk highlights: severity distribution is {json.dumps(severity_counts, sort_keys=True)}. "
                f"Explain why this matters in plain language using these attacker paths: {attacker_summary or 'no attacker-path facts recorded'}. "
                "Do not use raw tool names or proof tokens in management wording."
            )
        highlights = "; ".join(_draft_finding_line_payload(finding) for finding in top_findings)
        return (
            f"AI-assisted draft: priority review should focus on {highlights}. "
            f"Severity distribution is {json.dumps(severity_counts, sort_keys=True)} and must be verified by the operator."
        )
    if section_id == "remediation_overview":
        remediation = {
            severity: count
            for severity, count in severity_counts.items()
            if severity in {"critical", "high", "medium", "low", "info", "unknown"}
        }
        if audience == "management" and management_story:
            tracks = [
                item
                for item in management_story.get("remediation_tracks", [])
                if isinstance(item, dict)
            ]
            track_text = "; ".join(
                f"{item.get('theme')}: engineering={item.get('engineering')}; IT/Ops={item.get('it')}; done={item.get('done')}"
                for item in tracks[:3]
            )
            return (
                "AI-assisted management remediation overview: split next steps between engineering and IT/Ops, "
                f"using only these grounded tracks: {track_text or 'no remediation tracks recorded'}. "
                f"Supported-finding priority counts are {json.dumps(remediation, sort_keys=True)}."
            )
        return (
            "AI-assisted draft: remediation planning should follow only supported findings, stored evidence refs, "
            f"and retest state. Current supported-finding priority counts are {json.dumps(remediation, sort_keys=True)}."
        )
    if section_id == "evidence_basis":
        linked = sum(1 for finding in findings if finding.get("evidence_ref"))
        return (
            f"AI-assisted draft: this narrative is grounded in {linked} evidence-linked findings, "
            f"{tested_scope.get('completed_task_count', 0)} completed task records, and "
            f"{len(authorized_targets)} authorized target entries. Raw proof export remains deterministic."
        )
    if section_id == "methodology_context":
        return (
            "AI-assisted draft: methodology context follows the existing run mapping "
            f"({methodology.get('ptes_phase_label', 'PTES n/a')} / {methodology.get('nist_phase_label', 'NIST n/a')}) "
            f"and observed tags {', '.join(coverage_tags) or 'none recorded'}."
        )
    return "AI-assisted draft section unavailable for this run context."


def _draft_finding_line(finding: Finding) -> str:
    evidence = finding.evidence_ref or "no linked evidence ref"
    return f"{finding.severity} {finding.title} on {finding.target_id} ({evidence})"


def _draft_finding_line_payload(finding: dict[str, object]) -> str:
    evidence = str(finding.get("evidence_ref") or "no linked evidence ref")
    severity = str(finding.get("severity") or "unknown")
    title = str(finding.get("title") or "Untitled finding")
    target = str(finding.get("target_id") or "target not recorded")
    validation_status = str(finding.get("validation_status") or "unvalidated")
    return f"{severity} {title} on {target} ({evidence}; validation={validation_status})"


def _render_report_draft_markdown(
    *,
    run: Run,
    variant: str,
    provider: str,
    sections: list[dict[str, object]],
    source_categories: list[str],
    source_evidence_refs: list[str],
) -> str:
    lines = [
        f"# AI-assisted Report Draft: {variant}",
        "",
        f"- Source Run: {run.id}",
        f"- Provider: {provider}",
        "- Status: draft_ready",
        "- Review Required: yes",
        "- Canonical Report Changed: no",
        f"- Boundary: {REPORT_DRAFT_BOUNDARY}",
        "",
        "## Source Traceability",
        "",
        f"- Source Data Categories: {', '.join(source_categories)}",
        f"- Source Evidence Refs: {', '.join(source_evidence_refs) or 'No linked finding evidence refs recorded'}",
        "",
    ]
    for section in sections:
        lines.extend(
            [
                f"## {section['title']}",
                "",
                str(section["draft"]),
                "",
            ]
        )
    return "\n".join(lines).rstrip() + "\n"


def build_report_catalog(run: Run, *, context: dict[str, object] | None = None) -> list[RunReportCatalogItemRead]:
    context = context or report_context(run)
    linked_evidence = sum(1 for finding in context["findings"] if finding.evidence_ref)
    lifecycle_summary = report_lifecycle_summary(run, context, linked_evidence=linked_evidence)
    availability = report_availability_for_run(run, context, lifecycle_summary)
    catalog: list[RunReportCatalogItemRead] = []
    for variant in PRIMARY_REPORT_VARIANTS:
        title = REPORT_VARIANT_LABELS[variant]
        default_framework = DEFAULT_COMPLIANCE_FRAMEWORK if variant == "compliance" else None
        markdown_content = render_markdown_report(
            run,
            variant=variant,
            framework=default_framework,
            context=context,
        )
        framework_summary = (
            compliance_framework_package_context(context, default_framework)
            if variant == "compliance" and default_framework in COMPLIANCE_FRAMEWORK_PACKAGES
            else {}
        )
        assurance_summary = assurance_package_context(context) if variant == "assurance" else {}
        compliance_summary = framework_summary
        run_narrative_summary = {}
        query_suffix = (
            f"variant={variant}&framework={default_framework}"
            if variant == "compliance" and default_framework is not None
            else f"variant={variant}"
        )
        catalog.append(
            RunReportCatalogItemRead(
                variant=variant,
                title=title,
                description=REPORT_VARIANT_DESCRIPTIONS[variant],
                source_run_id=run.id,
                generated_at=run.created_at,
                available_formats=["markdown", "html", "pdf"],
                methodology_references=report_methodology_references_for_variant(
                    run,
                    variant,
                    framework=default_framework,
                ),
                source_scope_profile={
                    "run_profile": context["profile_name"],
                    "assessment_type": context["configuration"].get("assessment_type"),
                    "enabled_modules": context["configuration"].get("enabled_modules", []),
                    "targets": context["configuration"].get("targets", {}),
                },
                included_findings={
                    "count": len(context["findings"]),
                    "by_severity": context["findings_by_severity"],
                    "by_status": context["findings_by_status"],
                    "report_sections": context["report_sections"],
                    "test_coverage": context["test_coverage"],
                    "coverage_truth": context.get("coverage_truth", {}),
                },
                included_inventory={
                    "host_count": context["inventory_summary"].get("host_count", 0),
                    "service_count": context["inventory_summary"].get("service_count", 0),
                    "endpoint_count": context["inventory_summary"].get("endpoint_count", 0),
                    "technology_count": context["inventory_summary"].get("technology_count", 0),
                    "wireless_access_point_count": context["inventory_summary"].get(
                        "wireless_access_point_count",
                        0,
                    ),
                    "wireless_network_count": context["inventory_summary"].get(
                        "wireless_network_count",
                        0,
                    ),
                    "confidence_score": context["inventory_summary"].get("confidence_score", 0.0),
                },
                evidence_status={
                    "linked_findings": linked_evidence,
                    "total_findings": len(context["findings"]),
                    "completeness_ratio": (linked_evidence / len(context["findings"])) if context["findings"] else 0.0,
                },
                compliance_summary={
                    "package": compliance_summary.get("package"),
                    "reference": compliance_summary.get("reference"),
                    "mapped_findings": compliance_summary.get("mapped_findings"),
                    "unmapped_findings": compliance_summary.get("unmapped_findings"),
                    "mapped_control_count": compliance_summary.get("mapped_control_count"),
                    "total_mapped_controls": compliance_summary.get("total_mapped_controls"),
                    "boundary": compliance_summary.get("boundary"),
                    "mapped_label": compliance_summary.get("mapped_label"),
                    "available_frameworks": list(COMPLIANCE_REPORT_FRAMEWORKS),
                    "selected_framework": default_framework,
                    "gap_advisor": compliance_gap_advisor_context(context, default_framework),
                }
                if variant == "compliance"
                else {},
                assurance_summary=assurance_summary,
                adaptive_change_summary=context["adaptive_change"],
                ai_draft_summary=report_draft_summary_for_catalog(run, variant),
                run_narrative_summary=run_narrative_summary,
                version_label=f"{variant}-{run.created_at:%Y%m%dT%H%M%S}",
                content_sha256=hashlib.sha256(markdown_content.encode("utf-8")).hexdigest(),
                availability_status=availability["status"],
                availability_label=availability["label"],
                availability_reason=availability["reason"],
                preview_allowed=bool(availability["preview_allowed"]),
                export_allowed=bool(availability["export_allowed"]),
                draft_allowed=bool(availability["draft_allowed"]),
                lifecycle_summary=lifecycle_summary,
                export_paths={
                    "markdown": f"/api/v1/runs/{run.id}/report?format=markdown&{query_suffix}",
                    "html": f"/api/v1/runs/{run.id}/report?format=html&{query_suffix}",
                    "pdf": f"/api/v1/runs/{run.id}/report?format=pdf&{query_suffix}",
                },
                download_names={
                    "markdown": f"aegispt-run-{run.id}-{variant}.md",
                    "html": f"aegispt-run-{run.id}-{variant}.html",
                    "pdf": f"aegispt-run-{run.id}-{variant}.pdf",
                },
            )
        )
    return catalog


def render_markdown_report(
    run: Run,
    *,
    variant: str = "technical",
    framework: str | None = None,
    context: dict[str, object] | None = None,
) -> str:
    context = context or report_context(run)
    requested_variant = variant
    framework_variant = compliance_framework_for_request(requested_variant, framework)
    if str(requested_variant or "").strip().lower() == "management_nl":
        return _render_management_nl_markdown(run, context)
    variant = normalize_report_variant(requested_variant)
    if variant == "summary":
        return _finalize_management_markdown_report(run, context, _render_executive_markdown(run, context))
    if variant == "evidence":
        return _finalize_markdown_report(run, context, variant, _render_evidence_markdown(run, context))
    if variant == "retest":
        return _finalize_markdown_report(run, context, variant, _render_retest_markdown(run, context))
    if variant == "compliance":
        if framework_variant == "soc2":
            return _finalize_markdown_report(run, context, variant, _render_soc2_markdown(run, context))
        if framework_variant == "nfir":
            return _finalize_markdown_report(run, context, variant, _render_nfir_markdown(run, context))
        return _finalize_markdown_report(
            run,
            context,
            variant,
            _render_compliance_markdown(run, context, framework_variant),
        )

    profile_name = context["profile_name"]
    engagement_name = context["engagement_name"]
    client_name = context["client_name"]
    findings = context["findings"]
    tasks = context["tasks"]
    approvals = context["approvals"]
    findings_by_severity = context["findings_by_severity"]
    findings_by_status = context["findings_by_status"]
    methodology = context["methodology"]
    adaptive_pack = context["adaptive_pack"]
    adaptive_change = context["adaptive_change"]
    coverage = context["coverage"]
    latest_scope = context["latest_scope"]
    remediation_counts = context["remediation_counts"]
    _ = context["inventory_summary"]
    assert isinstance(findings, list)
    confirmed_findings = [finding for finding in findings if isinstance(finding, Finding)]
    score = _risk_score(confirmed_findings)

    lines = [
        f"# AegisPT Run Report: {run.id}",
        "",
        "## Executive Summary",
        "",
        f"- Engagement: {engagement_name}",
        f"- Client: {client_name}",
        f"- Run Profile: {profile_name}",
        f"- Run Status: {run.status}",
        f"- Requested By: {run.requested_by}",
        f"- Created At: {run.created_at.isoformat()}",
        f"- Operator Workflow Stage: {methodology['operator_stage']}",
        f"- PTES Mapping for This Run: {methodology['ptes_phase_label']}",
        f"- NIST Mapping for This Run: {methodology['nist_phase_label']}",
        f"- Adaptive Coverage: {adaptive_pack['label']}",
        f"- Adaptive Change Review: {adaptive_change['summary_line']}",
            f"- Finding Count: {len(findings)}",
            "",
            "## Executive Narrative",
            "",
            _executive_narrative(run, context),
            "",
            *_render_evidence_first_attack_story_markdown(run, context),
            *_render_evidence_gap_report_markdown(context),
            "## Exposure Score",
            "",
            f"Risk Level: {_risk_level(score)} ({score}/10) {_risk_bar(score)}",
            "",
            "## Remediation Priority Table",
            "",
            *_render_remediation_priority_table_markdown(confirmed_findings),
            "",
            "## Discovery Summary",
            "",
        *_inventory_summary_lines(context),
        *_render_test_coverage_markdown(context),
        *_render_adaptive_technical_sections_markdown(context),
        "## Scope",
        "",
    ]

    if latest_scope is not None:
        lines.extend(
            [
                "### Allowlist",
                "",
                "```json",
                format_json_block(latest_scope.allowlist_json),
                "```",
                "",
                "### Denylist",
                "",
                "```json",
                format_json_block(latest_scope.denylist_json),
                "```",
                "",
            ]
        )
    else:
        lines.extend(["- No scope snapshot loaded for this run.", ""])

    lines.extend(_render_configuration_markdown(context))

    lines.extend(
        [
            "## Rules of Engagement Summary",
            "",
            f"- ROE Reference: {run.engagement.roe_ref if run.engagement is not None and run.engagement.roe_ref else 'Not Recorded'}",
            f"- Approval Records: {len(approvals)}",
            "- Guardrails: evidence-first collection, replayable artifacts, and approval-gated active validation where applicable.",
            "",
            "## Methodology",
            "",
            "- Assessment lifecycle: PTES",
            f"- Web/API technical coverage model: OWASP WSTG {WSTG_STABLE_VERSION}",
            "- Structured testing and reporting discipline: NIST SP 800-115",
            f"- Optional control-verification layer: OWASP ASVS {ASVS_STABLE_VERSION} when a precise reference is assigned",
            "",
            "### PTES Lifecycle Alignment",
            "",
            "- Pre-Engagement -> engagement definition, scope, and rules of engagement setup",
            "- Intelligence Gathering -> reconnaissance and target discovery activities",
            "- Analysis / Validation -> passive validation and evidence-backed issue confirmation",
            "- Controlled Exploitation / Verification -> approval-gated active validation and internal adversary simulation steps",
            "- Reporting -> executive and technical reporting with linked evidence",
            "- Retest -> rerun and verification-state updates after remediation",
            "",
            "### NIST SP 800-115 Alignment",
            "",
            "- Planning -> scope, logistics, approvals, and rules of engagement",
            "- Discovery -> reconnaissance, identification, and technical analysis",
            "- Attack -> controlled validation of exploitable weaknesses",
            "- Reporting -> structured findings, evidence, remediation, and verification output",
            "- Post-Testing -> remediation follow-up and retest handling",
            "",
            "## Coverage Summary",
            "",
            f"- Tools Executed: {', '.join(coverage['tools']) or 'None'}",
            f"- WSTG Areas Covered: {', '.join(coverage['wstg_areas']) or 'Not Assigned'}",
            f"- Control Families Seen: {', '.join(coverage['control_families']) or 'Not Assigned'}",
            f"- Methodology Tags Seen: {', '.join(coverage['methodology_tags']) or 'Not Assigned'}",
            "",
            "### By Severity",
            "",
            *_format_count_map_markdown(findings_by_severity),
            "",
            "### By Status",
            "",
            *_format_count_map_markdown(findings_by_status),
            "",
            "## Adaptive Coverage",
            "",
            f"- Runtime Pack: {adaptive_pack['label']}",
            f"- Deployment Target: {adaptive_pack['deployment_target'] or 'Not Bound'}",
            f"- Deployment Status: {adaptive_pack['deployment_status'] or 'Not Bound'}",
            f"- Inventory Snapshot Used: {adaptive_pack['manifest'].get('inventory_snapshot_id') or 'Not Assigned'}",
            f"- Relevance Decision: {adaptive_pack['manifest'].get('relevance_decision_id') or 'Not Assigned'}",
            f"- Threat Intel References: {', '.join(adaptive_pack['manifest'].get('threat_intel_refs', [])) or 'None'}",
            f"- Generation Reason: {adaptive_pack['manifest'].get('generation_reason') or 'Standard coverage only'}",
            "",
            *_render_adaptive_change_markdown(context),
            "## Remediation Priorities",
            "",
            *_format_count_map_markdown(remediation_counts),
        ]
    )

    if findings:
        for finding in findings[:5]:
            lines.append(f"- {remediation_priority_for_finding(finding)}: {finding.title}")
    else:
        lines.append("- No confirmed findings recorded.")

    lines.extend(["", "## Confirmed Findings", ""])
    lines.extend(_render_deduplicated_findings_markdown(confirmed_findings))

    lines.extend(_render_rationale_ledger_markdown(context))

    lines.extend(["## Evidence and Reproduction", ""])
    if tasks:
        for task in tasks:
            target_label = task_targets_display(task)
            lines.extend(
                [
                    f"### Task {task.id}",
                    "",
                    f"- Tool: {task.tool}",
                    f"- Target: {target_label}",
                    f"- Status: {task.status}",
                ]
            )
            if task.executions:
                for execution in task.executions:
                    lines.extend(
                        [
                            f"- Execution {execution.id}: exit_code={execution.exit_code}, tool_version={execution.tool_version}",
                        ]
                    )
                    for artifact in sort_artifacts(list(execution.artifacts)):
                        artifact_name = str(artifact.metadata_json.get("name", artifact.id))
                        lines.append(
                            f"  artifact: {artifact_name} ({artifact.uri}) download={artifact_download_path(artifact.id)}"
                        )
            else:
                lines.append("- No executions recorded")
            lines.append("")
    else:
        lines.extend(["No tasks recorded.", ""])

    lines.extend(
        [
            "## Retest and Verification",
            "",
            "### Verification Status Counts",
            "",
            *_format_count_map_markdown(findings_by_status),
            f"- Resolved Findings: {sum(1 for finding in findings if finding.status == 'resolved')}",
            f"- Findings Requiring Further Validation: {sum(1 for finding in findings if finding.status in {'open', 'triaged', 'in_progress', 'reopened'})}",
            "",
        ]
    )

    return _finalize_markdown_report(run, context, variant, "\n".join(lines).rstrip() + "\n")


def render_html_report(
    run: Run,
    *,
    variant: str = "technical",
    framework: str | None = None,
    context: dict[str, object] | None = None,
) -> str:
    context = context or report_context(run)
    requested_variant = variant
    framework_variant = compliance_framework_for_request(requested_variant, framework)
    variant = normalize_report_variant(requested_variant)
    profile_name = context["profile_name"]
    engagement_name = context["engagement_name"]
    client_name = context["client_name"]
    findings = context["findings"]
    tasks = context["tasks"]
    approvals = context["approvals"]
    findings_by_severity = context["findings_by_severity"]
    findings_by_status = context["findings_by_status"]
    methodology = context["methodology"]
    adaptive_pack = context["adaptive_pack"]
    adaptive_change = context["adaptive_change"]
    coverage = context["coverage"]
    latest_scope = context["latest_scope"]
    remediation_counts = context["remediation_counts"]
    inventory_summary = context["inventory_summary"]
    confirmed_findings = [finding for finding in findings if isinstance(finding, Finding)]
    score = _risk_score(confirmed_findings)
    decision_facts = _management_decision_facts(run, context)
    story_context = _management_assessment_story_context(run, context)

    summary_rows = [
        ("Engagement", engagement_name),
        ("Client", client_name),
        ("Run Profile", profile_name),
        ("Run Status", run.status),
        ("Requested By", run.requested_by),
        ("Created At", run.created_at.isoformat()),
        ("Operator Workflow Stage", methodology["operator_stage"]),
        ("PTES Mapping", methodology["ptes_phase_label"]),
        ("NIST Mapping", methodology["nist_phase_label"]),
        ("Adaptive Coverage", str(adaptive_pack["label"])),
        ("Adaptive Change Review", str(adaptive_change["summary_line"])),
        ("Finding Count", str(len(findings))),
        ("Hosts Observed", str(inventory_summary.get("host_count", 0))),
        ("Services Observed", str(inventory_summary.get("service_count", 0))),
        ("Endpoints Observed", str(inventory_summary.get("endpoint_count", 0))),
    ]
    if variant == "compliance" and framework_variant == "soc2":
        soc2 = soc2_report_package_context(context)
        summary_rows.extend(
            [
                ("SOC 2 Mapped Findings", str(soc2["mapped_findings"])),
                ("SOC 2 Unmapped Findings", str(soc2["unmapped_findings"])),
                ("SOC 2 Controls With Findings", f"{soc2['mapped_control_count']} of {soc2['total_mapped_controls']}"),
            ]
        )
    if variant == "compliance" and framework_variant in COMPLIANCE_FRAMEWORK_PACKAGES:
        compliance = compliance_framework_package_context(context, framework_variant)
        summary_rows.extend(
            [
                (f"{compliance['package']} Mapped Findings", str(compliance["mapped_findings"])),
                (f"{compliance['package']} Unmapped Findings", str(compliance["unmapped_findings"])),
                (str(compliance["mapped_label"]), f"{compliance['mapped_control_count']} of {compliance['total_mapped_controls']}"),
                (str(compliance["boundary_label"]), str(compliance["boundary"])),
            ]
        )
    if variant == "compliance" and framework_variant == "nfir":
        nfir = nfir_report_context(run, context)
        phase_count = sum(1 for phase in nfir["phases"] if isinstance(phase, dict) and phase["status"] == "executed")
        summary_rows.extend(
            [
                ("NFIR Reference", str(nfir["reference"])),
                ("NFIR Executed Phases", f"{phase_count} of {len(NFIR_PHASES)}"),
                ("NFIR Boundary", str(nfir["boundary"])),
            ]
        )
    if variant == "assurance":
        assurance = assurance_package_context(context)
        summary_rows.extend(
            [
                ("Assurance Boundary", str(assurance["boundary"])),
                ("Evidence-Linked Findings", f"{assurance['evidence_linked_findings']} of {assurance['total_findings']}"),
                ("Evidence Artifacts", str(assurance["evidence_artifacts"])),
                ("Residual-Risk Findings", str(assurance["residual_risk_findings"])),
                ("Out-of-Scope Items", str(len(assurance["out_of_scope_items"]))),
            ]
        )
    if variant == "attack_narrative":
        narrative = run_attack_narrative_context(run, context)
        attack_summary = narrative["attack_path_summary"]
        chain_summary = narrative["chain_detection_summary"]
        summary_rows.extend(
            [
                ("Narrative Mode", "AI-assisted / advisory"),
                ("Narrative Status", str(narrative["status"])),
                ("Operator Review Required", "yes"),
                ("Canonical Report Changed", "no"),
                ("Candidate Paths", str(attack_summary.get("candidate_path_count", 0))),
                ("Stored Chain Detections", str(chain_summary.get("chain_count", 0))),
            ]
        )
    if variant == "summary":
        summary_rows = [
            ("Customer", _management_safe_text(client_name, fallback="the customer")),
            ("Assessed System", _management_scope_label(context)),
            ("Assessment State", _humanize_key(str(run.status))),
            ("Evidence-backed Findings", str(len(confirmed_findings))),
            (
                "High/Critical Items",
                str(
                    sum(
                        1
                        for finding in confirmed_findings
                        if str(finding.severity or "").lower() in {"critical", "high"}
                    )
                ),
            ),
        ]
    summary_html = "".join(
        f"<tr><th>{escape(label)}</th><td>{escape(value)}</td></tr>" for label, value in summary_rows
    )

    approvals_html = "".join(
        "<li>"
        f"{escape(approval.step_id)}: {escape(approval.decision)} by {escape(approval.approver_id)} "
        f"at {escape(approval.created_at.isoformat())}"
        "</li>"
        for approval in approvals
    ) or "<li>No approvals recorded</li>"

    scope_html = (
        "<div class='scope-grid'>"
        f"<section><h3>Allowlist</h3><pre>{escape(format_json_block(latest_scope.allowlist_json))}</pre></section>"
        f"<section><h3>Denylist</h3><pre>{escape(format_json_block(latest_scope.denylist_json))}</pre></section>"
        "</div>"
        if latest_scope is not None
        else "<p>No scope snapshot loaded for this run.</p>"
    )

    methodology_html = (
        "<ul>"
        "<li>PTES governs the assessment lifecycle and operator workflow alignment.</li>"
        f"<li>OWASP WSTG {escape(WSTG_STABLE_VERSION)} governs web and API technical coverage references.</li>"
        "<li>NIST SP 800-115 governs technical testing discipline, evidence handling, and reporting structure.</li>"
        f"<li>OWASP ASVS {escape(ASVS_STABLE_VERSION)} remains an optional control-reference layer when analysts assign precise references.</li>"
        "</ul>"
    )

    coverage_html = (
        "<ul>"
        f"<li><strong>Tools Executed:</strong> {escape(', '.join(coverage['tools']) or 'None')}</li>"
        f"<li><strong>WSTG Areas Covered:</strong> {escape(', '.join(coverage['wstg_areas']) or 'Not Assigned')}</li>"
        f"<li><strong>Control Families Seen:</strong> {escape(', '.join(coverage['control_families']) or 'Not Assigned')}</li>"
        "</ul>"
        "<h3>Priority Counts</h3>"
        f"{_format_count_map_html(remediation_counts)}"
    )
    inventory_html = (
        "<ul>"
        f"<li><strong>Hosts Observed:</strong> {escape(str(inventory_summary.get('host_count', 0)))}</li>"
        f"<li><strong>Services Observed:</strong> {escape(str(inventory_summary.get('service_count', 0)))}</li>"
        f"<li><strong>Endpoints Observed:</strong> {escape(str(inventory_summary.get('endpoint_count', 0)))}</li>"
        f"<li><strong>Technologies Observed:</strong> {escape(str(inventory_summary.get('technology_count', 0)))}</li>"
        f"<li><strong>Inventory Confidence:</strong> {escape(str(inventory_summary.get('confidence_score', 0.0)))}</li>"
        "</ul>"
        if inventory_summary
        else "<p>No discovery-confirmed inventory snapshot is linked to this run.</p>"
    )

    adaptive_pack_html = (
        "<ul>"
        f"<li><strong>Runtime Pack:</strong> {escape(str(adaptive_pack['label']))}</li>"
        f"<li><strong>Deployment Target:</strong> {escape(str(adaptive_pack['deployment_target'] or 'Not Bound'))}</li>"
        f"<li><strong>Deployment Status:</strong> {escape(str(adaptive_pack['deployment_status'] or 'Not Bound'))}</li>"
        f"<li><strong>Inventory Snapshot Used:</strong> {escape(str(adaptive_pack['manifest'].get('inventory_snapshot_id') or 'Not Assigned'))}</li>"
        f"<li><strong>Relevance Decision:</strong> {escape(str(adaptive_pack['manifest'].get('relevance_decision_id') or 'Not Assigned'))}</li>"
        f"<li><strong>Threat Intel References:</strong> {escape(', '.join(adaptive_pack['manifest'].get('threat_intel_refs', [])) or 'None')}</li>"
        f"<li><strong>Generation Reason:</strong> {escape(str(adaptive_pack['manifest'].get('generation_reason') or 'Standard coverage only'))}</li>"
        "</ul>"
    )
    adaptive_change_html = _render_adaptive_change_html(context)

    findings_html = _render_deduplicated_findings_html(confirmed_findings)

    task_sections: list[str] = []
    for task in tasks:
        target_label = task_targets_display(task)
        execution_lines: list[str] = []
        for execution in task.executions:
            artifact_lines = "".join(
                "<li>"
                f"{escape(str(artifact.metadata_json.get('name', artifact.id)))} - "
                f"<code>{escape(artifact.uri)}</code> - "
                f"<a href=\"{escape(artifact_download_path(artifact.id))}\">download</a>"
                "</li>"
                for artifact in sort_artifacts(list(execution.artifacts))
            )
            execution_lines.append(
                "<li>"
                f"Execution {escape(str(execution.id))}: exit_code={execution.exit_code}, "
                f"tool_version={escape(execution.tool_version)}"
                + (f"<ul>{artifact_lines}</ul>" if artifact_lines else "")
                + "</li>"
            )
        task_sections.append(
            "<article class='task'>"
            f"<h3>Task {escape(str(task.id))}</h3>"
            f"<p><strong>Tool:</strong> {escape(task.tool)} | "
            f"<strong>Target:</strong> {escape(target_label)} | "
            f"<strong>Status:</strong> {escape(task.status)}</p>"
            + (f"<ul>{''.join(execution_lines)}</ul>" if execution_lines else "<p>No executions recorded.</p>")
            + "</article>"
        )

    tasks_html = "".join(task_sections) or "<p>No tasks recorded.</p>"

    configuration_html = _render_configuration_html(context)
    rationale_ledger_section = _render_rationale_ledger_html(context) if variant == "technical" else ""

    if variant == "summary":
        management_highlights = "".join(
            "<li>"
            f"{escape(_humanize_key(str(row['severity'])))}: "
            f"{escape(str(row['title']))} - {escape(str(row['impact']))}"
            "</li>"
            for row in _management_cluster_rows(confirmed_findings)[:5]
        ) or "<li>No confirmed findings recorded.</li>"
        executive_panel = f"""
        <section class="panel">
          <h2>Executive Narrative</h2>
          <p>{escape(_executive_narrative(run, context))}</p>
          {_management_decision_html(decision_facts)}
          {_management_story_html(story_context)}
          <h3>Exposure Score</h3>
          <p><strong>Risk Level:</strong> {escape(_risk_level(score))} ({score}/10) <code>{escape(_risk_bar(score))}</code></p>
          <h3>Remediation Priority Table</h3>
          {_render_remediation_priority_table_html(confirmed_findings, management=True)}
          <h3>Risk Highlights</h3>
          <ul class="meta-list">{management_highlights}</ul>
        </section>
        """
    else:
        executive_panel = f"""
        <section class="panel">
          <h2>Executive Narrative</h2>
          <p>{escape(_executive_narrative(run, context))}</p>
          {_render_evidence_first_attack_story_html(run, context)}
          <h3>Exposure Score</h3>
          <p><strong>Risk Level:</strong> {escape(_risk_level(score))} ({score}/10) <code>{escape(_risk_bar(score))}</code></p>
          <h3>Remediation Priority Table</h3>
          {_render_remediation_priority_table_html(confirmed_findings)}
          <h3>Risk Highlights</h3>
          <ul class="meta-list">{"".join(f"<li>{escape(finding.severity.upper())}: {escape(finding.title)}</li>" for finding in confirmed_findings[:5]) or "<li>No confirmed findings recorded.</li>"}</ul>
        </section>
        """

    report_context_pairs = (
        [
            ("Customer", _management_safe_text(client_name, fallback="the customer")),
            ("Assessed System", _management_scope_label(context)),
            ("Status", _humanize_key(str(run.status))),
        ]
        if variant == "summary"
        else [
            ("Engagement", engagement_name),
            ("Client", client_name),
            ("Profile", profile_name),
            ("Status", run.status),
            ("Run", _short_run_id(run)),
        ]
    )
    report_context_html = "".join(
        f"<span class='context-chip'><strong>{escape(label)}:</strong> {escape(value)}</span>"
        for label, value in report_context_pairs
    )
    report_header_html = (
        (
            "<section class=\"panel report-professional-header\">"
            "<h2>Report Boundary</h2>"
            "<table>"
            "<tr><th>Assessment Title</th><td>Management Summary</td></tr>"
            f"<tr><th>Assessed System</th><td>{escape(_management_scope_label(context))}</td></tr>"
            f"<tr><th>Date Range</th><td>{escape(_report_date_range(run))}</td></tr>"
            "<tr><th>Evidence Basis</th><td>Stored AegisPT findings and linked evidence for the tested scope.</td></tr>"
            "</table>"
            "</section>"
        )
        if variant == "summary"
        else (
            "<section class=\"panel report-professional-header\">"
            "<h2>Report Header</h2>"
            "<table>"
            f"<tr><th>Assessment Title</th><td>{escape(REPORT_VARIANT_LABELS.get(variant, REPORT_VARIANT_LABELS['technical']))}</td></tr>"
            f"<tr><th>Target</th><td>{escape(_report_target_summary(context))}</td></tr>"
            f"<tr><th>Date Range</th><td>{escape(_report_date_range(run))}</td></tr>"
            f"<tr><th>Authorized By</th><td>{escape(_authorized_by(run, [approval for approval in approvals if isinstance(approval, Approval)]))}</td></tr>"
            f"<tr><th>Run ID</th><td>{escape(_short_run_id(run))}</td></tr>"
            f"<tr><th>AegisPT Version</th><td>{escape(AEGISPT_REPORT_VERSION)}</td></tr>"
            f"<tr><th>Methodology Version</th><td>{escape(METHODOLOGY_VERSION)}</td></tr>"
            "</table>"
            "</section>"
        )
    )

    if variant == "summary":
        summary_next_steps = "".join(
            f"<li>{escape(str(row['title']))}: {escape(str(row['action']))}</li>"
            for row in _management_cluster_rows(confirmed_findings)[:5]
        ) or "<li>Keep planned monitoring in place and retest after material changes.</li>"
        findings_section = ""
        evidence_section = ""
        verification_section = f"""
        <section class="panel">
          <h2>Recommended Next Steps</h2>
          <ul class="meta-list">
            {summary_next_steps}
            <li>Use the technical report only when analysts need evidence references, replay artifacts, or reproduction detail.</li>
          </ul>
        </section>
        """
        title = "AegisPT Management Summary"
    elif variant == "evidence":
        findings_section = f"""
        <section class="panel">
          <h2>Findings Evidence Map</h2>
          {findings_html}
        </section>
        """
        evidence_section = f"""
        <section class="panel">
          <h2>Task Evidence</h2>
          {tasks_html}
        </section>
        """
        verification_section = ""
        title = "AegisPT Evidence Appendix"
    elif variant == "retest":
        findings_section = f"""
        <section class="panel">
          <h2>Findings Verification State</h2>
          {findings_html}
        </section>
        """
        evidence_section = ""
        verification_section = _render_proof_of_resolution_html(run, context) + f"""
        <section class="panel">
          <h2>Retest and Verification</h2>
          <h3>Verification Status Counts</h3>
          {_format_count_map_html(findings_by_status)}
          <p><strong>Resolved Findings:</strong> {sum(1 for finding in findings if finding.status == 'resolved')}</p>
          <p><strong>Findings Requiring Further Validation:</strong> {sum(1 for finding in findings if finding.status in {'open', 'triaged', 'in_progress', 'reopened'})}</p>
        </section>
        """
        title = "AegisPT Retest / Verification Report"
    elif variant == "compliance" and framework_variant == "soc2":
        findings_section = _render_soc2_html(run, context)
        evidence_section = ""
        verification_section = ""
        title = "AegisPT SOC 2 Report Package"
    elif variant == "compliance" and framework_variant == "nfir":
        findings_section = _render_nfir_html(run, context)
        evidence_section = ""
        verification_section = ""
        title = "AegisPT NFIR Evidence Mapping"
    elif variant == "compliance":
        compliance_package = COMPLIANCE_FRAMEWORK_PACKAGES[framework_variant]
        findings_section = _render_compliance_html(run, context, framework_variant)
        evidence_section = ""
        verification_section = ""
        title = str(compliance_package["heading"])
    else:
        findings_section = f"""
        <section class="panel">
          <h2>Confirmed Findings</h2>
          {findings_html}
        </section>
        """
        evidence_section = f"""
        <section class="panel">
          <h2>Evidence and Reproduction</h2>
          {tasks_html}
        </section>
        """
        verification_section = f"""
        <section class="panel">
          <h2>Retest and Verification</h2>
          <h3>Verification Status Counts</h3>
          {_format_count_map_html(findings_by_status)}
          <p><strong>Resolved Findings:</strong> {sum(1 for finding in findings if finding.status == 'resolved')}</p>
          <p><strong>Findings Requiring Further Validation:</strong> {sum(1 for finding in findings if finding.status in {'open', 'triaged', 'in_progress', 'reopened'})}</p>
        </section>
        """
        title = "AegisPT Run Report"

    report_lede = (
        "SOC 2 Security-package output maps existing evidence-backed findings to an additive report-time control table without changing the core execution model."
        if variant == "compliance" and framework_variant == "soc2"
        else "NFIR evidence-mapping output maps existing evidence-backed findings and tasks to seven report-time pentest phases without claiming NFIR certification."
        if variant == "compliance" and framework_variant == "nfir"
        else f"{COMPLIANCE_FRAMEWORK_PACKAGES[framework_variant]['package']} evidence-package output maps existing evidence-backed findings to an additive report-time control table without changing the core execution model or claiming certification/compliance validation."
        if variant == "compliance"
        else "Evidence-first assessment output aligned to PTES, OWASP WSTG, and NIST SP 800-115 without changing the core execution model."
    )
    if variant == "summary":
        test_coverage = context.get("test_coverage", {})
        coverage_brief = (
            (
                f"<li>Test activity reviewed: {escape(str(test_coverage.get('executed_task_count', 0)))} "
                f"of {escape(str(test_coverage.get('total_task_count', 0)))} checks.</li>"
                "<li>This summary reflects recorded evidence for the tested scope only.</li>"
            )
            if isinstance(test_coverage, dict)
            else "<li>Coverage data is unavailable for this run.</li>"
        )
        test_coverage_section_html = f"""
        <section class="panel">
          <h2>Methodology Used</h2>
          <p>This management summary is not a certification, but the assessment and reporting are aligned to recognized testing references:</p>
          {_management_methodology_html()}
        </section>
        <section class="panel">
          <h2>Tested / Not Tested</h2>
          <ul class="meta-list">{coverage_brief}</ul>
        </section>
        """
        technical_detail_sections_html = f"""
        {_management_risk_picture_html(context)}
        {_management_attacker_html(context)}
        {_management_remediation_html(context)}
        {_management_test_origin_html(run, context)}
        {_management_standards_html()}
        """
        report_lede = "Business-facing summary of recorded AegisPT evidence, risk themes, and recommended remediation priorities."
    else:
        test_coverage_section_html = _render_test_coverage_html(context)
        technical_detail_sections_html = f"""
        {_render_adaptive_technical_sections_html(context) if variant == "technical" else ""}
        <section class="panel">
          <h2>Scope</h2>
          {scope_html}
        </section>

        <section class="panel">
          <h2>Run Configuration</h2>
          {configuration_html}
        </section>

        <section class="panel">
          <h2>Rules of Engagement Summary</h2>
          <p><strong>ROE Reference:</strong> {escape(run.engagement.roe_ref if run.engagement is not None and run.engagement.roe_ref else "Not Recorded")}</p>
          <ul class="meta-list">{approvals_html}</ul>
        </section>

        <section class="panel">
          <h2>Methodology Summary</h2>
          {methodology_html}
        </section>

        <section class="panel">
          <h2>Coverage Summary</h2>
          {coverage_html}
        </section>

        <section class="panel">
          <h2>Discovery Results</h2>
          {inventory_html}
        </section>

        <section class="panel">
          <h2>Adaptive Coverage</h2>
          {adaptive_pack_html}
        </section>

        <section class="panel">
          <h2>Adaptive Change Summary</h2>
          {adaptive_change_html}
        </section>
        """
    browser_title = title if variant == "summary" else f"{title} {run.id}"

    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <title>{escape(browser_title)}</title>
    <style>
      :root {{
        --ink: #1f2937;
        --muted: #4b5563;
        --line: #d1d5db;
        --panel: #ffffff;
        --panel-alt: #f8fafc;
        --accent: #9a3412;
      }}
      body {{
        font-family: "Segoe UI", "Helvetica Neue", sans-serif;
        font-size: 14px;
        line-height: 1.6;
        margin: 0 auto;
        max-width: 1100px;
        padding: 2rem 1.6rem 3rem;
        color: var(--ink);
        background: linear-gradient(180deg, #fffaf5 0%, #ffffff 10rem);
      }}
      h1, h2, h3 {{
        color: #111827;
      }}
      h1 {{
        margin-bottom: 0.25rem;
        font-size: 2rem;
      }}
      h2 {{
        margin: 0 0 0.85rem;
        padding-bottom: 0.45rem;
        border-bottom: 1px solid #e5e7eb;
        font-size: 1.12rem;
      }}
      h3 {{
        margin-top: 0;
      }}
      .lede {{
        color: var(--muted);
        margin: 0.2rem 0 0;
      }}
      .report-cover {{
        margin-bottom: 1.5rem;
      }}
      .report-context {{
        display: flex;
        flex-wrap: wrap;
        gap: 0.55rem;
        margin-top: 0.9rem;
      }}
      .context-chip {{
        display: inline-flex;
        gap: 0.3rem;
        align-items: center;
        padding: 0.38rem 0.65rem;
        border-radius: 999px;
        border: 1px solid #e5e7eb;
        background: #fcfcfd;
        color: #374151;
        font-size: 0.82rem;
      }}
      table {{
        border-collapse: collapse;
        width: 100%;
        margin-bottom: 1.5rem;
        background: var(--panel);
        table-layout: fixed;
      }}
      th, td {{
        border: 1px solid var(--line);
        padding: 0.65rem 0.75rem;
        text-align: left;
        vertical-align: top;
      }}
      th {{
        width: 14rem;
        background: #fcfcfd;
        color: #374151;
        font-weight: 600;
      }}
      tr:nth-child(even) td {{
        background: #fcfcfd;
      }}
      .panel {{
        border: 1px solid var(--line);
        padding: 1rem 1.25rem;
        margin-bottom: 1.15rem;
        border-radius: 0.75rem;
        background: var(--panel);
        box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
      }}
      .management-decision {{
        background: #f8fafc;
        border-color: #cbd5e1;
      }}
      .decision-grid {{
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
        gap: 0.75rem;
        margin: 0.85rem 0 1rem;
      }}
      .decision-grid div {{
        border: 1px solid #e2e8f0;
        border-radius: 0.65rem;
        padding: 0.75rem;
        background: #ffffff;
      }}
      .decision-grid strong {{
        display: block;
        color: #64748b;
        font-size: 0.72rem;
        letter-spacing: 0.06em;
        margin-bottom: 0.28rem;
        text-transform: uppercase;
      }}
      .decision-grid span {{
        color: #111827;
        font-weight: 600;
      }}
      .management-story {{
        background: #f8fbff;
        border-color: #c9def4;
      }}
      .management-risk-picture {{
        background: #f8fbff;
        border-color: #c9def4;
      }}
      .risk-picture-grid {{
        display: grid;
        grid-template-columns: 12rem 1fr;
        gap: 1rem;
        align-items: center;
      }}
      .risk-score-card {{
        min-height: 8rem;
        border-radius: 1rem;
        border: 2px solid #67c7f1;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        background: #ffffff;
      }}
      .risk-score-card span {{
        color: #64748b;
        text-transform: uppercase;
        font-size: 0.7rem;
        letter-spacing: 0.08em;
      }}
      .risk-score-card strong {{
        font-size: 1.8rem;
        color: #0f172a;
        margin: 0.15rem 0;
      }}
      .risk-score-card small {{
        color: #64748b;
      }}
      .risk-bar-row {{
        display: grid;
        grid-template-columns: 6rem 1fr 2rem;
        gap: 0.65rem;
        align-items: center;
        margin: 0.42rem 0;
      }}
      .risk-bar-row span {{
        color: #374151;
        font-weight: 700;
        font-size: 0.72rem;
        text-transform: uppercase;
      }}
      .risk-bar-track {{
        height: 0.7rem;
        border-radius: 999px;
        background: #e5e7eb;
        overflow: hidden;
      }}
      .risk-bar-fill {{
        height: 100%;
        border-radius: 999px;
      }}
      .risk-bar-row strong {{
        text-align: right;
      }}
      .standard-badge-grid {{
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
        gap: 0.75rem;
      }}
      .standard-badge-card {{
        border: 1px solid #dbe3ee;
        border-radius: 0.65rem;
        padding: 0.75rem;
        background: #ffffff;
      }}
      .standard-badge-card span {{
        display: inline-block;
        margin-bottom: 0.35rem;
        color: #1d4ed8;
        font-weight: 800;
        letter-spacing: 0.06em;
      }}
      .standard-badge-card strong {{
        display: block;
        color: #111827;
      }}
      .standard-badge-card small {{
        color: #64748b;
      }}
      .attack-map-route {{
        display: grid;
        grid-template-columns: repeat(5, 1fr);
        gap: 0.55rem;
        margin: 1rem 0 1.2rem;
      }}
      .attack-node {{
        position: relative;
        min-height: 6rem;
        border: 1px solid #b9d7f0;
        border-radius: 0.75rem;
        padding: 0.7rem;
        background: #ffffff;
      }}
      .attack-node::after {{
        content: "";
        position: absolute;
        top: 50%;
        right: -0.6rem;
        width: 0.6rem;
        border-top: 2px solid #67c7f1;
      }}
      .attack-node:last-child::after {{
        display: none;
      }}
      .attack-node span {{
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 1.35rem;
        height: 1.35rem;
        border-radius: 999px;
        background: #67c7f1;
        color: #082032;
        font-size: 0.72rem;
        font-weight: 700;
      }}
      .attack-node strong {{
        display: block;
        margin: 0.5rem 0 0.2rem;
        color: #0f172a;
      }}
      .attack-node small {{
        color: #475569;
      }}
      .attack-node-critical {{
        border-color: #dc2626;
      }}
      .attack-node-critical span {{
        background: #dc2626;
        color: #ffffff;
      }}
      .attack-node-high {{
        border-color: #ea580c;
      }}
      .attack-node-high span {{
        background: #ea580c;
        color: #ffffff;
      }}
      .attack-node-medium {{
        border-color: #d97706;
      }}
      .attack-node-medium span {{
        background: #d97706;
        color: #111827;
      }}
      .attack-node-good span {{
        background: #16a34a;
        color: #ffffff;
      }}
      .attack-node-outcome {{
        border-color: #7c3aed;
      }}
      .attack-node-outcome span {{
        background: #7c3aed;
        color: #ffffff;
      }}
      .technique-table span {{
        color: #64748b;
        font-size: 0.78rem;
      }}
      .technique-table th {{
        width: auto;
      }}
      .scope-grid {{
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr));
        gap: 1rem;
      }}
      .finding, .task {{
        border: 1px solid var(--line);
        padding: 1rem 1.25rem;
        margin-bottom: 1rem;
        border-radius: 0.75rem;
        background: var(--panel);
      }}
      .finding-header {{
        display: flex;
        align-items: baseline;
        justify-content: space-between;
        gap: 1rem;
      }}
      .finding p,
      .task p {{
        margin: 0.38rem 0;
      }}
      .priority {{
        color: var(--accent);
        font-weight: 700;
        padding: 0.26rem 0.55rem;
        border-radius: 999px;
        border: 1px solid #fdba74;
        background: #fff7ed;
        font-size: 0.8rem;
      }}
      code, pre {{
        background: var(--panel-alt);
        border-radius: 0.5rem;
        overflow-wrap: anywhere;
        word-break: break-word;
      }}
      code {{
        padding: 0.1rem 0.3rem;
        font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
      }}
      pre {{
        padding: 0.85rem;
        overflow-x: auto;
        white-space: pre-wrap;
        line-height: 1.5;
      }}
      ul, ol {{
        padding-left: 1.1rem;
      }}
      .meta-list li {{
        margin-bottom: 0.35rem;
      }}
    </style>
  </head>
  <body>
    <header class="report-cover pdf-cover">
      <h1>{escape(title)}</h1>
      <p class="lede">{escape(report_lede)}</p>
      <div class="report-context">{report_context_html}</div>
    </header>

    {report_header_html}

    <section class="panel">
      <h2>Summary</h2>
      <table>{summary_html}</table>
      <h3>By Severity</h3>
      {_format_count_map_html(findings_by_severity)}
      <h3>By Status</h3>
      {_format_count_map_html(findings_by_status)}
    </section>

    {test_coverage_section_html}
    {executive_panel}
    {technical_detail_sections_html}

    {findings_section}
    {rationale_ledger_section}
    {evidence_section}
    {verification_section}
    <footer class="panel">
      <p>{escape(REPORT_DISCLAIMER)}</p>
    </footer>
  </body>
</html>
"""
